// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 치유
// 요리사 · 치유사 · 약사 · 의원 · 수도사
// ==========================================

// ------------------------------------------
// 요리사 (cook) · 자원 없음
// ------------------------------------------
kJob('cook', 'A', [

{ at:'A', t:'쉬는 자리 — 냄새가 가는 곳',
  x:`문 닫힌 방에 들어와 겨우 앉았다. 다들 허기져 있다.<br><br>
    익히면 냄새가 난다. 냄새는 문틈으로 나간다. 여기서는 문틈 너머에 냄새를 맡는 것이 있다.<br>
    부엌에서 오래 산 손은 냄새가 어디로 가는지 안다. 김은 위로 오르고 기름 냄새는 아래로 깔린다.<br><br>
    문 밑 틈으로 바람이 들어온다. 들어오는 바람이 있으면 나가는 바람도 있다.`,
  o:[
    { l:'① 기름 없이 물에만 익힌다.', k:'fix', dc:21, wake:1,
      ok:`말린 고기를 기름 없이 물에 넣었다. 뚜껑을 덮고 불을 낮췄다. 김이 뚜껑 안에 맺혀 도로 떨어진다.<br><br>냄새가 솥 밖으로 거의 안 나온다. 다들 뚜껑을 열 때만 냄새를 맡았다. 한 숟갈씩. 문 밑 틈은 조용했다.<br><br>냄새를 가두는 솥. 불을 줄이는 법이 아니라 냄새를 줄이는 법을 손이 알았다. 같은 손의 다른 일이다.`,
      ng:`뚜껑이 들썩인다. 김이 한 줄기 새어 나간다. 문 밑 틈으로.<br><br>틈 밖에서 코를 킁킁대는 소리가 난다. 아주 가까이. 문짝에 얼굴을 비비는 소리.<br>다들 숟가락을 든 채 굳었다. 소리가 멀어질 때까지 한 시간을 그러고 있었다. 국은 식었다.`,
      win:{ exp:20, dream:3, hp:8 }, lose:{ mind:-16, spirit:-20 } },
    { l:'② 불을 끄고 날것을 얇게 저며 나눈다.', k:'heal', dc:22,
      ok:`불을 껐다. 말린 고기를 얇게 저며 소금 한 톨씩 얹었다. 날것도 저미면 넘어간다. 얇을수록.<br><br>다들 말없이 씹었다. 배가 반쯤 찬다. 반이면 걷는다.<br>틈 너머로 냄새를 찾던 것이 지나갔다. 찾지 못하고.`,
      ng:`저미다 칼이 미끄러졌다. 손가락이 깊게 베였다.<br><br>피 냄새는 익힌 냄새보다 멀리 간다. 문 밑 틈에서 바람이 거꾸로 분다. 들이마시는 쪽으로.<br>손을 천으로 감아 쥐고 다들 숨을 죽였다. 틈 밖의 것이 아침까지 문 앞에 앉아 있었다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'A', t:'복도 — 밥 먹으라는 소리',
  x:`복도 끝에서 목소리가 난다. 밥 먹어라.<br><br>
    어른 목소리다. 집집마다 저녁 무렵에 나던 소리다.<br>
    부엌에서 일해 본 사람은 그 목소리가 어떤 상을 차려 놓고 부르는지 안다. 국이 식기 전에 부르는 목소리다.<br><br>
    그런데 냄새가 없다. 국을 끓였다면 냄새가 먼저 와야 한다.`,
  o:[
    { l:'① 냄새가 없다고 일행에게 낮게 말한다.', k:'sense', dc:21,
      ok:`일행을 붙잡고 낮게 말했다. 상을 차린 집은 냄새부터 난다. 냄새 없는 밥은 밥이 아니다.<br><br>다들 고개를 끄덕인다. 그런데 하나가 고개를 끄덕이며 복도 끝을 본다. 발끝이 그쪽을 향해 있다.<br>그 사람 소매를 쥐고 반대쪽으로 걸었다. 목소리가 등 뒤에서 한 번 더 부른다. 이번엔 그 사람 이름으로.`,
      ng:`말하려는데 이쪽 배가 먼저 운다. 꼬르륵. 크게.<br><br>복도 끝 목소리가 멈춘다. 그리고 웃는다. 배고프구나.<br>그 뒤로 한참 그 목소리가 이쪽 배 소리를 흉내 냈다. 꼬르륵. 바로 등 뒤에서.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 복도 한가운데 국 한 그릇을 떠 놓고 지나간다.', k:'bond', dc:22,
      ok:`솥에 남은 국을 한 그릇 떠서 복도 한가운데 놓았다. 김이 오른다. 냄새가 복도 끝으로 간다.<br><br>목소리가 멈췄다. 한참 뒤에 그릇 긁는 소리가 난다. 숟가락이 아니다. 손톱이다.<br>그 소리가 나는 동안 옆 계단으로 다 지나갔다. 부르는 쪽도 먹으면 조용해진다.`,
      ng:`그릇을 놓는데 목소리가 바로 앞에서 난다. 거기 놓으면 안 되지. 상에 놓아야지.<br><br>그릇이 저절로 미끄러진다. 복도 끝 쪽으로. 국이 바닥에 길게 흘렀다.<br>흘린 자국을 밟지 않으려고 벽에 붙어 걸었다. 자국은 일행 발치까지 따라왔다.`,
      win:{ exp:18, dream:3 }, lose:{ hp:-22, spirit:-20 } },
    { l:'③ 남은 것이라도 있을까 목소리 쪽으로 간다.', k:'luck', dc:23,
      doom:{ title:'저녁상', what:'목소리에 손목을 잡혀 복도 끝으로 끌려갑니다', dc:18, sec:50,
        text:`목소리 쪽으로 걸었다. 차려진 상이라면 남은 것이 있다. 부엌 사람은 남은 것을 그냥 못 둔다.<br><br>복도 끝에 둥근 밥상이 있다. 밥그릇 다섯이 엎어져 있다. 엎은 그릇은 다 먹은 그릇이다.<br>여섯째 그릇만 바로 놓였다. 비었다. 뒤에서 손이 손목을 쥔다. 차다. 앉아야지. 밥 먹어야지.<br><br>무릎이 꺾인다. 상 앞으로 끌려간다. 숟가락이 손에 쥐여진다. 빈 그릇을 뜨라고.`,
        dieText:`복도 끝 둥근 상에 엎은 그릇이 여섯이 됐다.<br><br>다 먹은 것이다. 목소리가 다시 부른다. 밥 먹어라.<br>이번엔 일곱째 그릇이 바로 놓여 있다.` },
      ok:`복도 끝에 둥근 상이 있다. 밥그릇 다섯이 엎어져 있다. 여섯째만 바로 놓였다. 비었다.<br><br>상에는 다가서지 않았다. 상 밑만 봤다. 상다리 사이에 소금 자루가 하나 있다. 부엌이 남긴 것이다.<br>자루를 끌어 왔다. 등 뒤에서 아쉬운 목소리가 난다. 밥 먹고 가지.`,
      win:{ exp:22, dream:3, item:'소금 덩이' } }
  ] },

{ at:'A', t:'계단 — 맛이 안 난다는 사람',
  x:`쉬는 자리에서 국을 돌렸다. 하나가 숟가락을 내려놓는다.<br><br>
    아무 맛이 안 난다고 한다. 짠맛도, 뜨거운 것도 모르겠다고 한다.<br>
    먹는 것을 오래 다룬 사람은 안다. 혀가 먼저 떠나는 사람이 있다. 몸은 남고.<br><br>
    그 사람 눈이 자꾸 계단 위를 본다. 거기서 누가 이름을 부른다고 했다. 아무도 못 들었다.`,
  o:[
    { l:'① 소금을 혀에 직접 얹어 준다.', k:'heal', dc:22, wake:1,
      ok:`소금 덩이를 손톱만큼 떼어 그 사람 혀에 올렸다. 입을 다물게 하고 기다렸다.<br><br>한참 있다가 얼굴이 찡그려진다. 짜다고 한다. 눈에 물이 고인다. 짠 걸 아는 혀는 아직 이쪽 혀다.<br>국을 다시 떠 주었다. 이번엔 다 먹었다. 계단 위를 보지 않는다.<br><br>먹이는 것으로 사람을 붙잡아 둘 수 있다. 맛이 줄이 된다. 그 줄을 쥐는 법을 손이 처음 알았다.`,
      ng:`소금을 올렸는데 표정이 그대로다. 짜지 않다고 한다.<br><br>한 덩이를 다 올렸다. 그래도 그대로다. 그 사람이 웃는다. 계단 위에서 부르는 소리가 더 잘 들린다고.<br>그 사람 허리띠를 이쪽 허리띠에 묶었다. 밤새.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마지막으로 맛있게 먹은 것을 묻는다.', k:'bond', dc:21,
      ok:`마지막으로 맛있던 게 뭐냐고 물었다. 한참 생각한다. 어릴 때 먹던 무엇이라고 한다. 들기름 냄새가 났다고.<br><br>기름은 없다. 말린 고기를 달군 돌에 구워 기름을 냈다. 비슷한 냄새가 난다.<br>그 사람이 코를 킁킁댄다. 이 냄새, 하고 울먹인다. 냄새를 따라 돌아온 것이다.`,
      ng:`묻자 그 사람이 대답한다. 아까 계단 위에서 먹었다고.<br><br>무엇을 먹었냐니 기억이 안 난다고 한다. 맛있었다고만 한다. 입가에 검은 것이 묻어 있다.<br>닦아 주었다. 닦은 천이 차다. 그 사람 입술보다 차다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 쓰러뜨린 것의 살',
  x:`일행이 무언가를 쓰러뜨렸다. 길을 막던 것이다.<br><br>
    털이 있고 다리가 넷이다. 그 이상은 등잔으로 비추고 싶지 않다.<br>
    사흘째 말린 것만 먹었다. 다들 이쪽을 본다. 먹을 수 있는지는 부엌 사람이 정한다.<br><br>
    살 냄새가 난다. 짐승 냄새다. 아마도.`,
  o:[
    { l:'① 결을 갈라 먹을 수 있는 데만 뗀다.', k:'gaze', dc:22,
      ok:`칼로 등 쪽부터 갈랐다. 결을 봤다. 엉덩이와 등심은 짐승 결이다. 앞다리는 아니다. 앞다리 결은 사람 손목처럼 꼬여 있다.<br><br>앞쪽은 건드리지 않았다. 뒤쪽만 떼어 싸 두었다.<br>다들 앞다리를 묻지 않았다. 이쪽도 말하지 않았다.`,
      ng:`가르는데 결이 중간에 바뀐다. 짐승 결이 다른 결로. 칼끝이 그 경계에서 멈췄다.<br><br>손이 떨려 칼을 놓쳤다. 쓰러진 것의 앞발이 칼 쪽으로 오므라든다. 아직 덜 죽었다.<br>다들 뒷걸음질 쳤다. 그날 아무도 먹지 않았다.`,
      win:{ exp:18, dream:2, item:'짐승 고기' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 뼈째 오래 삶아 피를 다 뺀다.', k:'heal', dc:21, wake:1,
      ok:`토막 낸 것을 찬물에 담가 피를 뺐다. 물을 세 번 갈았다. 셋째 물도 붉다. 넷째에 맑아졌다.<br><br>오래 삶았다. 거품을 걷었다. 거품에 섞여 머리카락이 떠올랐다. 그것도 걷었다.<br>국물이 맑아지자 맛을 봤다. 짐승 맛이다. 그것만 남을 때까지 끓였다.<br><br>무엇을 먹는지 모를 때는 무엇이 아닌 것을 다 덜어 내면 된다. 덜어 내는 손이 손 하나 몫만큼 늘었다.`,
      ng:`피가 안 빠진다. 물을 갈아도 갈아도 붉다.<br><br>여덟째 물에서 손을 뺐다. 손등에 붉은 물이 스며 지워지지 않는다.<br>솥을 엎었다. 엎은 자리 바닥이 한동안 미지근했다.`,
      win:{ exp:22, dream:3, hp:8, item:'짐승 고기' }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A', t:'빈방 — 불 없이 끓는 솥',
  x:`빈방에 화덕이 있다. 솥이 끓고 있다. 불은 없다.<br><br>
    뚜껑이 들썩인다. 김에서 냄새가 난다. 고깃국이다. 간이 맞는 냄새다.<br>
    솥을 다뤄 본 손은 안다. 이만큼 끓인 국은 누가 몇 시간을 지킨 국이다.<br><br>
    지킨 사람은 없다. 솥 옆에 국자가 걸려 있다. 손잡이가 축축하다.`,
  o:[
    { l:'① 문가에서 냄새로 무엇을 넣었는지 가려낸다.', k:'sense', dc:21,
      ok:`문가에서 맡았다. 뼈, 무, 대파. 그다음에 단내. 끝에 쇠 맛.<br><br>쇠 맛은 냄비 맛이 아니다. 피 맛이다. 국 끓인 쪽이 뭘 넣었는지 알 만했다.<br>솥은 건드리지 않았다. 화덕 옆 바구니만 가져왔다. 다듬어 둔 산나물이 한 줌. 이건 넣기 전 것이다.`,
      ng:`맡을수록 좋다. 침이 고인다. 다리가 솥 쪽으로 간다.<br><br>정신을 차리니 국자를 쥐고 있다. 국자 손잡이가 이쪽 손 모양으로 패어 있다. 처음부터.<br>국자를 떨어뜨렸다. 쨍. 솥 안에서 무언가가 그 소리에 돌아눕는다.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 화덕 재를 끌어내 솥을 식힌다.', k:'fix', dc:22,
      ok:`불이 없는데 끓는다면 화덕 밑이 문제다. 재를 끌어냈다. 재 밑에 숯이 빨갛다. 언제부터 타는지 모르는 숯이다.<br><br>숯을 다 끌어내 물을 끼얹었다. 치익. 솥이 잦아든다. 들썩이던 뚜껑이 내려앉는다.<br>내려앉은 뚜껑 밑에서 한숨 소리가 난다. 길고 편하게. 다 끓었다는 소리다.`,
      ng:`재를 끌어내자 숯이 튄다. 팔뚝에 붙었다. 살이 탄다.<br><br>솥은 오히려 더 끓는다. 국이 넘친다. 넘친 국이 바닥을 타고 이쪽 발로 온다.<br>뜨겁지 않다. 차다. 그래서 더 빨리 피했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'③ 국자로 뚜껑을 밀어 안을 본다.', k:'gaze', dc:23,
      doom:{ title:'끓는 솥', what:'솥의 김에 숨이 막힙니다', dc:18, sec:45,
        text:`국자로 뚜껑을 밀었다. 김이 한꺼번에 오른다. 얼굴을 덮는다.<br><br>김이 뜨겁지 않다. 젖은 천 같다. 코와 입에 달라붙는다. 숨을 쉬면 김이 들어오고 내쉬면 안 나간다.<br>솥 안을 봤다. 국물 위에 얼굴이 떠 있다. 눈을 감고. 국물 맛을 보는 얼굴이다.<br><br>그 얼굴이 입을 연다. 김을 들이마신다. 이쪽 숨과 같은 박자로.`,
        dieText:`솥은 계속 끓었다.<br><br>국물 위 얼굴이 둘이 됐다. 하나는 아직 덜 익었다.<br>국자 손잡이가 다시 축축해졌다.` },
      ok:`뚜껑을 열기 전에 젖은 천으로 코와 입을 감았다. 그리고 국자 끝으로 살짝 밀었다.<br><br>김이 오른다. 천에 달라붙는다. 무겁다. 천을 벗겨 던지자 천이 바닥에서 한참 꿈틀댔다.<br>솥 안은 보지 않았다. 솥 옆 소금 단지만 들고 나왔다. 간이 맞는 국을 끓인 소금이다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' } }
  ] },

{ at:'A', t:'쉬는 자리 — 그릇 하나가 남는다',
  x:`국을 다 끓였다. 그릇을 늘어놓았다. 일행 수만큼.<br><br>
    떠서 돌렸다. 다 돌리고 나니 그릇 하나가 남았다. 국이 담긴 채로.<br>
    몇 번을 세어도 일행은 맞다. 그릇이 하나 많다. 늘어놓을 때도 셌다.<br><br>
    남은 그릇에서 김이 오른다. 김이 옆으로 기운다. 누가 후후 부는 것처럼.`,
  o:[
    { l:'① 그릇을 거두고 이름을 불러 다시 나눈다.', k:'fix', dc:22, wake:1,
      ok:`그릇을 다 거두고 처음부터 나눴다. 국자를 들고 한 사람씩 이름을 불렀다. 대답하면 한 그릇.<br><br>대답이 하나 더 나왔다. 일행 목소리 사이에. 그 자리엔 아무도 없다. 그 그릇은 바닥에 쏟았다.<br>다시 셌다. 이번엔 맞는다. 쏟은 자리 바닥이 꿈틀하다 잠잠해졌다.<br><br>밥을 나누는 손은 원래 머릿수를 안다. 이제는 머릿수가 아닌 것도 안다. 국자가 세는 법이 하나 늘었다.`,
      ng:`세는데 세는 동안 바뀐다. 다섯, 여섯, 다섯.<br><br>일행 얼굴을 하나씩 봤다. 다 아는 얼굴이다. 그런데 하나가 국을 안 마신다. 김만 들이마신다.<br>누군지 끝내 못 가렸다. 밤새 등을 벽에 붙이고 앉아 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 남은 그릇을 문밖에 내놓는다.', k:'bond', dc:21,
      ok:`남은 그릇을 두 손으로 들어 문밖에 내놓았다. 문을 닫았다.<br><br>문밖에서 마시는 소리가 난다. 후루룩. 그리고 그릇을 내려놓는 소리. 공손하게.<br>아침에 문을 여니 그릇이 비어 있다. 그릇 안에 말린 버섯이 한 줌 담겨 있다. 답례다.`,
      ng:`그릇을 내놓는데 문밖에 손이 먼저 와 있다. 그릇이 아니라 이쪽 손목을 받는다.<br><br>뿌리치다 국이 쏟아졌다. 손등이 데었다. 국 때문이 아니다. 손목을 쥔 그 손이 데게 했다.<br>문을 닫고 등으로 막았다. 문 너머가 한참 그릇을 찾았다.`,
      win:{ exp:18, dream:2, item:'야생 버섯' }, lose:{ hp:-24, spirit:-20 } },
    { l:'③ 남기면 안 되니 이쪽이 마신다.', k:'steady', dc:23,
      doom:{ title:'남은 그릇', what:'그릇 주인에게 앉은 채 끌려갑니다', dc:18, sec:50,
        text:`남은 그릇을 들어 마셨다. 남기는 건 부엌의 일이 아니다.<br><br>국이 미지근하다. 누가 입을 댔던 온도다. 다 마셨을 때 어깨에 손이 얹힌다. 그거 내 거야.<br>돌아보지 못했다. 어깨의 손이 이쪽을 끌어당긴다. 앉은 그대로 바닥을 미끄러진다. 방 어두운 구석 쪽으로. 그릇은 아직 손에 있다.<br><br>일행이 국자를 든 채 이쪽을 본다. 그릇 수를 세는 눈이다.`,
        dieText:`다음 끼니에 그릇을 늘어놓았다. 일행 수만큼.<br><br>돌리고 나니 이번에도 하나가 남았다. 국이 담긴 채로.<br>김이 옆으로 기운다. 후후 부는 박자가 이쪽 사람 버릇이다.` },
      ok:`마시려다 그릇 가장자리를 봤다. 입 댄 자국이 있다. 국물 기름이 입술 모양으로 굳었다.<br><br>남의 그릇이다. 내려놓았다. 대신 이쪽 그릇의 국을 반 덜어 그 그릇에 보탰다. 가득 채워 주었다.<br>그릇이 아주 조금 밀린다. 고맙다는 듯. 그 뒤로 아무도 어깨를 짚지 않았다.`,
      win:{ exp:20, dream:3, spirit:8 } }
  ] },

{ at:'A', t:'통로 — 핥은 벽',
  x:`통로 벽 한 군데가 하얗다. 핥은 자국이 있다. 여러 혀가.<br><br>
    소금이 배어 나온 벽이다. 부엌 사람은 이런 벽을 안다. 짠물이 오래 고였던 자리다.<br>
    벽 밑에 신발 자국이 몰려 있다. 다 벽을 향해 있다.<br><br>
    소금은 귀하다. 여기 것들도 아는 모양이다.`,
  o:[
    { l:'① 칼등으로 쳐서 덩이째 떼어 낸다.', k:'break', dc:22,
      ok:`칼등으로 쳐서 덩이를 뗐다. 두 덩이. 하얗고 단단하다.<br><br>뗀 자리 안쪽이 축축하다. 소금 밑에 아직 짠물이 돈다. 벽이 숨 쉬는 박자로 배어 나온다.<br>더 떼지 않았다. 핥으러 오는 것들 몫도 남아야 길을 안 막는다.`,
      ng:`치는데 벽이 울린다. 통로 끝까지.<br><br>통로 저편에서 무언가가 기어 온다. 혀를 내밀고. 벽을 핥으며 다가온다. 하얀 자국을 따라.<br>떼던 덩이를 버리고 뛰었다. 등 뒤에서 핥는 소리가 이쪽 발자국을 따라 바닥으로 옮겨 왔다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 혀끝에 대 보고 쓸 소금인지 가린다.', k:'sense', dc:21,
      ok:`손톱으로 긁어 혀끝에 댔다. 짜다. 그다음 쓰다. 쓴 소금은 간수가 덜 빠진 것이다.<br><br>간수는 끓이면 날아간다. 긁어모아 천에 싸 두었다. 끓이면 쓸 만하다.<br>혀끝에 남은 쓴맛이 오래 갔다. 벽 앞의 신발 자국들이 왜 거기서 멈췄는지 조금 알 것 같았다.`,
      ng:`혀를 대자 짜다. 그리고 미지근하다. 벽이 아니라 살갗 온도다.<br><br>벽이 혀를 마주 핥는다. 젖은 것이 혀끝을 감는다. 혀를 빼는데 끈적하다.<br>입을 한참 헹궜다. 그날 무엇을 먹어도 소금 맛만 났다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ mind:-16, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 칼 가는 소리',
  x:`어둠 저편에서 칼 가는 소리가 난다. 스윽, 스윽.<br><br>
    숫돌에 물을 묻혀 가는 소리다. 고르다. 손에 익은 쪽이 간다.<br>
    부엌 사람은 그 소리를 들으면 칼이 무엇을 위한 칼인지 안다. 길게 갈면 저미는 칼이고 짧게 갈면 뼈 칼이다.<br><br>
    길게 간다. 얇게 저밀 것이 있다는 뜻이다.`,
  o:[
    { l:'① 이쪽 칼도 같은 박자로 갈며 지나간다.', k:'hide', dc:22,
      ok:`숫돌을 꺼냈다. 저쪽 박자에 맞춰 갈았다. 스윽, 스윽. 소리가 겹친다.<br><br>겹친 소리는 하나로 들린다. 저쪽은 이쪽이 있는 줄 모른다. 그 소리에 묻혀 일행이 지나갔다.<br>마지막으로 일어서는데 저쪽 박자가 한 번 어긋난다. 잠깐 멈춘다. 그리고 다시 간다. 이쪽 박자로.`,
      ng:`박자를 맞추는데 저쪽이 멈춘다. 이쪽 소리만 남았다. 스윽.<br><br>어둠에서 대답이 온다. 잘 가네.<br>칼을 거두고 다 같이 뛰었다. 등 뒤에서 숫돌 소리가 다시 시작됐다. 더 빠르게.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 소리 쪽으로 다가가 도마를 본다.', k:'gaze', dc:23,
      ok:`벽을 따라 다가갔다. 등잔은 끄고. 소리가 커진다.<br><br>도마가 있다. 도마 위에 고기가 없다. 저밀 것이 아직 안 왔다. 칼 가는 손만 보인다. 팔꿈치 위가 없다.<br>도마 옆에 소금에 절인 생선이 한 줄 걸려 있다. 손이 칼만 보는 사이 한 마리를 뗐다. 손은 끝까지 칼만 봤다.`,
      ng:`다가가자 소리가 멈춘다. 도마가 보인다. 도마 위가 비었다.<br><br>칼이 이쪽을 향한다. 칼끝이 이쪽 팔뚝을 가볍게 짚는다. 치수를 재듯이. 손목에서 팔꿈치까지.<br>물러났다. 팔뚝에 가는 금이 그어져 있다. 피가 늦게 배어 나온다.`,
      win:{ exp:20, dream:3, item:'민물고기' }, lose:{ hp:-28, spirit:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 불려 가는 동료',
  x:`밤에 하나가 일어나 앉는다. 눈은 감았다.<br><br>
    누가 부른다고 한다. 가야 한다고 한다. 신발을 찾는다.<br>
    붙잡아도 힘이 세다. 잠든 사람 힘이 아니다.<br><br>
    요리사가 아는 것은 하나다. 배를 채운 사람은 쉽게 안 일어난다. 따뜻한 것이 배에 있으면 몸이 자리를 지킨다.`,
  o:[
    { l:'① 뜨거운 국물을 한 숟갈씩 입에 흘려 넣는다.', k:'heal', dc:22, wake:1,
      ok:`솥을 다시 불에 올렸다. 국물을 한 숟갈씩 식혀 입술 사이로 흘렸다. 한 숟갈. 또 한 숟갈.<br><br>넘어간다. 목이 울컥 움직인다. 다섯 숟갈째에 몸에서 힘이 빠진다. 신발 찾던 손이 내려온다.<br>배가 데워진 몸이 도로 눕는다. 부르는 쪽이 한참 기다리다 그쳤다.<br><br>국물 한 숟갈로 사람을 자리에 앉혔다. 먹이는 일이 붙드는 일이 됐다. 손이 그걸 잊지 않을 것이다.`,
      ng:`흘려 넣는데 안 넘어간다. 입가로 다 흐른다.<br><br>그 사람이 일어선다. 문 쪽으로. 셋이 매달려 겨우 눕혔다. 입가의 국물이 얼어 있다.<br>아침에 깨어 아무것도 기억 못 한다. 배고프다고만 한다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 신발을 솥 밑에 감추고 곁을 지킨다.', k:'steady', dc:21,
      ok:`신발을 솥 밑에 감췄다. 그 사람 곁에 앉았다.<br><br>밤새 신발을 찾는다. 바닥을 더듬는다. 솥 밑까지는 손이 안 간다. 뜨거운 데는 안 간다.<br>새벽에 지쳐 잠들었다. 그 사람 손끝에 그을음이 묻어 있다. 솥 근처까지는 왔었다.`,
      ng:`신발을 감췄더니 맨발로 일어선다.<br><br>문까지 가서야 붙잡았다. 문틈으로 차가운 손가락 끝이 나와 그 사람 발등을 짚고 있었다.<br>떼어 놓는데 그 사람 발등에 손가락 자국 넷이 하얗게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-24 } }
  ] },

{ at:'A', t:'마지막 쉼 — 어디서 난 것인가',
  x:`내려가기 전, 마지막 쉼이다. 가방을 털었다.<br><br>
    주워 모은 것이 늘어선다. 무엇은 짐승 것이고 무엇은 땅에서 났다. 몇은 이 안에서 난 것이다.<br>
    이 안에서 난 것은 먹어도 되는지 끝까지 모른다.<br><br>
    다들 지쳤다. 따뜻한 것이 필요하다.`,
  o:[
    { l:'① 이 안의 것은 빼고 바깥 것만 끓인다.', k:'heal', dc:21, wake:1,
      ok:`하나씩 집어 골랐다. 바깥에서 들고 온 것, 바깥 것과 같은 것. 나머지는 옆으로 밀었다.<br><br>솥이 반밖에 안 찬다. 물을 늘리고 소금을 아꼈다. 묽다. 대신 무엇이 들었는지 다 안다.<br>다들 다 마셨다. 아무도 꿈을 꾸지 않았다.<br><br>아는 것만 넣는 솥. 모자라도 탈 없는 한 끼. 고르는 손이 전보다 단호해졌다. 망설임이 줄었다.`,
      ng:`고르다 보니 다 의심스럽다. 바깥 것도 여기 오래 있었다.<br><br>결국 반도 안 넣었다. 국이 맹물 같다. 다들 마시고 배를 문지른다.<br>허기는 그대로다. 허기진 사람은 부르는 소리를 더 잘 듣는다.`,
      win:{ exp:22, dream:3, hp:10 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 전부 넣고 오래 끓인다.', k:'luck', dc:23,
      ok:`다 넣었다. 오래 끓였다. 무엇이든 오래 끓이면 맛이 하나로 모인다.<br><br>맛을 봤다. 괜찮다. 한 숟갈 더 봤다. 괜찮다.<br>솥 바닥에 버섯 하나가 끝까지 안 풀어졌다. 건져 보니 갓이 사람 손톱 같다. 그것만 버렸다. 다 끓인 뒤에.`,
      ng:`끓이는데 솥 안이 소리를 낸다. 낮게. 여럿이.<br><br>국물 위로 거품이 오른다. 거품마다 작은 얼굴이 하나씩. 터질 때마다 한숨이 난다.<br>솥째 버렸다. 다들 굶었다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A1', t:'탕비실 — 돌아가는 도시락',
  x:`탕비실 전자레인지가 돌고 있다. 웅. 안에 불이 켜져 있다.<br><br>
    도시락이 돈다. 뚜껑에 이름이 적혀 있다. 언니. 노래하던 언니다.<br>
    남은 시간 칸 숫자가 줄어든다. 영 바로 앞에서 다시 처음으로 돌아간다.<br><br>
    몇 해를 데운 밥 냄새가 아니다. 갓 지은 냄새다.`,
  o:[
    { l:'① 문은 두고 전깃줄을 따라가 본다.', k:'fix', dc:22,
      ok:`전자레인지 뒤로 손을 넣었다. 플러그가 꽂혀 있지 않다. 선 끝이 벽 틈으로 들어간다. 벽 안쪽이 따뜻하다.<br><br>선을 따라 벽 틈을 열자 찬장 뒤 칸이 나온다. 직원들이 숨겨 둔 비상 먹거리다. 꿀 단지와 말린 고기. 날짜는 문 닫기 전이다.<br>챙겨 나오는데 띵, 하고 운다. 아무도 꺼내 가지 않는다. 숫자가 다시 처음으로.`,
      ng:`선을 당겼다. 벽 안쪽에서 마주 당긴다.<br><br>전자레인지가 쿵 하고 벽으로 끌려 붙는다. 그 바람에 문이 열렸다. 도시락이 바닥에 쏟아진다. 밥알마다 작은 해 모양 도장이 찍혀 있다.<br>밟지 않으려다 넘어졌다. 손바닥에 밥알이 붙었다. 떼어도 도장 자국이 남는다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 숫자가 영이 되는 순간 문을 연다.', k:'luck', dc:21,
      ok:`숫자가 영이 되는 순간 문을 열었다. 띵.<br><br>도시락이 뜨겁다. 밥과 나물무침, 달걀말이. 갓 한 것이다. 냄새도 맞다.<br>먹지는 않았다. 나물만 덜어 싸 두었다. 남의 도시락은 남의 것이다. 뚜껑을 덮어 냉장고에 넣었다. 다음에 데울 수 있게.`,
      ng:`문을 여는데 띵 소리가 끝나지 않는다. 띠이이이.<br><br>소리에 맞춰 복도 끝에서 슬리퍼 소리가 온다. 내 도시락 먹지 마.<br>도시락을 놓고 식탁 밑으로 들어갔다. 슬리퍼가 식탁 앞에 오래 서 있었다. 발끝이 이쪽을 향해서.`,
      win:{ exp:16, dream:2, item:'산나물' }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A1', t:'스튜디오 — 방글이의 요리 교실',
  x:`세트 한쪽에 부엌이 있다. 「방글이의 요리 교실」. 반쪽짜리 부엌이다. 카메라 쪽 벽이 없다.<br><br>
    가스레인지 위에 냄비. 도마 위에 플라스틱 채소와 플라스틱 칼. 고리에 아이 크기 앞치마가 걸려 있다.<br>
    무대 감독이 카드를 들고 서 있다. 카드에 적혀 있다. 오늘의 요리사 — 앞으로.<br><br>
    냄비 안에서 뭔가 끓는다. 가스는 안 켜졌다. 끓는 소리는 진짜다.`,
  o:[
    { l:'① 앞치마를 매고 냄비를 맡는다.', k:'heal', dc:23,
      doom:{ title:'요리 교실', what:'앞치마 끈에 묶여 카메라 앞으로 끌려갑니다', dc:18, sec:50,
        text:`앞치마를 맸다. 아이 크기라 끈이 모자란다. 끈이 저절로 늘어나 허리를 두 바퀴 감는다.<br><br>조명이 켜진다. 카메라에 빨간 불이 들어온다. 스피커에서 박수. 앞치마 끈이 앞으로 당긴다. 벽이 없는 쪽으로.<br>냄비 뚜껑이 열린다. 안에서 하얀 장갑이 국자를 쥐고 나온다. 손가락이 넷이다. 이쪽 손에 국자를 쥐여 준다.<br><br>무대 감독이 카드를 뒤집는다. 맛있게 웃어요.`,
        dieText:`다음 날 다섯 시, 요리 교실 코너가 나갔다.<br><br>앞치마 입은 아이가 냄비를 젓는다. 키가 조금 크다. 웃는 입이 얼굴보다 길다.<br>요리가 다 되자 아이가 카메라를 향해 국자를 내민다. 국자 안에 아무것도 없다.` },
      ok:`앞치마를 손에 들기만 하고 매지 않았다. 끈이 손목을 더듬다 놓친다.<br><br>냄비 뚜껑은 플라스틱 칼끝으로 밀었다. 안에서 끓는 건 물이다. 진짜 물. 바닥에 소금 덩이가 녹다 말았다. 끓는 소리는 소금이 내는 것이다.<br>소금을 건져 세트 뒤로 나왔다. 무대 감독은 끝까지 카메라만 봤다. 카드가 바뀌었다. 다음 시간에.`,
      win:{ exp:22, dream:3, item:'소금 덩이' } },
    { l:'② 세트 냉장고 칸에서 진짜 재료만 고른다.', k:'sense', dc:22,
      ok:`세트 냉장고는 문짝만 있다. 그런데 안에 칸이 있다. 손을 넣어 하나씩 눌렀다. 단단한 건 가짜, 들어가는 건 진짜.<br><br>진짜 버섯 한 줌. 요리 교실에서 쓰려고 넣어 둔 것이다. 말라서 오히려 오래갔다.<br>냉장고 문을 닫는데 안에서 누가 맞잡아 닫아 준다. 살살.`,
      ng:`누르다가 하나가 손가락을 마주 눌러 온다.<br><br>손가락 넷. 하얀 천이다. 장갑이 냉장고 안에 접혀 들어 있었다. 이쪽 손가락을 하나씩 접는다. 주먹을 쥐게.<br>뺐다. 손가락 마디마다 천 냄새가 배었다. 씻어도 안 빠진다.`,
      win:{ exp:18, dream:2, item:'야생 버섯' }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 플라스틱 칼로 감독의 카드를 가린다.', k:'hide', dc:22,
      ok:`플라스틱 칼을 들고 카드 앞을 지나갔다. 칼날을 카드 앞에 세웠다. 글씨가 가려진다.<br><br>무대 감독이 카드를 내려다본다. 읽을 수 없는 카드다. 한참 고개를 갸웃한다.<br>그사이 일행이 세트 뒤로 빠졌다. 감독이 새 카드를 꺼낸다. 광고 시간.`,
      ng:`칼을 세우는데 감독이 카드를 돌려 이쪽에 보인다.<br><br>오늘의 요리사 밑에 이름 칸이 있다. 이쪽 이름이 크레용으로 적혀 있다.<br>카드에서 눈을 떼지 못했다. 박수가 쏟아질 때까지. 박수가 귀에서 한참 안 멎는다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'놀이 세트 — 텃밭의 고랑',
  x:`보라색 등 밑에 흙 언덕이 있다. 진짜 흙이다. 나물이 자란다.<br><br>
    고랑마다 팻말. 내가 심었어요. 아이 이름들.<br>
    나물 잎이 크다. 잎맥이 굵다. 이렇게 자라려면 흙 속에 먹을 것이 많아야 한다.<br><br>
    먹을 것을 다루는 사람은 흙도 본다. 흙이 무엇을 먹었는지.`,
  o:[
    { l:'① 평평한 가장자리 고랑 것만 뿌리째 캔다.', k:'gaze', dc:22, wake:1,
      ok:`가운데는 흙이 부풀었다. 가장자리는 평평하다. 평평한 데 것만 골랐다.<br><br>뿌리째 캤다. 뿌리에 사 온 화분 흙이 붙어 있다. 그 흙에서 자란 것은 그냥 나물이다. 잎을 비벼 보니 쌉쌀한 산나물 냄새.<br>가운데 고랑은 건드리지 않았다. 쓰러진 팻말을 바로 세워 두었다.<br><br>무엇이 먹는 것인지 아는 데서 한 걸음 더 갔다. 무엇을 먹고 자랐는지까지 보는 눈. 그 눈이 처음 떴다.`,
      ng:`가장자리 것을 당기는데 뿌리가 안 끝난다. 길게 따라 나온다. 가운데 고랑 쪽으로 이어져 있다.<br><br>가운데 흙이 들썩인다. 당기는 쪽으로. 무언가가 딸려 올라오려 한다.<br>뿌리를 끊었다. 끊긴 자리에서 하얀 즙이 난다. 손에 묻은 즙이 따뜻하다.`,
      win:{ exp:22, dream:3, item:'산나물' }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 허수아비 발치의 쑥을 재빨리 뜯는다.', k:'luck', dc:23,
      ok:`허수아비 발치에만 쑥이 잔뜩이다. 쑥은 원래 사람 발길 닿는 데 난다.<br><br>한 움큼 뜯었다. 허수아비 방글이 탈이 바람도 없이 이쪽으로 고개를 돌린다. 천천히.<br>다 돌기 전에 언덕을 내려왔다. 쑥은 뭉치로 묶었다. 냄새가 진하다.`,
      ng:`뜯는데 허수아비 팔이 내려온다. 장대째.<br><br>벌린 팔이 이쪽 어깨를 감싼다. 안아 주듯. 장갑 손가락이 등을 토닥인다. 넷. 넷.<br>빠져나오며 어깨가 긁혔다. 쑥은 흙에 다 흘렸다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A1', t:'놀이 세트 — 맑은 눈의 물고기',
  x:`큰 수조에 은색 물고기가 떼로 돈다. 살이 통통하다.<br><br>
    먹이통이 다섯 시에 열린다고 적혀 있다. 이 물고기들은 무엇을 먹고 이렇게 컸나.<br>
    생선을 다뤄 본 사람은 눈을 본다. 눈이 맑으면 갓 잡은 것이고, 흐리면 오래된 것이다.<br><br>
    여기 것들은 눈이 맑다. 너무 맑다. 다 같이 이쪽을 본다.`,
  o:[
    { l:'① 뚜껑을 열고 손으로 건진다.', k:'evade', dc:23,
      doom:{ title:'물고기 친구', what:'수조 안으로 팔부터 빨려 들어갑니다', dc:18, sec:50,
        text:`뚜껑을 열고 손을 넣었다. 물이 차다. 물고기가 손바닥으로 몰려든다. 간지럽다.<br><br>간지러운 게 아니다. 문다. 작은 이빨로 한 점씩. 손을 빼려는데 물이 손목을 쥔다. 물이 당긴다. 팔꿈치, 어깨.<br>수조 유리에 얼굴이 눌린다. 유리 너머로 일행이 보인다. 위에서 파란 목이 내려와 이쪽 정수리를 부리로 누른다.<br><br>스피커에서 노래가 흐른다. 물고기 친구, 밥 먹을 시간.`,
        dieText:`다섯 시에 먹이통이 열렸다.<br><br>은색 물고기들이 떼로 돈다. 한 마리가 늘었다. 조금 크다. 눈이 맑다.<br>수조 바닥 자갈 위, 손목시계 옆에 신발이 한 켤레 놓였다.` },
      ok:`손을 넣기 전에 소매를 걷고 팔에 소금을 문질렀다. 민물 것은 짠 것을 싫어한다.<br><br>물고기들이 손을 피한다. 피해 도는 떼 바깥으로 처지는 한 마리를 쥐었다. 눈이 조금 흐린 놈이다. 이 수조에서 제일 평범한 놈.<br>건져 올리는데 위에서 파란 목이 내려온다. 뚜껑을 닫았다. 부리가 뚜껑을 한 번 쪼고 올라갔다.`,
      win:{ exp:22, dream:3, item:'민물고기' } },
    { l:'② 수조 위 먹이통과 선반을 살핀다.', k:'gaze', dc:21,
      ok:`먹이통을 들여다봤다. 바닥에 붉은 가루가 조금 남았다. 마른 새우 가루다. 냄새가 진짜다.<br><br>옆 선반에 생선 손질 도구가 있다. 요리 코너와 같이 쓰던 것이다. 비늘 긁개, 작은 칼, 굵은 소금 한 봉.<br>소금만 챙겼다. 먹이는 물고기 몫이다.`,
      ng:`들여다보는데 먹이통 바닥이 붉다. 가루가 아니다. 엉겨 굳은 것이다.<br><br>손톱만 한 조각 속에 손톱이 있다. 작은 손톱이다.<br>먹이통을 닫았다. 수조 속 물고기들이 일제히 이쪽을 본다. 아직 밥때가 아니라는 듯.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A1', t:'방청석 — 의자 위의 간식',
  x:`방청석 의자마다 작은 봉지가 놓여 있다. 방청객 간식. 사탕 하나, 과자 하나.<br><br>
    일행 하나가 벌써 까서 입에 넣었다. 단 것이 귀하다.<br>
    먹을 것을 오래 만진 손은 포장을 보면 안다. 이 봉지는 공장에서 봉한 게 아니다. 손으로 접었다. 접은 자리가 다 똑같다.<br><br>
    먹은 사람이 웃는다. 입꼬리가 조금 길다.`,
  o:[
    { l:'① 뱉게 하고 맑은 물로 입을 헹군다.', k:'heal', dc:22,
      ok:`그 사람 턱을 잡고 뱉게 했다. 사탕이 굴러 나온다. 하얗다. 안에 실밥이 들어 있다.<br><br>맑은 물로 입을 헹구게 했다. 세 번. 길던 입꼬리가 한 땀씩 내려온다.<br>그 사람이 볼을 만진다. 얼굴이 당긴다고 한다. 꿰맨 것처럼.`,
      ng:`뱉게 하는데 그 사람이 입을 다문다. 웃으며.<br><br>억지로 벌렸다. 사탕은 이미 녹았다. 혀가 하얗다. 그 사람이 박수를 친다. 스피커 박수와 박자가 맞는다.<br>한참 손을 붙잡고 있었다. 박수가 그칠 때까지.`,
      win:{ exp:18, dream:2, spirit:8 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 봉지를 눌러 진짜 과자만 골라낸다.', k:'sense', dc:21,
      ok:`봉지를 하나씩 손끝으로 눌렀다. 대부분 속이 물렁하다. 사탕 무게가 아니다.<br><br>맨 뒷줄 봉지 셋만 바스락거린다. 공장 봉지다. 누가 몰래 넣어 둔 것이다. 꿀 과자다.<br>그것만 챙겼다. 나머지 봉지를 의자에 도로 놓는데 다들 조금 무거워져 있다.`,
      ng:`누르다가 봉지 하나가 터진다. 안에서 하얀 솜이 쏟아진다.<br><br>방청석 전체가 숨을 들이켜는 소리를 낸다. 녹음이다. 그리고 웃음.<br>솜이 손에 붙는다. 털어도 털어도. 실밥이 손가락 사이에 감긴다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'식당 — 이백열두 그릇의 국솥',
  x:`배식대 국솥에서 국자가 혼자 움직인다. 물속에서 국이 끓는다.<br><br>
    국 냄새가 물 위로 올라온다. 미역국이다. 생일에 끓이는 국.<br>
    부엌 사람은 국 한 솥을 보면 몇 그릇인지 안다. 이 솥은 이백열두 그릇이다. 딱 맞게 끓였다.<br><br>
    국자가 멈춘다. 이쪽을 향한다. 한 그릇 더 뜰 수 있다는 듯.`,
  o:[
    { l:'① 국자를 받아 배식을 거든다.', k:'bond', dc:23,
      doom:{ title:'배식 당번', what:'배식대 뒤로 끌려가 국솥 앞에 세워집니다', dc:18, sec:50,
        text:`국자를 받았다. 손에 익은 무게다. 떠서 내밀었다. 물속에서 식판이 받아 간다.<br><br>다음, 다음. 줄이 끝나지 않는다. 손을 놓으려는데 등 뒤에서 앞치마 끈을 묶어 준다. 배식 당번이라고. 오늘은 네 차례라고.<br>발이 배식대 뒤로 끌려간다. 국솥 앞에. 물이 가슴까지 차오른다. 국자를 쥔 손이 이쪽 손이 아니라 국자의 손이 된다.<br><br>솥 안 국은 줄지 않는다. 이백열두 그릇. 그리고 한 그릇.`,
        dieText:`식당 국솥에서 국자가 혼자 움직인다.<br><br>푼다. 내민다. 다음.<br>푸는 박자가 조금 바뀌었다. 부엌에서 일해 본 손의 박자다. 넘치지 않게 딱 맞게.` },
      ok:`국자를 받는 척하고 솥 가장자리에 걸어 두었다. 내 차례가 아니라고 말했다.<br><br>국자가 한참 걸린 채 있다. 그러다 다음 사람에게 간다.<br>솥 옆 바구니에 마른 미역이 한 묶음 있다. 물 밖으로 들어 올리니 소금이 하얗게 피어 있다. 소금째 챙겼다.`,
      win:{ exp:22, dream:3, item:'소금 덩이' } },
    { l:'② 김을 맡아 언제 끓인 국인지 가늠한다.', k:'sense', dc:22,
      ok:`물 위에서 김을 맡았다. 미역, 참기름, 간장. 그리고 오래 우린 뼈.<br><br>생일 국이다. 그런데 이백열두 그릇이다. 한 사람 생일이 아니다. 모두의 날이다. 물 들어온 날이다.<br>국은 안 먹었다. 생일 국은 생일인 사람이 먹는다.`,
      ng:`맡는데 김이 코로 들어와 안 나간다. 물 냄새가 섞여 있다.<br><br>기침을 했다. 식당 물이 일제히 출렁인다. 국그릇들이 이쪽을 향한다.<br>물에 잠긴 식탁마다 숟가락이 들린다. 이쪽 기침 박자로 숟가락이 그릇을 친다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'③ 퇴식구 옆을 뒤진다.', k:'luck', dc:21,
      ok:`퇴식구 옆 잔반통은 비었다. 이백열두 명이 남김없이 먹었다.<br><br>그 옆 행주 통 밑에 소쿠리가 있다. 다듬다 만 민물고기가 담겨 있다. 소금에 절여 단단하다. 물 들기 전에 손질한 것이다.<br>두 마리 꺼냈다. 부엌을 맡던 사람이 다음 끼니를 준비하던 중이었다.`,
      ng:`잔반통 뚜껑을 열자 안이 숟가락으로 차 있다.<br><br>숟가락마다 이가 문 자국이 있다. 수백 개. 뚜껑을 닫는데 숟가락들이 짤랑 운다.<br>배식대 쪽 국자가 이쪽을 향한다. 잔반 버리면 혼난다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A2', t:'조리실 — 밀랍 두른 독',
  x:`조리실 구석에 독이 있다. 뚜껑 위로 물이 찰랑인다.<br><br>
    뚜껑 가장자리에 밀랍이 둘러져 있다. 꼼꼼하게. 누가 물이 오르는 걸 보면서 발랐다.<br>
    부엌 사람은 이게 무슨 뜻인지 안다. 마지막까지 먹을 것을 지킨 것이다.<br><br>
    뚜껑 위에 손바닥 자국이 있다. 밀랍에 찍혔다. 눌러서 닫은 손이다.`,
  o:[
    { l:'① 밀랍을 한쪽만 들어 조금만 꺼낸다.', k:'fix', dc:22, wake:1,
      ok:`밀랍 한쪽만 손톱으로 들었다. 뚜껑을 손가락 하나 틈만 밀었다. 손을 넣어 더듬었다.<br><br>안이 말랐다. 겨울 찬거리로 말려 둔 버섯이다. 한 줌 쥐고 뚜껑을 도로 눌렀다. 밀랍을 손바닥으로 데워 다시 붙였다. 처음 자국 위에 이쪽 손을 겹쳐서.<br><br>남이 지킨 것을 덜어 쓰고 다시 지켜 주는 손. 부엌을 맡는 손은 이렇게 넓어진다. 제 솥 너머까지.`,
      ng:`밀랍을 드는데 뚜껑이 저 혼자 닫힌다. 밑에서 누른다.<br><br>손가락이 끼었다. 뚜껑 밑에서 다른 손가락이 이쪽 손가락을 쥔다. 차다. 안 된다는 듯 하나씩 눌러 접는다.<br>빼냈다. 손가락 셋이 퍼렇게 멍들었다.`,
      win:{ exp:22, dream:3, item:'야생 버섯' }, lose:{ hp:-26, spirit:-20 } },
    { l:'② 손바닥 자국에 이쪽 손을 겹쳐 대 본다.', k:'bond', dc:23,
      ok:`밀랍의 손바닥 자국에 이쪽 손을 겹쳤다. 크기가 비슷하다. 어른 손이다. 조리실을 맡던 손이다.<br><br>손바닥이 따뜻해진다. 밀랍이 녹는다. 뚜껑이 저절로 열린다. 내어 주는 것이다.<br>안에 소금 항아리가 하나 더 있다. 그것만 꺼냈다. 뚜껑이 다시 닫힌다. 자국이 둘이 됐다.`,
      ng:`겹치는데 자국이 이쪽 손보다 커진다. 밀랍이 넓어진다.<br><br>손바닥이 밀랍에 붙었다. 떼려는데 물 밑에서 손등을 누른다. 겹친 손이 하나 더.<br>살갗이 찢어지며 떨어졌다. 손바닥에 밀랍이 붙어 굳었다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'종탑 — 발린 생선 뼈',
  x:`종탑 들보에 비둘기가 산다. 물고기를 물어 온다.<br><br>
    들보 밑에 물고기 뼈가 쌓였다. 살은 다 발렸다. 깨끗하게.<br>
    생선을 다뤄 본 손은 발린 뼈를 보면 누가 먹었는지 안다. 새는 이렇게 못 바른다. 이건 젓가락질이다.<br><br>
    비둘기가 한 마리 내려앉는다. 부리에 은빛 물고기가 퍼덕인다.`,
  o:[
    { l:'① 말린 고기 부스러기와 바꾼다.', k:'bond', dc:21,
      ok:`말린 고기를 손바닥에 올려 내밀었다. 비둘기가 고개를 갸웃한다. 물고기를 바닥에 두고 고기를 쪼아 먹는다.<br><br>물고기를 집었다. 퍼덕인다. 산 것이다. 민물 것이다. 비린내가 맑다.<br>들보 위에서 다른 비둘기들이 일제히 내려다본다. 다음은 자기 차례라는 듯.`,
      ng:`내밀자 비둘기가 손바닥을 쫀다. 고기가 아니라 살을.<br><br>들보 위에서 수십 마리가 한꺼번에 내려온다. 날개가 얼굴을 친다. 부리가 손등을 찍는다.<br>종 밑으로 기어들어 갔다. 손이 피투성이다.`,
      win:{ exp:18, dream:2, item:'민물고기' }, lose:{ hp:-26, spirit:-18 } },
    { l:'② 막대로 뼈 무더기를 헤쳐 본다.', k:'gaze', dc:22,
      ok:`뼈 무더기를 막대로 헤쳤다. 물고기 뼈, 물고기 뼈. 그 사이에 나무젓가락 한 벌.<br><br>젓가락에 이름이 새겨져 있다. 칼로 긁어서. 젓가락 주인은 여기서 비둘기가 물어 온 물고기를 먹으며 버텼다.<br>무더기 밑에 소금 봉지가 반쯤 남아 있다. 그것을 챙기고 젓가락은 들보 위에 올려 두었다.`,
      ng:`헤치는데 뼈가 끝나지 않는다. 밑으로 갈수록 굵어진다.<br><br>맨 밑의 뼈는 물고기 것이 아니다. 젓가락이 그 옆에 가지런히 놓였다. 다 먹고 내려놓은 모양으로.<br>막대를 놓고 물러났다. 그날 생선 냄새를 맡을 때마다 속이 뒤집혔다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A2', t:'중정 — 원예부 선반',
  x:`중정 유리 온실이 물에 반쯤 잠겼다. 위쪽 선반은 물 밖이다.<br><br>
    선반에 화분이 줄지어 있다. 원예부 화분. 이름표에 반과 번호.<br>
    물 밖 화분에 나물이 자란다. 흙이 촉촉하다. 누가 물을 준다. 아침 일곱 시마다.<br><br>
    먹을 것을 키운 흙은 손이 간 흙이다. 손이 간 흙에는 손이 아직 있다.`,
  o:[
    { l:'① 이름표를 하나씩 읽어 주며 몇 잎씩만 딴다.', k:'gaze', dc:22, wake:1,
      ok:`화분마다 이름표를 읽었다. 키운 아이 이름을 불러 주고 잎을 몇 장씩만 땄다. 고맙다고 하면서.<br><br>잎을 딸 때마다 물 밑에서 작은 물결이 하나씩 퍼진다. 대답하듯이. 아무도 화를 내지 않는다.<br>한 줌이 모였다. 쌉쌀한 냄새.<br><br>누가 키웠는지 묻고 얻는 손. 거두는 일이 빼앗는 일이 되지 않는 법을 손이 하나 배웠다.`,
      ng:`이름을 부르다 하나를 잘못 읽었다. 번진 글씨다.<br><br>물 밑에서 대답이 온다. 그 이름이 아니에요. 화분이 선반에서 미끄러진다. 물속으로. 흙이 풀리며 뿌리가 손목을 감는다.<br>뿌리를 끊고 물러났다. 손목에 붉은 자국이 고리처럼 남았다.`,
      win:{ exp:22, dream:3, item:'산나물' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 유리 지붕 홈에 고인 빗물을 받는다.', k:'fix', dc:21,
      ok:`유리 지붕 홈에 빗물이 고였다. 학교 물이 아니라 하늘 물이다. 위에서 왔다.<br><br>홈 끝에 수통을 대고 기울였다. 맑다. 한 통을 다 채웠다.<br>아래 물은 안 먹고 위 물을 먹는다. 아래 물은 이름을 안다.`,
      ng:`홈을 기울이는데 유리가 운다. 쩍. 금이 간다.<br><br>빗물과 함께 유리 조각이 쏟아진다. 팔뚝을 그었다. 피가 아래 물에 떨어진다.<br>물 밑에서 무언가가 그 방울을 받아 마신다. 물결이 이쪽으로 모인다. 서둘러 나왔다.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-28, mind:-14 } },
    { l:'③ 너무 젖은 화분의 버섯을 캔다.', k:'sense', dc:23,
      ok:`흙이 너무 촉촉한 화분에 버섯이 났다. 하얀 갓. 냄새를 맡았다. 밤 냄새, 끝에 단내. 먹는 쪽이다.<br><br>흙째 떴다. 흙 속에 손톱만 한 단추가 하나 있다. 교복 단추다. 그것은 화분에 도로 묻었다.<br>버섯만 챙겼다.`,
      ng:`맡는데 단내가 아니라 물 냄새다. 오래 고인 물.<br><br>갓을 뒤집으니 주름 사이가 촘촘한 머리카락이다. 젖은.<br>던졌다. 버섯이 물에 떨어져 가라앉는다. 손짓하듯 흔들리면서.`,
      win:{ exp:18, dream:2, item:'야생 버섯' }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A2', t:'기숙사 — 침대 밑 밤참 상자',
  x:`기숙사 침대 밑에 상자가 있다. 방수 천으로 몇 겹 쌌다. 아이들 밤참 상자다.<br><br>
    점호 전에 몰래 꺼내 먹던 것. 상자 위에 쪽지. 사감 선생님 보지 마세요.<br>
    먹을 것을 숨겨 본 사람은 안다. 숨긴 것은 숨긴 사람이 다시 찾으러 온다.<br><br>
    복도 끝에서 발소리가 다가온다. 아홉 시 점호다.`,
  o:[
    { l:'① 상자를 안고 이불 속에 숨는다.', k:'hide', dc:22,
      ok:`상자를 안고 이불 밑으로 들어갔다. 젖은 이불이다. 무겁다. 숨을 죽였다.<br><br>사감 발소리가 침대마다 멈췄다 간다. 이쪽 침대 앞에서 오래 멈춘다. 그리고 지나간다. 이불 속 이쪽 옆구리에 차가운 등이 하나 닿아 있다.<br>발소리가 사라지고 이불을 걷었다. 옆자리는 비었다. 상자 안은 말린 고기와 꿀 사탕이다.`,
      ng:`이불 속에 들어가자 이불이 가라앉는다. 침대째 물속으로.<br><br>숨이 막히기 직전에 기어 나왔다. 사감 발소리가 바로 앞에서 멈춘다. 침대 밖으로 나온 아이는 벌점이다.<br>이쪽 손등에 분필로 금이 하나 그어졌다. 지워도 안 지워진다.`,
      win:{ exp:18, dream:2, item:'말린 고기' }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 하나만 꺼내고 쪽지를 남긴다.', k:'bond', dc:21,
      ok:`상자를 풀어 하나만 꺼냈다. 꿀 한 덩이. 쪽지 뒷면에 적었다. 하나 빌려 갑니다.<br><br>도로 싸서 침대 밑에 넣었다. 발소리가 지나간다. 이쪽 침대 앞에서 멈추지 않는다.<br>복도로 나오는데 등 뒤 침대 밑에서 상자 푸는 소리가 난다. 쪽지 읽는 소리. 키득거림.`,
      ng:`쪽지를 쓰는데 연필이 미끄러진다. 글씨가 이름이 된다. 이쪽 이름.<br><br>침대 밑에서 손이 나와 쪽지를 가져간다. 점호 명단에 붙일 거라고 속삭인다.<br>발소리가 빨라진다. 이쪽 침대를 향해. 문 밖으로 뛰었다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-24 } }
  ] }

]);


// ------------------------------------------
// 치유사 (healer) · 마력
// ------------------------------------------
kJob('healer', 'A', [

{ at:'A', t:'쉬는 자리 — 피 안 나는 상처',
  x:`앉자마자 상처를 셌다. 버릇이다.<br><br>
    하나가 팔뚝을 내민다. 벌어진 상처다. 깊다. 그런데 피가 안 난다.<br>
    상처 가장자리가 하얗다. 오래 물에 불린 살처럼. 벌어진 모양이 둥글다. 무엇이 문 자리다.<br><br>
    언제 물렸냐고 물었다. 그 사람은 모른다고 한다. 아까 누가 손을 잡아 준 것만 기억난다고 한다.`,
  o:[
    { l:'① 마력을 가늘게 넣어 상처 안쪽을 비춰 본다.', k:'gaze', dc:22, cost:{ mana:25 },
      ok:`손끝에 마력을 모아 실처럼 가늘게 상처 안으로 넣었다. 안쪽이 손끝에 그려진다.<br><br>살 속에 작은 것이 박혀 있다. 이빨이 아니다. 단추다. 동그랗고 납작한 것. 누가 거기 꿰매 두려던 자리다.<br>마력으로 감싸 끌어냈다. 단추가 나오자 그제야 피가 난다. 붉고 따뜻한 피다.<br><br>피가 나는 상처는 고칠 수 있는 상처다. 그 사람이 처음으로 아프다고 했다.`,
      ng:`마력을 넣자 상처가 마력을 문다. 빨아들인다. 끝도 없이.<br><br>손을 뗐다. 손끝이 하얗게 불었다. 그 사람 상처와 같은 색이다.<br>둘 다 피가 안 났다. 밤새 손끝을 입에 물고 있었다.`,
      win:{ exp:20, dream:3, hp:8 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 씻고, 벌리고, 피가 날 때까지 문지른다.', k:'heal', dc:21, wake:1,
      ok:`맑은 물로 씻었다. 하얀 가장자리를 천으로 문질렀다. 살갗이 벗겨질 만큼. 그 사람이 이를 문다.<br><br>한참 문지르자 하얀 데 밑에서 분홍빛이 올라온다. 이어서 피가 한 방울. 또 한 방울.<br>그제야 묶었다. 피가 나야 닫을 수 있다.<br><br>상처를 닫는 손이 상처를 여는 법을 알았다. 닫기 전에 살려 놓는 것. 손이 그 순서를 몸에 새겼다.`,
      ng:`문지르는데 하얀 데가 넓어진다. 천이 닿는 자리마다.<br><br>손을 멈췄다. 그 사람 팔이 손목까지 하얘졌다. 차다.<br>불가에 팔을 대고 밤을 새웠다. 아침에 손목 아래로 조금 색이 돌았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 아프다는 목소리',
  x:`복도 저쪽 어둠에서 목소리가 난다. 아파요.<br><br>
    아이 목소리다. 울지는 않는다. 그냥 또박또박 말한다. 아파요. 여기가 아파요.<br>
    상처를 닫는 사람은 그 말을 듣고 그냥 못 지나간다. 다리가 먼저 그쪽으로 간다.<br><br>
    일행이 이쪽 팔을 잡는다. 목소리가 말한다. 거기 손이 따뜻한 사람.`,
  o:[
    { l:'① 대답하지 않고 일행 손을 잡고 지나간다.', k:'steady', dc:22,
      ok:`이를 물고 걸었다. 일행 손을 꼭 쥐었다. 손바닥이 땀에 젖는다.<br><br>목소리가 따라온다. 아파요. 왜 안 와요. 걸음마다 한 번씩. 복도 끝 모퉁이에서 목소리가 바뀐다. 어른 목소리로. 낮게. 안 오네.<br>모퉁이를 돌자 조용해졌다. 손바닥에 일행 손톱 자국이 남았다. 일행도 그만큼 세게 쥐었다.`,
      ng:`걷는데 목소리가 울기 시작한다. 진짜 우는 소리다. 숨이 넘어가게.<br><br>다리가 멈췄다. 일행이 끌다시피 데려갔다. 등 뒤의 울음이 이쪽 이름을 부른다. 처음 듣는 아이가 이쪽 이름을 안다.<br>그날 밤 잠들 때마다 그 울음이 귀에서 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 붕대 한 뭉치를 그쪽으로 굴려 보낸다.', k:'bond', dc:21,
      ok:`붕대를 한 뭉치 꺼내 바닥에 굴렸다. 어둠 속으로 풀리며 굴러간다.<br><br>한참 조용하다. 그러다 붕대 감는 소리가 난다. 서툴게. 오래.<br>아파요 소리가 그쳤다. 대신 고마워요. 그리고 다 감았어요. 무엇을 감았는지는 묻지 않았다.`,
      ng:`굴린 붕대가 어둠 속에서 멈춘다. 그리고 도로 굴러온다. 다 풀린 채로.<br><br>풀린 붕대 끝이 젖어 있다. 검붉다. 감아 주세요. 목소리가 바로 붕대 끝에서 난다.<br>붕대를 밟지 않으려다 벽에 어깨를 찧었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 다가가 어디가 아픈지 본다.', k:'heal', dc:23,
      doom:{ title:'아픈 데', what:'아픈 아이에게 손목을 잡혀 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`다가갔다. 쪼그려 앉았다. 어둠 속에 작은 것이 웅크리고 있다. 어디가 아프냐고 물었다.<br><br>여기요. 작은 손이 이쪽 손목을 잡아 제 가슴에 댄다. 차다. 심장이 안 뛴다. 손바닥 밑에서 무언가가 손바닥을 더듬는다.<br>여기가 아파요. 안쪽이요. 손이 가슴 안으로 들어간다. 당긴다. 어둠 쪽으로. 무릎이 바닥을 쓸며 끌려간다.<br><br>고쳐 주세요. 고칠 때까지 있어 주세요.`,
        dieText:`복도 저쪽 어둠에서 목소리가 난다.<br><br>아파요. 그리고 다른 목소리가 대답한다. 어른 목소리다. 조용히. 괜찮아, 괜찮아.<br>다음에 지나간 일행은 두 목소리를 들었다. 한 목소리는 손이 따뜻하다.` },
      ok:`다가가되 등잔을 앞에 내밀었다. 빛이 웅크린 것에 닿는다.<br><br>아이가 아니다. 아이 옷을 입힌 무엇이다. 소매에서 나온 손이 너무 길다. 빛이 닿자 그 손이 얼굴을 가린다.<br>그 앞에 붕대와 맑은 물 한 병을 놓고 물러났다. 물러나는 내내 등을 보이지 않았다.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A', t:'계단 — 너무 빨리 닫힌 상처',
  x:`계단에서 동료가 정강이를 베였다. 마력으로 닫았다.<br><br>
    닫혔다. 그런데 너무 빨리 닫혔다. 이쪽 마력보다 빨리.<br>
    닫힌 자리 밑이 볼록하다. 살갗 밑에서 무언가가 아주 조금 움직인다.<br><br>
    동료는 괜찮다고 한다. 하나도 안 아프다고. 그게 더 이상하다.`,
  o:[
    { l:'① 닫힌 자리를 다시 열어 안을 꺼낸다.', k:'heal', dc:22, wake:1,
      ok:`칼끝을 불에 달궈 닫힌 자리를 다시 갈랐다. 동료가 그제야 소리를 지른다. 아픈 것이다.<br><br>안에서 가는 것이 나온다. 머리카락이다. 길다. 한 가닥이 상처를 꿰매듯 드나들고 있었다. 끝까지 뽑아 불에 던졌다. 치익.<br>그다음에 이쪽 마력으로 닫았다. 이번엔 이쪽 속도로.<br><br>닫히는 것이 다 낫는 것은 아니다. 누가 닫았는지를 보는 눈. 그 눈이 손끝에 하나 더 생겼다.`,
      ng:`가르자 머리카락이 안쪽으로 달아난다. 다리 위쪽으로.<br><br>쫓아 가를 수가 없다. 무릎 위에서 놓쳤다. 동료는 아프다고 한다. 이제는 무릎이.<br>무릎을 천으로 꽁꽁 동였다. 밤새 동인 자리 밑에서 무언가가 매듭을 더듬었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 마력을 밀어 넣어 볼록한 것을 밖으로 밀어낸다.', k:'heal', dc:23, cost:{ mana:25 },
      ok:`손바닥을 닫힌 자리에 대고 마력을 안쪽부터 밀었다. 볼록한 것이 밀려 올라온다.<br><br>살갗이 터지며 가는 것이 비어져 나온다. 머리카락 한 가닥. 끝에 작은 매듭이 지어져 있다. 집어서 불에 넣었다.<br>그다음에야 상처가 아프다. 동료가 이를 문다. 아파서 다행이다.`,
      ng:`밀자 볼록한 것이 거꾸로 밀어 온다. 이쪽 손바닥 쪽으로. 마력을 타고.<br><br>손을 뗐다. 손바닥이 따끔하다. 들여다보니 손금 하나가 조금 길어졌다.<br>마력은 다 빠졌다. 동료 다리는 여전히 볼록하다.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 마력이 새는 쪽',
  x:`어둠 속을 걷는데 손끝이 시리다.<br><br>
    마력이 샌다. 손끝에서 실처럼 풀려 나간다. 앞쪽 어둠으로.<br>
    마력은 상처 쪽으로 흐른다. 상처를 닫는 사람은 그걸 안다. 마력이 가는 쪽에 다친 것이 있다.<br><br>
    이 어둠은 아주 크게 다쳤다. 아니면 다친 척을 아주 잘한다.`,
  o:[
    { l:'① 마력을 몸 안쪽으로 접어 넣는다.', k:'steady', dc:22, wake:1,
      ok:`숨을 깊이 쉬고 손끝을 쥐었다. 풀리던 실을 안쪽으로 감아 들였다. 손목으로, 팔꿈치로, 가슴으로.<br><br>가슴 한가운데 작게 접어 넣었다. 손끝이 다시 따뜻해진다. 어둠이 끌어갈 것이 없어졌다.<br>어둠 저편에서 아쉬운 숨소리가 한 번 났다.<br><br>마력은 흘러 나가는 것만이 아니다. 접어서 품을 수도 있다. 쓰지 않는 법을 손이 처음 익혔다.`,
      ng:`감아 들이는데 저쪽이 당긴다. 줄다리기다.<br><br>팔꿈치까지 끌려갔다가 겨우 끊었다. 끊긴 실이 어둠 속으로 사라진다. 이쪽 마력의 반이다.<br>남은 손끝이 한동안 아무것도 못 느꼈다.`,
      win:{ exp:22, dream:3, mind:8 }, lose:{ mind:-22, spirit:-20 } },
    { l:'② 마력을 한 줄기 미끼로 흘려 다른 쪽으로 돌린다.', k:'hide', dc:23, cost:{ mana:30 },
      ok:`마력을 한 줄기 크게 풀어 옆 통로 쪽으로 흘렸다. 상처 냄새를 실어서.<br><br>어둠이 그쪽으로 기운다. 바닥을 쓸며 옆 통로로 간다. 그사이 일행이 앞으로 지나갔다.<br>멀리서 무언가가 빈 마력을 핥는 소리가 났다. 오래.`,
      ng:`흘린 마력이 그쪽으로 가지 않는다. 이쪽 발밑에서 맴돈다.<br><br>어둠이 다가와 발목을 핥는다. 차다. 마력을 핥고 나서 살갗을 핥는다.<br>뛰었다. 발목에 하얀 자국이 남았다. 혀 모양이다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잡은 손이 하나 많다',
  x:`다친 셋을 눕히고 가운데 앉았다. 두 손으로 둘을 잡고 마력을 흘렸다.<br><br>
    셋째도 잡아야 한다. 손을 뻗었다. 셋째 손이 와서 잡힌다.<br>
    그런데 이쪽 손은 둘 다 이미 잡고 있다.<br><br>
    잡힌 손이 하나 더 있다. 차고, 부드럽다. 마력을 받고 있다.`,
  o:[
    { l:'① 눈을 감고 손을 하나씩 센다.', k:'gaze', dc:22,
      ok:`눈을 감고 손끝으로 셌다. 왼손에 하나. 오른손에 하나. 손등 위에 하나.<br><br>손등 위의 것은 이쪽이 잡은 게 아니다. 저쪽이 얹은 것이다. 마력을 마시고 있다.<br>왼손 오른손을 놓지 않은 채 손등만 털었다. 차가운 것이 떨어진다. 바닥을 기어 문틈으로 나갔다.`,
      ng:`세는데 셀 때마다 손이 하나씩 는다. 셋, 넷.<br><br>다 차다. 어느 게 일행 손인지 모르겠다. 마력이 사방으로 빠져나간다.<br>소리를 질렀다. 손들이 한꺼번에 놓았다. 누운 셋 중 하나가 이쪽 손을 다시 찾으며 울었다.`,
      win:{ exp:18, dream:2, spirit:8 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 마력의 온도로 산 손과 아닌 손을 가린다.', k:'sense', dc:21, wake:1,
      ok:`마력을 조금씩 나눠 흘렸다. 산 손은 받은 마력을 데워서 돌려보낸다. 아주 조금.<br><br>하나는 돌려보내지 않는다. 받기만 한다. 그 손만 마력을 끊었다. 손이 잠깐 더듬다 물러간다.<br>세 사람에게만 마력이 갔다. 아침에 셋 다 일어났다.<br><br>주는 것에서 돌아오는 것을 읽었다. 마력이 오가는 결을 손이 듣기 시작했다.`,
      ng:`온도를 읽는데 다 차다. 다친 셋도 찬 것이다.<br><br>가려내지 못했다. 넷에게 다 흘렸다. 아침에 셋이 일어났다. 일어난 셋 다 이쪽을 보지 않는다.<br>넷째 자리에 젖은 손자국이 남아 있다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 어느 손이든 끝까지 놓지 않는다.', k:'bond', dc:23,
      doom:{ title:'넷째 손', what:'넷째 손에 잡혀 바닥 밑으로 끌려갑니다', dc:18, sec:55,
        text:`놓지 않았다. 다친 사람 손을 놓는 건 이쪽 일이 아니다. 넷 다 쥐었다.<br><br>넷째 손이 마주 쥔다. 세게. 손가락 사이로 깍지를 낀다. 그리고 당긴다. 아래로.<br>바닥이 물러진다. 넷째 손이 나온 바닥 틈이 넓어진다. 팔이 팔꿈치까지 빠진다. 다른 손들은 하나씩 이쪽 손을 놓는다. 산 손들이다.<br><br>남은 손은 하나다. 놓지 말라고 그 손이 말한다.`,
        dieText:`바닥 틈은 아침에 닫혀 있었다.<br><br>틈 위에 손바닥 자국 둘이 겹쳐 있다. 하나는 차고 하나는 아직 미지근하다.<br>그 뒤로 이 방에서 손을 잡으면 손이 하나 더 잡힌다. 따뜻한 손이.` },
      ok:`놓지 않되 넷째 손에는 마력을 보내지 않았다. 쥐기만 했다.<br><br>넷째 손이 한참 기다린다. 아무것도 오지 않는다. 깍지를 풀고 물러간다.<br>새벽까지 셋 손을 잡고 있었다. 손등에 넷째 손의 냉기가 오래 남았다.`,
      win:{ exp:20, dream:3, mind:8 } }
  ] },

{ at:'A', t:'통로 — 비어 있는 붕대',
  x:`통로 벽에 붕대 감은 것이 기대 있다. 사람 크기다.<br><br>
    머리부터 발끝까지 감았다. 잘 감았다. 매듭이 단단하고 겹이 고르다. 상처를 다룰 줄 아는 손이다.<br>
    붕대에 피가 배어 있지 않다. 오래됐다.<br><br>
    가슴께가 아주 조금 오르내린다. 그렇게 보인다.`,
  o:[
    { l:'① 매듭만 풀어 감은 사람의 솜씨를 읽는다.', k:'gaze', dc:22,
      ok:`매듭을 하나 풀었다. 감은 순서가 보인다. 발목부터 위로. 다친 데를 먼저, 성한 데는 나중에.<br><br>풀린 데 안쪽이 비었다. 붕대만 사람 모양을 하고 있다. 누가 다 감고 나서 안의 것이 빠져나갔다.<br>매듭 안쪽에 연필 글씨. 감아 줬는데 갔다. 이쪽은 아무 말도 하지 않고 매듭을 도로 묶었다.`,
      ng:`매듭을 풀자 붕대가 저절로 풀린다. 위에서부터. 빠르게.<br><br>안에 아무것도 없다. 풀린 붕대가 바닥에 쌓이며 이쪽 발을 감는다. 감던 솜씨 그대로.<br>칼로 끊었다. 발목에 붕대 자국이 고르게 남았다. 남의 솜씨다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 깨끗한 겹만 잘라 챙긴다.', k:'fix', dc:21,
      ok:`바깥 겹은 먼지다. 안쪽 겹은 하얗다. 칼로 바깥만 벗기고 안쪽 겹을 길게 잘랐다.<br><br>세 뭉치가 나왔다. 감겨 있던 사이에 약초 잎이 끼어 있다. 상처 곪는 걸 막는 잎이다. 마른 채 향이 남았다.<br>잎도 챙겼다. 붕대 감은 것은 반쯤 가벼워진 채 벽에 기대 있다.`,
      ng:`자르는데 칼끝에 무언가 걸린다. 안쪽 겹이 칼을 문다.<br><br>당기자 붕대 밑에서 손가락이 나온다. 붕대만큼 하얗다. 칼날을 쥐고 있다.<br>칼을 놓고 물러섰다. 칼은 돌려받지 못했다.`,
      win:{ exp:16, dream:2, item:'약초 뭉치' }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 식어 가는 손',
  x:`오늘 마력을 많이 썼다. 손이 차다.<br><br>
    마력을 쓰면 손이 데워진다. 그게 보통이다. 오늘은 반대다. 쓸수록 손이 식는다.<br>
    손등을 보니 손가락 마디가 하얗다. 물에 오래 담근 손 같다.<br><br>
    다친 사람이 아직 하나 남았다. 등에 길게 그어진 상처다.`,
  o:[
    { l:'① 손을 불에 녹이며 마력을 쉬게 한다.', k:'steady', dc:21,
      ok:`손을 불가에 대고 앉았다. 마력을 한 방울도 쓰지 않았다. 다친 사람에게는 맑은 물로 씻고 묶기만 했다.<br><br>밤새 손이 천천히 데워진다. 마디의 하얀 것이 물러간다. 손끝에 피가 돈다.<br>마력을 쉬는 것도 일이다. 오늘 이 손은 그 일만 했다.`,
      ng:`불에 대도 안 녹는다. 손이 불을 무서워하지 않는다.<br><br>손끝이 불에 닿았다. 뜨거운 줄 모른다. 물집이 잡혀서야 알았다.<br>물집을 터뜨리니 안에서 물이 나온다. 맑지 않다. 비린내가 난다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 차가운 손 그대로 마력을 모아 등을 닫는다.', k:'heal', dc:23, cost:{ mana:30 }, wake:1,
      ok:`찬 손을 등 상처에 댔다. 다친 사람이 움찔한다. 차다고.<br><br>마력을 모았다. 손이 식는 만큼 마력이 맑다. 섞인 것이 없다. 이쪽 체온이 빠진 마력은 상처에 바로 스민다.<br>등이 닫혔다. 흉도 거의 없다.<br><br>마력에 손의 열이 섞이지 않을 때 더 곱게 닫힌다. 차가운 손으로 하는 치유. 손이 새로운 결을 찾았다.`,
      ng:`마력을 모으는데 손이 더 식는다. 손목까지.<br><br>등에 손을 댄 채로 손이 굳었다. 떼려니 살갗이 같이 들린다. 다친 사람이 비명을 지른다.<br>미지근한 물을 부어 겨우 뗐다. 상처는 반만 닫혔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, spirit:-24 } }
  ] },

{ at:'A', t:'문 앞 — 문틈으로 내민 손',
  x:`닫힌 문 밑 틈으로 손이 하나 나와 있다. 손바닥을 위로 펴서.<br><br>
    손바닥이 찢어져 있다. 깊다. 피가 고였다. 문 너머에서 숨소리가 난다. 아파서 참는 숨이다.<br>
    상처를 보면 손이 먼저 나간다. 오래 그렇게 살았다.<br><br>
    문 너머에서 아주 작게 말한다. 문은 열지 마세요. 손만요.`,
  o:[
    { l:'① 마력은 쓰지 않고 붕대로만 감아 준다.', k:'heal', dc:22,
      ok:`문 앞에 엎드려 그 손을 씻고 붕대를 감았다. 손바닥부터 손목까지. 단단하게.<br><br>문 너머의 숨이 고르게 된다. 손이 천천히 오므려지더니 문틈 안으로 들어간다.<br>잠시 뒤 틈으로 무언가 밀려 나온다. 꿀 한 줌이 싸인 종이다. 종이에 적혀 있다. 고마워요. 문은 열지 마세요.`,
      ng:`감는데 손이 이쪽 손목을 쥔다. 감는 붕대째.<br><br>문틈 쪽으로 당긴다. 손가락이 틈에 끼였다. 붕대를 끊고 손을 뺐다. 손가락 마디가 찢어졌다.<br>틈 안에서 붕대 감는 소리가 이어진다. 혼자서. 서툴게.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-26, mind:-16 } },
    { l:'② 손바닥 상처의 생김을 들여다본다.', k:'gaze', dc:21,
      ok:`엎드려 등잔을 대고 봤다. 상처가 손바닥 한가운데를 가로지른다. 곧다. 날붙이에 베인 것이다.<br><br>그런데 고인 피가 흐르지 않는다. 그릇처럼 손바닥에 담겨 있다. 담아 둔 것이다. 내밀라고.<br>손을 거두었다. 문 너머에서 숨소리가 그쳤다. 손이 천천히 오므려 피를 쥐고 들어간다.`,
      ng:`들여다보는데 고인 피에 이쪽 얼굴이 비친다. 뒤에 문이 비친다. 열려 있다.<br><br>돌아보니 문은 닫혀 있다. 다시 보니 피에 비친 문 틈으로 눈이 하나 보인다.<br>그 뒤로 문 앞을 지날 때마다 등이 시렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 손을 맞잡고 마력으로 상처를 닫아 준다.', k:'heal', dc:24, cost:{ mana:30 },
      doom:{ title:'손만요', what:'맞잡은 손에 문틈 안으로 빨려 들어갑니다', dc:19, sec:50,
        text:`손을 맞잡고 마력을 흘렸다. 상처가 닫힌다. 문 너머 숨소리가 길어진다. 좋아하는 숨이다.<br><br>닫혔는데 손이 놓지 않는다. 마력이 계속 빨려 간다. 손을 빼려 하자 문틈이 이쪽 손가락을 받아들인다. 손등, 손목.<br>문틈은 손가락 하나 들어갈 틈이다. 거기로 팔이 들어간다. 뼈가 접히는 소리는 나지 않는다. 그냥 들어간다.<br><br>문 너머에서 기쁜 목소리가 말한다. 손만요. 그다음은 팔만요.`,
        dieText:`문은 끝까지 열리지 않았다.<br><br>문 밑 틈으로 손이 둘 나와 있다. 손바닥을 위로 펴서. 하나는 찢어져 있고 하나는 붕대를 감았다.<br>문 너머에서 작게 말한다. 문은 열지 마세요.` },
      ok:`손을 맞잡고 마력을 흘리되 이쪽 손목에 실을 감았다. 그 실을 일행에게 쥐여 주었다.<br><br>상처가 닫히자 손이 당긴다. 일행이 실을 당겼다. 손이 떨어졌다. 문틈이 아쉽게 다문다.<br>닫힌 상처는 닫힌 채다. 문 너머에서 한참 손바닥을 비비는 소리가 났다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'어둠 — 다시 벌어지는 흉터',
  x:`어둠이 짙은 데를 지나는데 일행 하나가 팔을 움켜쥔다.<br><br>
    오래된 흉터다. 몇 해 전에 아문 것. 그게 다시 벌어진다. 천천히, 아문 순서를 거꾸로.<br>
    다른 일행도 하나씩 흉터를 짚는다. 무릎, 이마, 손등.<br><br>
    어둠 안쪽에서 무엇이 오래된 상처를 부른다.`,
  o:[
    { l:'① 흉터마다 손을 얹어 아문 순서를 다시 일러 준다.', k:'heal', dc:22, wake:1,
      ok:`벌어지는 흉터에 손바닥을 얹었다. 그 상처가 처음 났을 때를 물었다. 무엇에 다쳤는지, 누가 묶어 줬는지, 며칠 만에 아물었는지.<br><br>대답할 때마다 흉터가 다시 닫힌다. 한 겹씩. 아문 순서대로. 상처는 제가 아문 이야기를 기억한다.<br>다섯의 흉터를 다 닫았다. 어둠 안쪽에서 부르는 소리가 맥이 빠진다.<br><br>마력보다 앞서 말로 닫았다. 상처의 기억을 쥐는 법. 손이 그걸 붙잡았다.`,
      ng:`묻는데 그 사람이 기억을 못 한다. 언제 다쳤는지. 누가 묶어 줬는지.<br><br>흉터가 계속 벌어진다. 붉은 속살이 드러난다. 마력으로 겨우 덮었다. 덮은 자리가 고르지 않다.<br>어둠을 빠져나오고 나서야 피가 멎었다.`,
      win:{ exp:22, dream:3, hp:10 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 일행을 뒤로 물리고 어둠의 가장자리를 돌아간다.', k:'bond', dc:21,
      ok:`흉터 짚는 일행들을 한 사람씩 뒤로 끌었다. 어둠의 가장자리를 따라 벽에 붙어 돌았다.<br><br>멀어질수록 흉터가 잠잠해진다. 다 돌고 나서 보니 다들 흉터가 그대로다. 조금 붉을 뿐.<br>어둠 안쪽에서 무언가 혀를 찬다. 오래된 상처를 아쉬워하는 소리다.`,
      ng:`물리는데 하나가 버틴다. 어둠 쪽을 본다. 거기서 처음 다친 날이 보인다고 한다.<br><br>억지로 끌었다. 그 사람 이마 흉터가 다 벌어졌다. 피가 눈으로 흐른다.<br>앞이 안 보이는 그 사람 손을 잡고 걸었다. 오래.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'마지막 쉼 — 남은 마력',
  x:`내려가기 전, 마지막 쉼이다. 다 다쳤다.<br><br>
    마력이 조금 남았다. 다섯을 다 닫기에는 모자라다. 하나를 깊게 닫으면 넷이 그대로다.<br>
    상처를 닫아 온 손은 이런 셈을 매일 한다. 오늘은 셈이 무겁다.<br><br>
    아래층은 이보다 나쁠 것이다. 다들 안다.`,
  o:[
    { l:'① 남은 마력을 얇게 펴서 다섯을 덮는다.', k:'heal', dc:22, cost:{ mana:30 }, wake:1,
      ok:`손바닥을 펴고 마력을 얇게, 더 얇게 폈다. 다섯을 다 덮을 때까지.<br><br>얇은 마력은 깊은 상처를 못 닫는다. 대신 상처마다 피를 멎게 하고 열을 내린다. 다섯이 다 걸을 수 있게 된다.<br>그 이상은 몸이 할 일이다.<br><br>모자란 것을 고르게 나누는 손. 한 사람을 살리는 손에서 여럿을 걷게 하는 손으로, 손이 넓어졌다.`,
      ng:`펴는데 마력이 군데군데 끊긴다. 얇게 펴면 찢어진다.<br><br>셋은 덮었고 둘은 못 덮었다. 그 둘에게는 붕대만 감았다.<br>마력이 바닥나 손이 떨린다. 아래층에 내려가서도 한참 떨렸다.`,
      win:{ exp:24, dream:3, hp:8 }, lose:{ mind:-20, spirit:-22 } },
    { l:'② 제일 깊은 하나만 끝까지 닫는다.', k:'fix', dc:21,
      ok:`제일 깊은 상처를 골랐다. 옆구리다. 남은 마력을 다 거기에 넣었다.<br><br>닫혔다. 흉도 없다. 그 사람이 일어나 걷는다. 가장 무거운 짐을 진다. 나머지 넷의 짐까지.<br>넷의 상처는 붕대로 버텼다. 짐이 가벼우니 버틸 만했다.`,
      ng:`닫는데 옆구리 안쪽이 생각보다 깊다. 마력이 바닥에 닿기 전에 떨어졌다.<br><br>반만 닫혔다. 넷은 그대로다. 아무도 원망하지 않았다.<br>그게 더 무겁다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'분장실 — 분 밑의 얼굴',
  x:`분장실 거울 앞에서 일행 하나가 멍하니 앉아 있다.<br><br>
    얼굴이 하얗다. 분을 두드렸다. 누가 두드려 줬는지 모른다고 한다.<br>
    분 밑 살갗이 이상하다. 볼이 당겨 올라가 있다. 입꼬리 쪽으로. 웃는 모양으로 굳어 간다.<br><br>
    상처는 아니다. 그런데 상처를 닫는 손이 보기에는 상처다. 얼굴이 제 모양을 잃고 있다.`,
  o:[
    { l:'① 분을 닦아 내고 굳은 살을 손으로 풀어 준다.', k:'heal', dc:22, wake:1,
      ok:`맑은 물을 적신 천으로 분을 닦았다. 천천히. 닦을수록 분이 진하게 묻어 나온다. 몇 겹이다.<br><br>맨살이 드러나자 엄지로 볼을 눌러 풀었다. 굳은 근육을 결대로. 입꼬리가 한 치씩 내려온다. 그 사람이 숨을 크게 쉰다. 얼굴이 다시 제 것이다.<br><br>베이고 찢긴 것만 상처가 아니다. 모양을 잃는 것도 상처다. 손이 그 상처를 알아보기 시작했다.`,
      ng:`닦는데 분이 끝없이 나온다. 천이 하얗게 젖는다.<br><br>닦은 자리가 도로 하얘진다. 거울 속 넷째 의자에 앉은 것이 분첩을 두드린다. 이쪽 일행 볼에 맞춰.<br>그 사람을 거울 앞에서 끌어냈다. 입꼬리가 반쯤 올라간 채 굳었다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 거울을 등지게 돌려 앉힌다.', k:'steady', dc:21,
      ok:`의자를 돌려 거울을 등지게 했다. 그 사람 어깨를 붙잡고 기다렸다.<br><br>거울 쪽에서 분첩 두드리는 소리가 난다. 탁, 탁. 그러다 멈춘다. 등을 보인 얼굴에는 분을 바를 수 없다.<br>한참 지나 볼이 풀렸다. 그 사람이 손으로 제 얼굴을 만진다. 처음 만져 보는 것처럼.`,
      ng:`돌려 앉히는데 그 사람이 고개를 돌린다. 거울 쪽으로. 목이 끝까지.<br><br>붙잡아도 돌아간다. 거울 속에서 누가 부른다고 한다. 분 다 안 발랐다고.<br>눈을 손으로 가리고 끌고 나왔다. 그 사람 목이 한참 뻣뻣했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'의상실 — 숨 쉬는 인형탈',
  x:`의상실 옷걸이에 인형탈이 줄지어 걸려 있다. 방글이, 뭉치, 삐뚤이.<br><br>
    끝에서 둘째 뭉치 탈이 숨을 쉰다. 배가 오르내린다. 안에서 쌕쌕 소리가 난다.<br>
    숨이 짧고 얕다. 열이 오른 숨이다. 안에 누가 있다면 많이 아프다.<br><br>
    탈 등에 지퍼가 있다. 반쯤 내려와 있다. 안쪽이 어둡다.`,
  o:[
    { l:'① 지퍼를 끝까지 내려 안의 사람을 꺼낸다.', k:'heal', dc:23,
      doom:{ title:'뭉치 탈', what:'인형탈이 덮어씌워져 숨이 막힙니다', dc:18, sec:45,
        text:`지퍼를 끝까지 내렸다. 안에 손을 넣었다. 따뜻하다. 솜이다. 사람은 없다.<br><br>쌕쌕 소리가 바로 귀 옆에서 난다. 탈이 고개를 숙인다. 머리 구멍이 이쪽 머리 위로 내려온다. 털이 얼굴을 덮는다.<br>등 뒤에서 지퍼가 올라간다. 천천히. 끝까지. 좀약 냄새. 안쪽 솜이 입과 코를 막는다.<br><br>숨이 짧아진다. 얕아진다. 열이 오른 숨이다. 아까 들은 숨이다.`,
        dieText:`의상실 옷걸이 끝에서 둘째 뭉치 탈이 숨을 쉰다.<br><br>배가 오르내린다. 쌕쌕. 아까보다 숨이 조금 길다. 어른 숨이다.<br>지퍼는 반쯤 내려와 있다. 다음 사람이 손을 넣기 좋게.` },
      ok:`지퍼를 내리기 전에 탈 머리를 옷걸이에서 벗겨 바닥에 내려놓았다. 머리와 몸을 떼어 놓았다.<br><br>지퍼를 내리자 안은 솜뿐이다. 쌕쌕 소리가 바닥에 놓인 머리에서 난다. 머리 혼자 숨을 쉰다. 숨 쉴 데가 없어 답답한 숨이다.<br>머리를 엎어 두고 나왔다. 숨소리가 바닥에 막혀 둥글게 울렸다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 탈 위로 마력을 얇게 흘려 안을 더듬는다.', k:'sense', dc:22, cost:{ mana:30 },
      ok:`손바닥을 탈 배에 대고 마력을 얇게 흘렸다. 안쪽이 손끝에 그려진다.<br><br>솜, 철사, 단추. 사람은 없다. 숨은 솜이 쉰다. 다친 숨을 흉내 내는 솜이다. 상처 냄새를 맡고 오는 손을 기다린다.<br>손을 거두었다. 탈 배가 한참 더 오르내리다가 멈췄다. 기다리던 손이 안 왔다.`,
      ng:`흘린 마력을 솜이 빨아들인다. 탈 배가 부풀어 오른다. 크게 숨을 들이쉰다.<br><br>탈이 기침을 한다. 이쪽 기침 소리로. 그리고 말한다. 따뜻하다.<br>손을 떼고 물러났다. 마력이 반이 비었다. 손바닥에 털이 붙어 떨어지지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 아픈 숨소리를 외면하고 지나간다.', k:'steady', dc:21,
      ok:`숨소리를 등지고 걸었다. 상처를 닫는 사람에게 제일 어려운 걸음이다.<br><br>의상실 문을 나설 때 숨소리가 바뀐다. 쌕쌕이 웃음이 된다. 작게. 키득키득.<br>안 아팠던 것이다. 문을 닫았다. 손이 떨렸다. 속은 것보다 속을 뻔한 손이 무섭다.`,
      ng:`등지고 걷는데 숨소리가 끊긴다. 뚝.<br><br>멈춘 숨은 상처를 닫는 사람에게 칼이다. 다리가 굳었다. 돌아봤다. 탈이 옷걸이에서 고개를 숙여 이쪽을 보고 있다.<br>돌아본 걸 탈이 안다. 의상실을 나와서도 그 숨이 등에 붙어 따라왔다.`,
      win:{ exp:16, dream:2, mind:8 }, lose:{ mind:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'방청석 — 터진 손바닥',
  x:`방청석에서 박수 표지판에 불이 들어왔다. 스피커에서 박수가 쏟아진다.<br><br>
    일행 하나가 따라 친다. 멈추지 않는다. 표지판 불이 꺼져도 친다.<br>
    손바닥이 벌겋다. 터졌다. 피가 튄다. 그래도 친다. 박자가 정확하다.<br><br>
    얼굴은 웃는다. 눈은 운다.`,
  o:[
    { l:'① 손목을 붙잡고 마력으로 박자를 끊는다.', k:'heal', dc:23, cost:{ mana:25 }, wake:1,
      ok:`두 손목을 붙잡았다. 손바닥이 마주 닿기 직전에 마력을 손목 안쪽으로 밀어 넣었다. 박자를 쥔 데를.<br><br>마력이 걸리는 데가 있다. 손목 안쪽 힘줄에 무언가가 감겨 있다. 실이다. 보이지 않는 실. 마력으로 끊었다. 손이 툭 떨어진다.<br>터진 손바닥을 닫았다. 그 사람이 운다. 이번엔 얼굴도 운다.<br><br>상처 안에 감긴 것을 마력으로 끊었다. 닫는 데만 쓰던 마력이 끊는 데도 쓰였다. 손이 그 쓰임을 알았다.`,
      ng:`붙잡았는데 그 사람 손이 이쪽 손을 끼고 박수를 친다. 이쪽 손바닥도 같이.<br><br>짝, 짝. 박자에 맞춰. 이쪽 손도 멈추지 않는다. 손바닥이 터진다.<br>일행 둘이 덮쳐 겨우 떼어 놓았다. 손바닥이 둘 다 붉게 부었다. 스피커가 환호했다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 손바닥에 붕대를 두껍게 감아 소리를 죽인다.', k:'fix', dc:22,
      ok:`붕대를 두껍게 감았다. 칠 때마다 한 바퀴씩. 손바닥이 솜뭉치가 됐다.<br><br>박수가 소리를 잃는다. 퍽, 퍽. 스피커 박자와 안 맞는다. 맞지 않으니 손이 점점 느려진다.<br>마침내 멈췄다. 붕대를 풀자 손바닥이 터진 채로 굳어 있다. 그건 닫으면 된다.`,
      ng:`감는데 박자가 빨라진다. 붕대가 감기기 전에 풀린다.<br><br>붕대 끝이 피에 젖어 사방으로 튄다. 의자에, 이쪽 얼굴에.<br>박자가 끝날 때까지 기다리는 수밖에 없었다. 그 사람 손바닥이 뼈가 보일 만큼 터졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A1', t:'부조정실 — 화면 속의 다친 아이',
  x:`부조정실 모니터 벽 한가운데 화면에 아이가 있다. 세트 바닥에 쓰러져 있다.<br><br>
    무릎이 깨졌다. 피가 난다. 아이가 울며 카메라를 본다. 아파요.<br>
    아무도 안 온다. 화면 속 무대 감독은 카드를 든 채 서 있다. 계속 갑니다.<br><br>
    화면이 이쪽에 가깝다. 손을 뻗으면 닿는다. 유리가 미지근하다.`,
  o:[
    { l:'① 화면에 손을 대고 마력을 보낸다.', k:'heal', dc:23,
      doom:{ title:'생방송 사고', what:'화면 속으로 손부터 빨려 들어갑니다', dc:18, sec:50,
        text:`화면에 손바닥을 댔다. 마력을 보냈다. 화면 속 아이 무릎이 닫힌다. 아이가 웃는다.<br><br>손바닥이 유리에 붙는다. 유리가 물러진다. 손가락이 유리 안으로 들어간다. 화면 속 세트의 공기가 손끝에 닿는다. 조명 열기다.<br>아이가 이쪽 손을 잡는다. 고마워요. 당긴다. 팔이 화면 안으로. 화면 속 무대 감독이 카드를 뒤집는다. 출연자 추가.<br><br>부조정실의 다른 화면들이 하나씩 이쪽 얼굴을 비춘다. 웃으라고.`,
        dieText:`다섯 시, 방송이 나갔다.<br><br>세트 바닥에 아이가 넘어진다. 무릎이 깨진다. 어른이 달려와 무릎을 감싼다. 손에서 빛이 난다.<br>아이가 웃는다. 어른도 웃는다. 입이 얼굴보다 길다. 매회 같은 장면이다.` },
      ok:`손을 대기 직전에 멈췄다. 화면 속 아이 무릎을 다시 봤다. 피가 흐르는 방향이 위쪽이다.<br><br>거꾸로 흐르는 피는 피가 아니다. 무대용 물감이다. 아이가 우는 박자가 녹음 박자다.<br>손을 거두자 화면 속 아이가 울음을 뚝 그친다. 무대 감독이 카드를 뒤집는다. 다시 갑니다.`,
      win:{ exp:22, dream:3, mind:8 } },
    { l:'② 그 화면의 전원 단추를 찾아 끈다.', k:'fix', dc:22,
      ok:`화면 밑 조정판에 단추가 줄지어 있다. 화면 번호를 맞춰 하나를 눌렀다.<br><br>아이가 꺼진다. 까만 화면에 부조정실이 비친다. 이쪽 뒤에 아무도 없다. 다행이다.<br>조정판 밑 서랍에 구급함이 있다. 방송국 직원용이다. 깨끗한 붕대와 꿀 연고. 챙겼다.`,
      ng:`단추를 누르자 그 화면이 아니라 옆 화면이 꺼진다. 그 옆도. 하나씩.<br><br>아이 화면만 남는다. 부조정실이 그 빛 하나로 밝다. 아이가 울음을 그치고 이쪽을 본다. 왜 안 와요.<br>그 질문이 오래 귀에서 안 떠났다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A1', t:'인형극 무대 — 실밥이 터진 손 인형',
  x:`인형극 무대 막 앞에 손 인형이 하나 떨어져 있다. 토끼 모양이다.<br><br>
    옆구리 실밥이 터졌다. 솜이 비어져 나왔다. 솜이 붉다. 젖어 있다.<br>
    인형이 아주 조금 꿈틀댄다. 터진 데를 오므리려는 것처럼.<br><br>
    상처를 다뤄 온 손은 이걸 그냥 두기 힘들다. 그게 천이어도.`,
  o:[
    { l:'① 실과 바늘로 터진 데를 꿰매 준다.', k:'heal', dc:22,
      ok:`실을 꿰어 터진 데를 꿰맸다. 촘촘히. 상처 꿰매듯.<br><br>다 꿰매자 붉은 것이 더 안 샌다. 인형이 꿈틀대기를 멈춘다. 가만히 누워 있다. 잠든 것처럼.<br>막 뒤에서 작은 박수 소리가 난다. 손가락 몇 개로 치는 박수다. 막 아래로 꿀 사탕 하나가 굴러 나왔다.`,
      ng:`꿰매는데 바늘이 안쪽에서 무언가에 걸린다. 딱딱하다. 뼈 같다.<br><br>인형이 비명을 지른다. 막 뒤에서 여러 목소리가 같이 지른다. 바늘을 뺐다. 바늘 끝이 붉다.<br>인형을 내려놓고 물러섰다. 막이 출렁인다. 안에서 손들이 막을 짚는다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 붉은 솜을 응시해 무엇이 배었는지 본다.', k:'gaze', dc:21,
      ok:`등잔을 대고 들여다봤다. 붉은 솜에서 단내가 난다. 피가 아니다. 딸기 시럽이다. 촬영용이다.<br><br>꿈틀대는 것도 솜이 아니다. 인형 안에 손가락이 하나 들어 있다. 인형을 움직이던 손가락. 손은 없고 손가락만.<br>그대로 두고 지나갔다. 막 뒤에서 손가락 하나가 모자란 박수 소리가 났다.`,
      ng:`들여다보는데 인형 단추 눈이 이쪽을 본다. 바느질한 입이 열린다.<br><br>아파. 이쪽 목소리다. 아까 이쪽이 계단에서 넘어졌을 때 낸 소리다.<br>그 뒤로 넘어질 때마다 그 소리를 참았다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'양호실 — 보건 일지의 빈칸',
  x:`양호실 셋째 침대에 커튼이 쳐져 있다. 안에서 체온계 흔드는 소리. 탁, 탁, 탁.<br><br>
    책상 위에 보건 일지가 펼쳐져 있다. 날짜, 이름, 증상, 처치. 마지막 줄의 처치 칸이 비었다.<br>
    증상 칸에 적혀 있다. 숨이 차다. 물이 목까지 왔다.<br><br>
    상처를 닫는 사람은 빈 처치 칸을 못 본 척하기 어렵다.`,
  o:[
    { l:'① 처치 칸을 채운다. 해야 했던 처치를 적는다.', k:'heal', dc:22, wake:1,
      ok:`연필을 들었다. 숨이 차고 물이 목까지 온 사람. 해야 할 처치를 적었다. 높은 데로 옮길 것. 등을 두드릴 것. 혼자 두지 말 것.<br><br>적고 나니 커튼 안 체온계 소리가 멈춘다. 한참 조용하다. 그러다 커튼 아래 물이 조금 빠진다. 한 뼘쯤.<br>일지의 증상 칸 글씨가 번지며 바뀐다. 숨이 덜 차다.<br><br>손을 대지 않고 글로 처치했다. 무엇을 해야 하는지 아는 것이 손보다 먼저 닿을 때가 있다. 그 사실을 손이 받아들였다.`,
      ng:`적는데 연필이 물에 불어 글씨가 번진다. 처치 칸이 검게 젖는다.<br><br>커튼 안 체온계 소리가 빨라진다. 탁탁탁탁. 커튼 밑 물이 올라온다.<br>연필을 놓고 물러섰다. 일지 처치 칸에 번진 글씨가 남았다. 읽을 수 없다. 늦었다는 뜻 같다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-18, spirit:-26 } },
    { l:'② 약장 위 칸에서 쓸 것을 챙긴다.', k:'luck', dc:21,
      ok:`약장 위 칸은 물 밖이다. 팔을 뻗어 열었다. 소독약, 거즈, 반창고. 그리고 꿀 단지.<br><br>꿀 단지 뚜껑에 쪽지. 한 숟갈만. 욕심내면 혼나요.<br>한 숟갈만 떠서 상처에 발랐다. 나머지는 챙겼다. 커튼 안에서 체온계 소리가 잠깐 멈췄다 다시 났다. 괜찮다는 박자로.`,
      ng:`팔을 뻗는데 약장 문이 안쪽으로 열린다. 위 칸이 아니라 벽 속으로.<br><br>안에서 젖은 손이 이쪽 손목을 짚는다. 맥을 짚듯이. 오래. 숫자를 센다. 작게.<br>손을 빼냈다. 손목이 시리다. 맥이 한동안 그 손 박자로 뛰었다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-22 } },
    { l:'③ 커튼을 걷고 셋째 침대의 환자를 본다.', k:'heal', dc:24,
      doom:{ title:'셋째 침대', what:'환자 대신 침대에 눕혀져 물 밑으로 가라앉습니다', dc:19, sec:45,
        text:`커튼을 걷었다. 침대가 비었다. 시트가 오목하다. 체온계가 혼자 흔들린다.<br><br>상처 닫는 사람의 손이 시트를 짚는다. 차다. 아까까지 누가 있었다. 어디 갔는지 보려고 몸을 숙였다.<br>등을 누르는 손이 있다. 부드럽게. 보건 선생님 손이다. 누워요, 열이 있네. 무릎이 접힌다. 등이 시트에 닿는다. 시트가 물속에 있다.<br><br>체온계가 입에 물린다. 침대가 가라앉는다. 천천히. 커튼이 다시 쳐진다.`,
        dieText:`양호실 셋째 침대에 커튼이 쳐져 있다.<br><br>안에서 체온계 흔드는 소리. 탁, 탁, 탁.<br>보건 일지 마지막 줄 아래에 한 줄이 늘었다. 처치 칸에는 다른 글씨로 적혀 있다. 누워 있을 것.` },
      ok:`커튼 끝을 손가락 하나로만 걷었다. 몸은 커튼 밖에 둔 채.<br><br>침대가 비었다. 시트가 오목하다. 베개 밑에 체온계가 아니라 붕대 감은 손목이 하나 나와 있다. 손목에 이름표. 3학년 2반 17번. 맥을 짚어 봤다. 없다.<br>붕대를 고쳐 감아 주고 커튼을 닫았다. 체온계 소리가 조금 느려졌다.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A2', t:'세면장 — 불어 버린 손',
  x:`세면장 물에 손을 씻은 일행 하나가 손을 들여다본다.<br><br>
    손이 불었다. 하얗고 쭈글쭈글하다. 금방 씻었을 뿐인데 오래 물에 잠긴 손 같다.<br>
    불은 데가 손목을 지나 팔꿈치 쪽으로 올라간다. 천천히.<br><br>
    세면대 거울에 비친 그 사람 손은 이미 어깨까지 하얗다.`,
  o:[
    { l:'① 마력으로 살 속의 물을 짜낸다.', k:'heal', dc:23, cost:{ mana:30 },
      ok:`그 사람 팔을 두 손으로 쥐고 마력을 손끝 쪽으로 훑어 내렸다. 짜내듯이.<br><br>손끝에서 물이 똑똑 떨어진다. 차고 비리다. 한 그릇은 나왔다. 손이 조금씩 제 색으로 돌아온다.<br>세면대 거울 속 손도 손목까지 돌아왔다. 어깨에 남은 하얀 것은 천으로 감아 두었다.`,
      ng:`훑어 내리는데 물이 거꾸로 올라온다. 마력을 타고 이쪽 손으로.<br><br>이쪽 손끝이 불기 시작한다. 하얗게. 손을 뗐다. 둘 다 손이 쭈글쭈글하다.<br>세면대 배수구에서 꾸르륵 소리가 난다. 손이 많아졌다고 좋아하는 소리다.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 마른 천으로 세게 문질러 피를 돌린다.', k:'heal', dc:22,
      ok:`마른 천으로 팔을 문질렀다. 손끝에서 어깨 쪽으로. 세게. 살갗이 벌게질 때까지.<br><br>벌건 데는 하얗게 돌아가지 않는다. 피가 도는 살은 물을 밀어낸다.<br>한참 문지르고 나서 그 사람 손을 쥐어 보았다. 미지근하다. 마른 손이다.`,
      ng:`문지르는데 살갗이 천에 묻어 벗겨진다. 불은 살은 약하다.<br><br>천이 젖는다. 피가 아니라 물로. 그 사람이 아프다고 한다. 멀리서 말하는 것처럼.<br>문지르기를 멈추고 붕대로 감았다. 붕대 위로 물이 배어 나온다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A2', t:'기숙사 — 맞춰지는 숨',
  x:`기숙사 방에 침대가 열둘이다. 다 비었다. 숨소리는 열둘이다.<br><br>
    고르고 느린 숨. 다 같은 박자로. 잠든 아이들 숨이다.<br>
    일행 하나가 침대 끝에 걸터앉아 졸고 있다. 그 사람 숨도 같은 박자다.<br><br>
    상처를 닫아 온 사람은 숨을 들으면 안다. 남의 박자에 맞춘 숨은 제 몸을 덜 쓴다. 점점 덜.`,
  o:[
    { l:'① 숨을 하나씩 세어 일행 숨만 가려낸다.', k:'sense', dc:22, wake:1,
      ok:`눈을 감고 숨을 셌다. 열둘, 열셋. 열셋째가 일행이다. 숨 끝에 아주 작게 쇳소리가 난다. 아까 다친 갈비 탓이다.<br><br>그 소리만 따라가 어깨를 짚었다. 그 사람 숨이 박자에서 미끄러진다. 기침을 한다. 깬다.<br>열둘의 숨이 잠깐 엉킨다. 다시 고르게 맞춰진다. 열둘로.<br><br>숨 속의 상처를 들었다. 다친 데가 그 사람을 그 사람으로 남겨 두었다. 귀가 손만큼 많이 아는 날이었다.`,
      ng:`세는데 이쪽 숨도 같은 박자다. 언제부터인지 모른다.<br><br>세다 보니 열넷이다. 이쪽이 열넷째다. 눈꺼풀이 무겁다. 침대가 하나 비어 있다. 이쪽 크기다.<br>입술을 깨물어 깼다. 피 맛이 박자를 끊었다. 일행은 그때까지 졸고 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 일행 가슴에 손을 얹고 이쪽 숨을 들려준다.', k:'bond', dc:21,
      ok:`그 사람 가슴에 손을 얹었다. 귀를 그 사람 귀 가까이 대고 일부러 숨을 크게, 빠르게 쉬었다. 깨어 있는 숨으로.<br><br>그 사람 숨이 이쪽 박자로 끌려온다. 점점 빨라진다. 눈을 뜬다. 왜 이렇게 숨이 차냐고 묻는다.<br>열둘의 숨이 한 박자 늦게 따라온다. 그러다 포기한다.`,
      ng:`이쪽 숨을 들려주는데 그 사람 숨이 안 따라온다. 오히려 이쪽 숨이 느려진다.<br><br>열둘이 이쪽까지 데려가려 한다. 무릎이 침대 끝에 닿았다. 앉으면 끝이다.<br>일행 하나가 이쪽 등을 쳐서 깨웠다. 졸던 사람은 끝까지 졸았다. 업어서 나왔다.`,
      win:{ exp:16, dream:2, mind:8 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'수영장 — 물 위로 올라온 손',
  x:`수영장 레인 한가운데서 손이 올라온다. 하나. 손가락을 벌리고.<br><br>
    허우적거린다. 물 위로 올라왔다 내려갔다. 물에 빠진 사람 손이다.<br>
    상처를 닫는 사람은 저 손을 보면 몸이 먼저 물가로 간다. 꺼내야 살린다.<br><br>
    레인 줄에 사람 수만큼 부표가 떠 있다. 하나가 모자란다.`,
  o:[
    { l:'① 엎드려 그 손을 잡아 끌어 올린다.', k:'heal', dc:24,
      doom:{ title:'빠진 사람', what:'잡은 손에 잡혀 레인 바닥으로 끌려갑니다', dc:19, sec:45,
        text:`물가에 엎드려 손을 뻗었다. 그 손이 이쪽 손을 쥔다. 세게. 빠진 사람은 늘 세게 쥔다.<br><br>당겼다. 안 올라온다. 무겁다. 한 사람 무게가 아니다. 손 밑으로 손이 이어져 있다. 그 밑에도.<br>물 밑에서 당긴다. 이쪽 어깨가 물에 잠긴다. 얼굴이 수면에 닿는다. 물이 차다. 물속에서 눈들이 이쪽을 올려다본다. 다 기다렸다는 눈이다.<br><br>레인 줄 부표 하나가 소리 없이 늘었다.`,
        dieText:`수영장 레인 한가운데서 손이 올라온다. 둘이다.<br><br>하나는 허우적거린다. 하나는 허우적거리는 손을 붙잡으려 애쓴다. 끝까지.<br>레인 줄에 부표가 모자라지 않는다.` },
      ok:`엎드리기 전에 허리에 줄을 감아 일행에게 쥐였다. 그리고 손 대신 소매를 내밀었다.<br><br>손이 소매를 쥔다. 당긴다. 줄이 팽팽해진다. 일행이 버틴다. 소매가 찢어지며 손이 물 밑으로 돌아간다. 찢긴 소매 조각을 쥔 채.<br>잡히는 건 놓을 수 있어야 한다. 소매는 놓을 수 있다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 장대를 내밀어 잡게 한다.', k:'fix', dc:22,
      ok:`벽에 걸린 구조 장대를 내렸다. 끝을 손 쪽으로 내밀었다.<br><br>손이 장대를 쥔다. 당긴다. 장대가 물속으로 쑥 끌려간다. 손을 놓았다. 장대가 끝까지 들어가 보이지 않는다.<br>그 뒤로 손이 더 올라오지 않았다. 원하던 것을 받았다. 이쪽은 아니었다.`,
      ng:`장대를 내미는데 손이 장대가 아니라 장대를 쥔 이쪽 손 쪽으로 기어 온다. 손가락으로 장대를 타고.<br><br>장대를 버렸다. 손가락 끝이 이쪽 손등에 닿았다가 미끄러졌다. 차다.<br>손등에 물 자국이 손가락 모양으로 남아 한참 안 말랐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 물 위에 마력을 깔아 손 아래를 비춰 본다.', k:'sense', dc:23, cost:{ mana:25 },
      ok:`수면에 손을 대고 마력을 얇게 깔았다. 물 밑이 어렴풋이 보인다.<br><br>손 밑에 몸이 없다. 손만 있다. 팔꿈치에서 끊긴 손이 줄에 매달려 허우적거린다. 줄 끝은 배수구로 간다. 누가 당겼다 놓았다 한다.<br>마력을 거두고 물러섰다. 배수구 쪽에서 줄 당기는 박자가 멈췄다. 들킨 걸 안다.`,
      ng:`마력을 까는데 물이 마력을 받아 하얗게 빛난다. 물 밑의 것들이 일제히 올려다본다.<br><br>손이 하나가 아니다. 수십이다. 레인마다. 다 허우적거리기 시작한다. 이쪽을 향해.<br>마력을 끊고 뛰었다. 등 뒤 물소리가 탈의실 문 앞까지 따라왔다.`,
      win:{ exp:20, dream:3 }, lose:{ mind:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'강당 가는 계단 — 숨 안 쉬는 동료',
  x:`물 밑 계단을 지나 숨을 쉬는 데로 올라왔다. 일행 하나가 늦게 올라왔다.<br><br>
    끌어 올렸다. 숨을 안 쉰다. 입술이 파랗다. 가슴이 안 움직인다.<br>
    상처를 닫아 온 손은 이 순간을 안다. 손이 할 수 있는 일이 아주 적은 순간이다.<br><br>
    물 밑에서 누가 그 사람 이름을 부른다. 출석을 부르는 목소리로.`,
  o:[
    { l:'① 고개를 젖히고 숨을 불어 넣는다.', k:'heal', dc:23, wake:1,
      ok:`고개를 젖혔다. 숨을 불어 넣었다. 가슴을 눌렀다. 서른 번. 다시 불었다.<br><br>물 밑에서 이름을 다시 부른다. 대답하지 말라고 그 사람 귀에 대고 말했다. 다시 눌렀다.<br>일곱째 바퀴에 그 사람이 물을 토한다. 기침한다. 숨을 쉰다. 물 밑의 목소리가 결석이라고 적는 소리가 난다.<br><br>마력도 약도 없이 손과 숨으로 돌려놓았다. 다른 것이 다 떨어져도 남는 것. 손이 그 바닥을 딛고 섰다.`,
      ng:`불어 넣는데 가슴이 안 오른다. 물이 막고 있다.<br><br>눌렀다. 물이 조금 나온다. 다시 불었다. 그 사람 입에서 대답이 새어 나온다. 네.<br>그 뒤로는 기침했다. 숨도 쉬었다. 그런데 그 사람이 한동안 이쪽 이름을 몰랐다.`,
      win:{ exp:24, dream:3, hp:10 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 마력으로 폐 속의 물을 끌어낸다.', k:'heal', dc:22, cost:{ mana:30 },
      ok:`가슴에 두 손을 겹쳐 대고 마력을 안으로 넣었다. 폐가 손끝에 그려진다. 물이 찼다.<br><br>마력으로 물을 감아 위로 끌었다. 목을 지나 입으로. 물이 한꺼번에 쏟아진다. 그 사람이 숨을 들이켠다. 크게.<br>쏟아진 물이 계단 쪽으로 흘러 내려간다. 제 갈 데로.`,
      ng:`물을 감아 끄는데 물이 마력을 거꾸로 당긴다. 아래로.<br><br>그 사람 몸이 계단 쪽으로 미끄러진다. 이쪽 손째로. 일행이 둘을 붙잡았다.<br>물은 반만 나왔다. 그 사람은 숨을 쉬었다. 쌕쌕거리며. 오래.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ hp:-26, spirit:-22 } }
  ] }

]);


// ------------------------------------------
// 약사 (pharma) · 자원 없음
// ------------------------------------------
kJob('pharma', 'A', [

{ at:'A', t:'쉬는 자리 — 이름 적힌 봉지',
  x:`불가에서 약 주머니를 풀었다. 하루에 한 번 약을 센다.<br><br>
    봉지가 하나 늘었다. 이번엔 착각이 아니다. 봉지 겉에 이쪽 이름이 적혀 있다. 모르는 글씨다.<br>
    그 밑에 복용법. 잠들기 전에. 한 봉 다.<br><br>
    약을 다루는 사람은 남이 지어 준 약을 제일 무서워한다. 무엇을 넣었는지 모르니까.`,
  o:[
    { l:'① 봉지를 조금만 열어 냄새로 가린다.', k:'sense', dc:22, wake:1,
      ok:`봉지 귀퉁이만 찢어 냄새를 맡았다. 감초. 대추. 그 밑에 아주 옅게 쓴 꽃 냄새.<br><br>쓴 꽃은 잠을 깊게 하는 꽃이다. 깊게, 아주 깊게. 감초와 대추는 그 쓴맛을 덮으려고 넣었다. 처방이 친절하다. 친절한 독이다.<br>봉지를 불에 던졌다. 연기가 한참 이쪽 쪽으로만 기울었다.<br><br>무엇이 들었는지만이 아니라 왜 그것을 같이 넣었는지가 맡아졌다. 냄새 속에서 처방이 읽혔다. 코가 한 겹 깊어졌다.`,
      ng:`맡는데 아무 냄새가 안 난다. 냄새 없는 약은 쓰지 않는다. 그런데 손이 봉지를 놓지 않는다.<br><br>정신을 차리니 봉지를 입에 대고 있다. 혀끝에 가루가 묻었다. 침을 뱉고 물로 헹궜다.<br>그날 밤 잠이 무겁게 덮쳤다. 아침에 일행이 흔들어 깨웠다. 세 번째에 깼다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 봉지째 태우고 연기의 색을 본다.', k:'gaze', dc:21,
      ok:`봉지를 불에 올렸다. 타는 연기를 봤다. 하얀 연기는 풀이고 푸른 연기는 돌가루다.<br><br>연기가 회색이다. 끝이 조금 붉다. 붉은 끝은 사람 몸에서 난 것을 태울 때 난다. 머리카락이나 손톱.<br>누가 이쪽 것을 넣었다. 이쪽 몸에 맞추려고. 재를 흙으로 덮었다.`,
      ng:`태우는데 연기가 불가에 둘러앉은 일행 쪽으로 퍼진다. 하나씩 하품을 한다.<br><br>다들 쓰러지듯 잠들었다. 이쪽만 깨어 있다. 밤새 혼자 불을 지켰다.<br>불 너머 어둠에서 누가 일행 수를 센다. 이쪽이 깨어 있어서 하나가 모자란다고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'복도 — 약 먹을 시간',
  x:`복도 문 앞에 쟁반이 놓여 있다. 물 한 컵. 하얀 알약 하나.<br><br>
    문 너머에서 상냥한 목소리가 말한다. 약 먹을 시간이에요.<br>
    물이 맑다. 알약은 손으로 빚었다. 모서리가 둥글다. 약을 빚어 본 손은 이게 잘 빚은 약인 걸 안다.<br><br>
    쟁반 옆 바닥에 컵이 여럿 엎어져 있다. 다 빈 컵이다.`,
  o:[
    { l:'① 알약을 쪼개 속을 본다.', k:'gaze', dc:22,
      ok:`손톱으로 쪼갰다. 겉은 하얗고 속은 잿빛이다. 속에 아주 가는 털이 섞였다. 솜털이다.<br><br>약에 털을 넣는 처방은 없다. 털은 먹은 사람을 무엇에 묶을 때 넣는다. 그 무엇의 털이다.<br>알약 반쪽을 쟁반에 도로 놓았다. 문 너머에서 목소리가 묻는다. 다 먹었어요? 대답하지 않았다.`,
      ng:`쪼개는데 가루가 날린다. 들이마셨다.<br><br>문 너머 목소리가 가까이 들린다. 아주 가까이. 귀 안에서. 착하지. 이제 누워요.<br>무릎이 꺾였다. 일행이 겨드랑이를 끼고 끌고 갔다. 한참 그 목소리가 귀 안에서 칭찬했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 약은 두고 물만 수통에 따른다.', k:'luck', dc:21,
      ok:`물 컵만 들어 수통에 따랐다. 냄새를 맡았다. 아무 냄새 없다. 그냥 물이다. 약을 넘기라고 준 물이다.<br><br>알약은 쟁반에 그대로 두었다. 문 너머가 조용하다. 물만 가져가는 사람은 처음인 모양이다.<br>한참 있다가 목소리가 말한다. 물도 약이에요. 맞는 말이다.`,
      ng:`물을 따르는데 컵 바닥에 알약이 하나 더 녹아 있다. 녹은 지 오래다.<br><br>수통에 다 섞였다. 수통 물을 다 버렸다. 남은 물이 없다.<br>문 너머에서 목소리가 웃는다. 목마르면 와요.`,
      win:{ exp:16, dream:2, item:'맑은 물' }, lose:{ hp:-22, mind:-18 } },
    { l:'③ 무슨 약인지 알려면 혀 밑에 넣어 본다.', k:'sense', dc:23,
      doom:{ title:'약 먹을 시간', what:'잠든 채 문 안쪽으로 끌려갑니다', dc:18, sec:50,
        text:`알약을 혀 밑에 넣었다. 약을 다루는 사람은 모르는 약을 제 몸으로 안다.<br><br>쓰지 않다. 달다. 녹는 게 빠르다. 혀 밑 핏줄로 곧장 들어간다. 무슨 약인지 알았다. 알았을 때는 이미 눈이 감긴다.<br>문이 열린다. 상냥한 손이 이쪽 발목을 쥔다. 착하지. 끌려간다. 문턱이 등을 긁고 지나간다.<br><br>문 너머 방에 침대가 줄지어 있다. 다 찼다. 끝에 하나만 비었다.`,
        dieText:`다음 사람이 복도를 지날 때 문 앞에 쟁반이 놓여 있었다.<br><br>물 한 컵. 알약 하나. 알약 모서리가 조금 더 둥글다.<br>잘 빚은 약이다. 약을 빚어 본 손이 빚었다.` },
      ok:`혀 밑에 넣기 직전에 손등에 대고 침 한 방울을 떨어뜨렸다. 알약 끝이 녹는다. 빠르다.<br><br>이렇게 빨리 녹는 약은 깨어 있으라고 주는 약이 아니다. 알약을 문틈으로 밀어 넣어 돌려주었다.<br>문 너머에서 쟁반을 거두는 소리가 났다. 다음엔 꼭 먹어요.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A', t:'계단 — 거꾸로 오르는 독',
  x:`계단 틈에서 무언가가 동료 발등을 물고 사라졌다.<br><br>
    구멍 둘. 붓기가 번진다. 그런데 이상하다. 독은 피를 따라 퍼진다. 이건 피를 거슬러 간다. 발등에서 발가락 쪽으로, 다시 발목으로.<br>
    길을 고르는 독이다.<br><br>
    독이 고르는 길이면 묶어도 돌아갈 것이다.`,
  o:[
    { l:'① 독을 끌어내는 풀과 붓기를 빼는 풀을 섞어 붙인다.', k:'heal', dc:22, wake:1,
      ok:`두 가지 풀을 꺼냈다. 하나는 독을 당기고 하나는 붓기를 누른다. 따로 쓰면 서로 방해한다. 비율을 맞춰 같이 찧었다. 둘에 하나.<br><br>상처 위에 붙였다. 독이 당기는 쪽을 따라 구멍으로 모인다. 고르던 길을 잃었다. 길이 하나밖에 안 남았으니까.<br>검은 물이 배어 나온다. 붓기가 빠진다.<br><br>독이 길을 고르면 약은 길을 줄인다. 섞는 비율로 길을 막았다. 손이 비율을 길처럼 다루기 시작했다.`,
      ng:`찧어 붙였는데 비율이 틀렸다. 당기는 풀이 너무 세다.<br><br>독이 구멍으로 몰리다 못해 살갗을 뚫고 나온다. 발등에 구멍이 셋으로 늘었다.<br>동료가 소리를 지른다. 검은 물이 멎을 때까지 한참 걸렸다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 무릎과 발목 두 군데를 묶어 가둔다.', k:'fix', dc:21,
      ok:`발목 위를 묶었다. 독이 돌아간다. 무릎 아래도 묶었다. 독이 두 매듭 사이에 갇힌다.<br><br>갇힌 독이 종아리 안에서 맴돈다. 갈 데가 없다. 시간이 지나자 기운이 빠진다.<br>매듭을 하나씩 풀었다. 종아리가 시퍼렇다. 그래도 거기서 멈췄다.`,
      ng:`두 군데를 묶었는데 독이 매듭 밑으로 빠져나간다. 살갗 바로 밑으로 얕게.<br><br>무릎 위까지 올라갔다. 셋째 매듭을 허벅지에 묶었다. 그제야 섰다.<br>동료가 그날 내내 다리를 끌었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 연기의 비율',
  x:`어둠이 짙다. 앞에서 무언가가 기어 온다. 바닥 쓸리는 소리.<br><br>
    약 주머니에 쑥이 있다. 쓴 나무껍질, 매운 씨앗도 있다. 짐승을 쫓는 연기를 만드는 것들이다.<br>
    여기 것들이 짐승인지는 모른다. 그래도 코는 있을 것이다.<br><br>
    셋을 다 쓰면 다음은 없다.`,
  o:[
    { l:'① 셋을 비율 맞춰 섞어 낮게 깔리는 연기를 피운다.', k:'fix', dc:22, wake:1,
      ok:`쑥 둘, 껍질 하나, 씨앗 반. 젖은 천으로 감싸 불씨에 얹었다. 매운 연기가 바닥을 따라 깔린다.<br><br>기어 오던 소리가 멈춘다. 그리고 물러간다. 바닥을 긁으며 서둘러.<br>연기가 다 탈 때까지 다들 숨을 죽였다. 아무것도 다시 오지 않았다.<br><br>바닥을 기는 것에게는 바닥에 깔리는 연기. 무엇에게 쓰는지에 맞춰 비율을 바꾸는 법을 손이 잡았다.`,
      ng:`섞는데 쑥이 젖었다. 연기가 위로만 오른다.<br><br>기어 오던 것이 연기 밑으로 그대로 들어온다. 발목을 스친다. 차고 끈적하다.<br>뛰었다. 연기 냄새가 그것의 냄새와 섞여 한참 코에 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 연기를 몸에 쐬어 약 냄새를 입고 지난다.', k:'hide', dc:23,
      ok:`쑥 한 줌만 태워 옷에 연기를 쐬었다. 일행 모두. 몸에서 쓴 냄새가 난다.<br><br>어둠 속을 걸었다. 기어 오던 것이 바로 옆을 지난다. 킁킁대다 고개를 돌린다. 쓴 것은 먹을 것이 아니다.<br>약 냄새를 입으면 사람이 아니라 약이 된다. 약은 아무도 안 먹는다.`,
      ng:`쐬는데 연기가 모자란다. 둘은 냄새를 입었고 셋은 못 입었다.<br><br>기어 오던 것이 냄새 없는 셋 쪽으로 간다. 이쪽이 앞을 막아섰다. 정강이를 물렸다.<br>상처에서 쓴 냄새가 난다. 그것이 퉤 하고 뱉었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 부르는 소리를 듣는 사람',
  x:`일행 하나가 잠을 못 잔다. 누가 부른다고 한다. 밤새.<br><br>
    눈이 벌겋다. 손이 떨린다. 사흘째다. 이대로면 내일은 걷지 못한다.<br>
    약을 다루는 사람은 잠을 주는 약을 안다. 순한 것과 센 것. 센 것을 쓰면 부르는 소리도 못 듣는다. 다른 소리도.<br><br>
    부르는 소리는 잠든 사람에게 더 잘 닿는다.`,
  o:[
    { l:'① 순한 차를 연하게 달여 얕게 재운다.', k:'heal', dc:22,
      ok:`감초 부스러기와 말린 꽃 몇 송이. 약하게, 연하게 달였다. 잠이 들되 깊지 않게.<br><br>그 사람이 잠든다. 얕게. 부르는 소리가 오면 뒤척인다. 뒤척이면 깬다. 깨면 다시 잔다.<br>밤새 그렇게 잤다. 아침에 눈이 덜 벌겋다. 얕은 잠은 발목을 안 내준다.`,
      ng:`연하게 달였는데 그 사람이 한 모금에 깊이 잠든다. 지쳐서다.<br><br>밤에 그 사람이 잠든 채 일어나 문 쪽으로 걷는다. 붙잡았다. 셋이 매달렸다.<br>아침에 그 사람은 기억이 없다. 다리에 손자국이 남았다. 일행 것이 아니다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 쓴 뿌리를 씹게 해 밤새 깨어 있게 한다.', k:'steady', dc:21,
      ok:`쓴 뿌리를 한 토막 쥐여 주었다. 졸릴 때마다 씹으라고.<br><br>그 사람이 밤새 씹었다. 얼굴을 찡그리며. 쓴맛이 귀를 막는다. 부르는 소리가 쓴맛을 못 넘어온다.<br>새벽에 이쪽이 대신 깨어 있고 그 사람을 재웠다. 낮잠은 부르는 쪽도 잔다.`,
      ng:`씹게 했는데 쓴맛을 모른다고 한다. 혀가 둔해졌다.<br><br>이쪽이 씹어 보니 쓰다. 그 사람만 모른다. 부르는 쪽이 혀부터 가져갔다.<br>밤새 둘 다 못 잤다. 그 사람 손목을 이쪽 손목에 묶은 채.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 센 약을 짓고 효를 알려고 먼저 반 모금 마신다.', k:'sense', dc:23,
      doom:{ title:'반 모금', what:'깊은 잠에 빠진 채 부르는 쪽으로 끌려갑니다', dc:18, sec:50,
        text:`센 약을 지었다. 남에게 주기 전에 반 모금 먼저 마셨다. 늘 그렇게 해 왔다.<br><br>오늘따라 빨리 돈다. 지친 몸이라 그렇다. 눈꺼풀이 무겁다. 일행 목소리가 멀어진다.<br>대신 다른 소리가 가깝다. 부르는 소리다. 이쪽 이름이다. 잠든 사람에게 더 잘 닿는다. 다리가 일어선다. 끌려간다. 이쪽 다리가 아닌 것처럼.<br><br>약이 잘 들었다. 너무 잘.`,
        dieText:`그 밤 잠 못 들던 일행은 깊이 잤다. 남은 약을 먹었다.<br><br>아침에 둘이 없었다. 문밖 바닥에 맨발 자국이 둘. 나란히. 어둠 쪽으로.<br>약 주머니는 불가에 남았다. 봉지 하나에 새 이름이 적혀 있다.` },
      ok:`반 모금을 입에 머금었다가 뱉었다. 머금은 것만으로 혀가 무거워진다. 세다. 너무 세다.<br><br>약을 반으로 묽혔다. 그 사람에게 주었다. 잠이 들되 소리를 들으면 깰 만큼.<br>밤에 두 번 깼다. 두 번 다 이쪽을 찾았다. 부르는 소리를 따라가지 않았다.`,
      win:{ exp:22, dream:3, mind:8 } }
  ] },

{ at:'A', t:'통로 — 이름표 없는 병',
  x:`통로 바닥에 작은 유리병이 서 있다. 누가 세워 두었다. 똑바로.<br><br>
    안에 맑은 것이 반쯤. 마개는 밀랍이다. 이름표가 없다.<br>
    병을 세워 두는 건 약을 아는 사람 버릇이다. 눕히면 마개가 젖는다.<br><br>
    병 주위 바닥에 무엇인가 쓸고 간 자국이 둥글게 나 있다. 병만 피해서.`,
  o:[
    { l:'① 손등에 한 방울 떨어뜨려 본다.', k:'gaze', dc:22,
      ok:`밀랍을 살짝 들고 손등에 한 방울 떨어뜨렸다. 차갑다. 그다음 화끈하다. 그다음 아무 느낌이 없다.<br><br>살을 잠재우는 약이다. 아픈 데 바르는 것. 많이 바르면 살이 제 것인 줄 모른다.<br>병을 챙겼다. 쓰는 양을 아는 손에서는 약이다. 둥글게 쓸린 자국은 무엇이 이 병을 꺼렸다는 뜻이다.`,
      ng:`떨어뜨린 자리가 감각을 잃는다. 손등 전체가. 손목까지.<br><br>손을 쥐었다 폈다 해 봐도 남의 손 같다. 그 손이 저절로 병을 쥔다. 쥔 채 놓지 않는다.<br>반나절 지나서야 손이 돌아왔다. 병은 깨졌다. 손바닥에 유리 조각이 박혀 있다. 아픈 줄도 몰랐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } },
    { l:'② 바닥에 조금 부어 무엇이 오는지 지켜본다.', k:'luck', dc:21,
      ok:`병을 기울여 바닥에 조금 부었다. 물러서서 지켜봤다.<br><br>어둠 속에서 무엇이 다가오다 멈춘다. 약 냄새 앞에서. 그리고 물러간다. 둥글게 쓸린 자국은 그것이 병을 비켜 다닌 자국이다.<br>남은 것을 병째 챙겼다. 이 약은 무엇을 쫓는 약이다. 반 병이면 몇 번은 쓴다.`,
      ng:`붓자 어둠 속의 것이 다가온다. 빠르게. 반가운 것처럼.<br><br>바닥의 약을 핥는다. 그리고 병을 든 이쪽 손을 본다. 더 있다는 걸 안다.<br>병을 멀리 던지고 반대로 뛰었다. 등 뒤에서 유리 깨지는 소리. 그리고 핥는 소리.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'쉬는 자리 — 약 냄새가 나는 사람',
  x:`쉬는 자리에서 일행 하나 곁을 지나다 멈췄다. 냄새가 난다.<br><br>
    약 냄새다. 독하고 맑은 냄새. 죽은 것을 오래 두려고 쓰는 약 냄새.<br>
    그 사람은 그런 약을 만진 적이 없다. 본인은 냄새를 모른다.<br><br>
    살갗이 조금 반들거린다. 손톱 밑이 하얗다.`,
  o:[
    { l:'① 쓴 즙을 달여 몸을 씻기고 마시게 한다.', k:'heal', dc:22, wake:1,
      ok:`쓴 풀을 진하게 달였다. 반은 천에 적셔 몸을 닦고 반은 마시게 했다.<br><br>그 사람이 토한다. 맑은 것을. 독한 냄새가 같이 나온다. 몸이 그것을 밀어낸다.<br>닦은 살갗에서 반들거림이 걷힌다. 손톱 밑에 분홍빛이 돈다. 다시 썩을 수 있는 몸이 됐다. 그게 산 몸이다.<br><br>독을 쓰는 약이 아니라 독을 거두는 약. 같은 쓴 풀로 반대의 일을 했다. 손이 쓴맛의 양쪽을 다 쥐었다.`,
      ng:`달인 즙을 마시게 했는데 그 사람이 삼키지 못한다. 목이 굳었다.<br><br>몸만 닦았다. 냄새는 반만 빠졌다. 그 사람이 춥다고 한다. 살이 이미 차다.<br>밤새 불 곁에 앉혔다. 아침에 조금 데워졌다. 냄새는 그대로다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 무엇을 먹었는지, 누가 주었는지 캐묻는다.', k:'bond', dc:21,
      ok:`곁에 앉아 낮게 물었다. 오늘 무엇을 먹고 마셨는지. 누가 준 것은 없는지.<br><br>한참 생각하다 말한다. 아까 계단에서 누가 물을 줬다고. 친절한 사람이었다고. 일행인 줄 알았다고.<br>그 물을 마신 건 그 사람뿐이다. 남은 수통 물을 다 쏟았다. 쏟은 물에서 같은 냄새가 났다.`,
      ng:`묻자 그 사람이 웃는다. 왜 그렇게 쳐다보냐고.<br><br>대답 대신 냄새가 진해진다. 웃을 때마다. 입안에서 나는 냄새다.<br>더 묻지 못했다. 그 사람이 잠들 때까지 지켜봤다. 자는 숨이 너무 고요했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-24 } }
  ] },

{ at:'A', t:'어둠 — 단내 나는 연기',
  x:`어둠 저편에서 연기가 흘러온다. 달다.<br><br>
    약을 다루는 사람은 단 연기를 제일 경계한다. 단 것은 쓴 것을 감추려고 넣는다.<br>
    일행 둘이 벌써 하품을 한다. 눈이 풀린다.<br><br>
    연기가 오는 쪽에 불빛이 하나 있다. 누가 약을 태운다.`,
  o:[
    { l:'① 젖은 천에 숯가루를 묻혀 코와 입을 막게 한다.', k:'fix', dc:22,
      ok:`천을 찢어 물에 적시고 숯가루를 비볐다. 다섯 몫. 코와 입에 동였다.<br><br>숯은 냄새를 먹는다. 단내가 천에서 걸린다. 하품하던 둘의 눈에 초점이 돌아온다.<br>연기를 등지고 걸었다. 천이 점점 무거워진다. 숯이 먹은 만큼.`,
      ng:`천을 동이는데 하나가 이미 주저앉았다. 잠들었다.<br><br>그 사람을 업고 걸었다. 숯천 너머로 단내가 비집고 들어온다. 이쪽 무릎도 풀린다.<br>겨우 빠져나왔다. 업힌 사람은 반나절 동안 깨지 않았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 깨우는 풀을 씹어 하품하는 둘의 혀 밑에 넣는다.', k:'heal', dc:21,
      ok:`매운 뿌리 한 토막을 씹어 둘로 나눴다. 하품하는 두 사람 혀 밑에 하나씩 넣었다.<br><br>둘이 눈을 번쩍 뜬다. 혀가 맵다고 운다. 매운 건 잠을 이긴다.<br>셋이서 연기를 피해 갔다. 이쪽 혀도 한참 얼얼했다.`,
      ng:`씹어 넣었는데 하나가 뱉는다. 잠결에.<br><br>그 사람이 연기 쪽으로 걸어간다. 끌어당겼다. 그 사람 팔이 축 늘어진다. 몸이 무겁다.<br>반쯤 끌고 반쯤 업었다. 이쪽 어깨가 빠질 것 같았다.`,
      win:{ exp:16, dream:2, mind:8 }, lose:{ hp:-22, spirit:-22 } },
    { l:'③ 불빛 쪽으로 가서 태우는 약을 끈다.', k:'break', dc:23,
      doom:{ title:'단내', what:'연기 속에서 잠든 채 불가로 끌려갑니다', dc:18, sec:50,
        text:`숨을 참고 불빛 쪽으로 갔다. 화로가 있다. 약초 다발이 탄다. 끄려고 손을 뻗었다.<br><br>참던 숨이 터졌다. 단 연기를 한가득 들이켰다. 무릎이 접힌다. 화로 곁에 주저앉는다. 따뜻하다.<br>화로 맞은편에 누가 앉아 있다. 약초를 한 다발 더 얹는다. 이쪽 팔을 잡아 화로 곁으로 끌어당긴다. 더 가까이. 졸리지요.<br><br>연기가 눈꺼풀을 덮는다. 맞은편 손이 이쪽 머리를 무릎에 눕힌다.`,
        dieText:`어둠 저편 화로는 계속 탔다.<br><br>연기가 흘러온다. 달다. 처방이 조금 바뀌었다. 쓴맛을 감추는 솜씨가 늘었다.<br>약을 다루던 손이 다발을 엮어 얹는다.` },
      ok:`숨을 참고 낮게 기어갔다. 연기는 위로 간다. 바닥 공기는 덜 달다.<br><br>화로가 있다. 약초 다발이 탄다. 흙을 한 줌 끼얹었다. 치익. 연기가 꺾인다.<br>화로 곁에 남은 다발 하나를 챙겼다. 태우기 전 것이다. 쓰는 양을 알면 잠 못 드는 사람에게 쓸 수 있다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' } }
  ] },

{ at:'A', t:'계단 — 기억에 없는 바늘 자국',
  x:`쉬는 자리에서 일행 하나가 소매를 걷었다. 팔꿈치 안쪽에 점이 있다.<br><br>
    바늘 자국이다. 셋. 가지런히. 그 사람은 기억이 없다.<br>
    약을 다루는 사람은 바늘 자국을 보면 무엇을 넣었는지 짐작한다. 자국 주위가 푸르면 넣은 것이고 붉으면 뺀 것이다.<br><br>
    셋 다 푸르다. 무엇을 넣었다.`,
  o:[
    { l:'① 자국을 눌러 피 한 방울을 짜 냄새를 맡는다.', k:'sense', dc:23, wake:1,
      ok:`자국 하나를 눌러 피를 한 방울 짰다. 손등에 받아 맡았다. 쇠 냄새. 그다음에 아주 옅게 꽃 냄새. 잠을 주는 꽃이다.<br><br>밤마다 누가 넣었다. 깊이 재우려고. 깊이 잠든 사람은 불러도 대답을 못 한다. 대신 따라간다.<br>그 사람에게 매운 뿌리를 씹게 했다. 오늘 밤은 이쪽이 그 사람 곁에서 잔다. 팔을 덮고.<br><br>피 한 방울에서 밤의 일을 읽었다. 약이 남긴 자취를 몸에서 맡는 법. 코가 몸속까지 닿았다.`,
      ng:`짜려고 누르는데 피가 안 나온다. 자국에서 맑은 것이 나온다.<br><br>맡아도 아무 냄새가 없다. 냄새 없는 것은 모른다. 모르는 것이 그 사람 몸에 있다.<br>그날 밤 그 사람 팔을 이쪽 팔에 묶고 잤다. 새벽에 팔이 저렸다. 자국이 넷이 되어 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 해독하는 차를 진하게 달여 먹인다.', k:'heal', dc:22,
      ok:`해독 풀을 진하게 달였다. 쓴 것을 삼키게 했다. 한 사발.<br><br>그 사람이 땀을 흘린다. 팔꿈치 자국 주위의 푸른빛이 옅어진다. 몸이 넣은 것을 밀어낸다.<br>밤에 그 사람은 얕게 잤다. 누가 부르자 깨서 대답 대신 이쪽을 깨웠다.`,
      ng:`달인 차가 너무 진하다. 그 사람이 토한다. 반도 못 넘겼다.<br><br>자국은 그대로 푸르다. 그 사람이 졸리다고 한다. 오후인데.<br>밤새 그 사람 곁을 지켰다. 한 번, 그 사람이 잠결에 대답했다. 네.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'마지막 쉼 — 셋 몫의 약',
  x:`내려가기 전, 마지막 쉼이다. 약을 나눴다.<br><br>
    셋 몫이다. 다섯이 다 다쳤다. 이 안에서 다친 데는 바깥에서 다친 데보다 늦게 닫힌다.<br>
    약이 모자랄 때 하는 일은 둘이다. 누구를 빼거나, 약을 늘리거나.<br><br>
    빼는 건 약을 다루는 사람이 할 일이 아니다.`,
  o:[
    { l:'① 부스러기까지 맞춰 넣어 다섯 몫으로 늘린다.', k:'heal', dc:22, wake:1,
      ok:`셋 몫의 약을 쪼개고 주머니 바닥 부스러기를 하나하나 맞춰 넣었다. 약한 것은 다른 것으로 받치고, 쓴 것은 단 것으로 눌렀다.<br><br>다섯 봉지가 됐다. 셋 몫일 때보다 약하지 않다. 서로가 서로를 거드니까.<br>다들 먹었다. 아침에 다섯 다 걸었다.<br><br>모자란 것을 맞춰서 넉넉하게. 있는 약을 주던 손이 없는 약을 지었다. 손 안에서 셈이 하나 더 늘었다.`,
      ng:`맞추다가 맞지 않는 둘이 만났다. 색이 탁해진다.<br><br>반을 버렸다. 셋 몫이 둘 몫이 됐다. 다섯이 둘 몫을 나눴다.<br>아무도 낫지 않았다. 다들 조금씩 덜 아팠다. 그것도 약이다. 모자란 약이다.`,
      win:{ exp:24, dream:3, hp:8 }, lose:{ hp:-22, mind:-18 } },
    { l:'② 다친 순서대로 셋에게 준다.', k:'bond', dc:21,
      ok:`많이 다친 사람부터 셋에게 주었다. 못 받은 둘에게는 아래에서 구하면 먼저 주겠다고 했다.<br><br>못 받은 둘 중 하나가 이쪽이다. 그건 말하지 않았다.<br>밤에 이쪽 상처가 욱신댔다. 받은 셋은 잘 잤다. 그거면 됐다.`,
      ng:`순서를 정하는데 말이 엇갈린다. 다들 자기가 더 아프다고 한다. 정말 그럴지도 모른다.<br><br>결국 똑같이 나눴다. 다섯이 다 조금씩 모자란다.<br>모자란 약은 낫게 하지 않는다. 덜 아프게만 한다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A1', t:'분장실 — 분첩의 가루',
  x:`분장실 거울 앞 의자마다 분첩이 놓여 있다. 하얀 가루가 묻었다.<br><br>
    일행 하나가 분첩을 만지고 나서 볼이 당긴다고 한다. 입꼬리 쪽으로.<br>
    약을 다루는 사람은 가루를 보면 손이 먼저 간다. 무엇을 갈아 만든 가루인지 알고 싶어서.<br><br>
    거울 속 넷째 의자의 것이 분첩을 두드린다. 탁, 탁. 그 박자에 일행 볼이 한 번씩 당긴다.`,
  o:[
    { l:'① 가루를 손등에 개어 무엇인지 가린다.', k:'gaze', dc:22, wake:1,
      ok:`분첩 귀퉁이를 손톱으로 긁어 손등에 놓고 침으로 갰다. 하얗게 번진다. 쌀가루가 아니다. 뼛가루다. 곱게 간.<br><br>그리고 아주 옅게 쓴 냄새. 근육을 굳히는 풀이다. 웃는 얼굴로 굳히려고 넣었다. 뼛가루는 그 풀을 살갗에 붙잡아 두는 몫이다.<br>무엇이 굳히는지 알면 무엇이 푸는지도 안다. 신 즙에 쓴 풀을 풀어 일행 볼을 닦았다. 입꼬리가 내려온다.<br><br>가루 하나에서 처방 전체를 거꾸로 읽어 냈다. 독을 보면 약이 보인다. 그 길이 손에 붙었다.`,
      ng:`개는데 손등 살갗이 당긴다. 가루 묻은 자리가 굳는다.<br><br>손가락이 펴진 채로 굳었다. 손을 쥘 수가 없다. 거울 속에서 분첩 두드리는 박자가 빨라진다.<br>물로 한참 씻었다. 손가락이 한 마디씩 돌아왔다. 새끼손가락은 저녁까지 굽지 않았다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 분첩을 전부 뒤집어 엎어 둔다.', k:'fix', dc:21,
      ok:`분첩을 하나씩 뒤집어 놓았다. 가루 묻은 쪽을 아래로.<br><br>거울 속 넷째 의자의 것이 분첩을 들어 올리다 멈춘다. 가루가 다 바닥에 묻었다. 두드릴 것이 없다.<br>일행 볼이 더 당기지 않는다. 거울 속 그것이 고개를 갸웃한다. 화장을 마치지 못한 얼굴로.`,
      ng:`뒤집는데 분첩이 이쪽 손바닥에 붙는다. 가루 면이.<br><br>떼자 손바닥에 하얀 자국이 남았다. 거울 속에서 그 자국에 맞춰 분첩을 두드린다.<br>손바닥이 웃는 모양으로 오므라든다. 저녁까지 펴지 못했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-16 } }
  ] },

{ at:'A1', t:'매점 — 빛나는 음료 냉장고',
  x:`매점 셔터 밑으로 음료 냉장고 불빛이 샌다. 전기가 끊긴 건물이다.<br><br>
    병들이 줄지어 섰다. 노란 것, 분홍 것. 병마다 방글이 얼굴 상표. 마시면 웃음이 나요.<br>
    약을 다루는 사람은 상표 문구를 믿지 않는다. 대신 병 바닥을 본다.<br><br>
    병 바닥마다 앙금이 앉았다. 하얗게.`,
  o:[
    { l:'① 병 바닥 앙금을 흔들지 않고 들여다본다.', k:'gaze', dc:22,
      ok:`병을 기울이지 않고 냉장고 불빛에 바닥을 비췄다. 앙금이 실처럼 엉겼다. 솜이다. 아주 고운 솜.<br><br>마시면 목에서부터 안쪽이 솜으로 채워질 것이다. 웃음이 나는 건 얼굴이 아니라 안쪽이다.<br>음료는 두고 냉장고 맨 아래 칸 생수만 꺼냈다. 바닥이 맑다. 봉인도 그대로다.`,
      ng:`들여다보는데 앙금이 저절로 일어난다. 병 안에서 소용돌이친다. 이쪽 얼굴 쪽으로 모인다.<br><br>냉장고 문이 저절로 열린다. 찬 바람과 함께 단내가 쏟아진다. 들이마셨다. 목 안이 간지럽다.<br>한참 기침을 했다. 기침 끝에 하얀 실이 한 가닥 나왔다.`,
      win:{ exp:18, dream:2, item:'맑은 물' }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 매점 계산대 밑의 상비 상자를 연다.', k:'luck', dc:21,
      ok:`계산대 밑에 낡은 상자가 있다. 매점 아주머니 상비 상자다. 반창고, 소화제, 꿀 사탕 봉지.<br><br>꿀 사탕은 공장 봉지다. 날짜가 문 닫기 전이다. 봉지를 눌러 보니 바스락거린다. 진짜다.<br>챙겼다. 상자 뚜껑 안쪽에 연필 글씨. 냉장고 거 애들 주지 마.`,
      ng:`상자를 여는데 안에 아무것도 없다. 바닥에 손바닥만 한 구멍이 있다.<br><br>구멍에서 차가운 손가락이 하나 나와 이쪽 손등을 두드린다. 똑똑. 계산하라고.<br>손을 뺐다. 손등에 웃는 해 도장이 찍혀 있다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 효를 알려고 노란 병을 한 모금만 마셔 본다.', k:'sense', dc:23,
      doom:{ title:'마시면 웃음이 나요', what:'웃는 얼굴로 굳어 숨이 멎어 갑니다', dc:18, sec:45,
        text:`노란 병을 따서 한 모금 머금었다. 모르는 약은 제 몸으로 안다. 늘 그렇게 해 왔다.<br><br>달다. 그리고 넘어가 버렸다. 혀가 아니라 목이 먼저 삼켰다. 목 안이 부드럽게 막힌다. 솜이 부푼다.<br>입꼬리가 올라간다. 저절로. 볼이 당긴다. 숨이 웃음 사이로만 새어 나온다. 하, 하.<br><br>매점 셔터 너머에서 녹음된 박수가 터진다. 숨이 점점 짧아진다.`,
        dieText:`매점 음료 냉장고에 병이 하나 늘었다.<br><br>노란 병이다. 상표의 방글이 얼굴이 조금 다르다. 웃는 입이 길다. 눈이 안 웃는다.<br>병 바닥 앙금이 다른 병보다 많다.` },
      ok:`병을 따서 입술에만 댔다. 혀에 닿기 전에 단내가 목을 먼저 간지른다. 삼키라고.<br><br>뱉었다. 입을 헹궜다. 혀끝이 저절로 웃는 모양으로 말린다. 물로 몇 번이나 헹궜다.<br>모르는 약은 혀끝까지만. 오늘은 입술까지만. 병은 뚜껑을 닫아 냉장고 맨 뒤에 넣었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'탕비실 — 이름 붙은 시럽',
  x:`탕비실 찬장에 약병이 줄지어 있다. 기침 시럽이다.<br><br>
    병마다 이름표. 피디. 감독. 언니. 인형 1. 인형 2. 인형탈 쓰는 사람은 목이 쉰다. 탈 안이 덥고 숨이 차서.<br>
    인형 1 병만 거의 비었다. 나머지는 가득하다.<br><br>
    약을 다루는 사람은 남의 약병 줄어든 양을 보면 그 사람 사정을 안다.`,
  o:[
    { l:'① 봉인과 날짜를 보고 멀쩡한 병만 고른다.', k:'luck', dc:22,
      ok:`병마다 뚜껑 봉인을 봤다. 언니 병은 봉인이 그대로다. 날짜는 문 닫기 한 달 전. 꿀 시럽이다.<br><br>그 병만 챙겼다. 목 아픈 사람에게 한 숟갈이면 된다. 꿀은 오래 간다.<br>인형 1 병은 건드리지 않았다. 다 마신 병에는 이유가 있다. 그 이유가 아직 탈 안에 있을지도 모른다.`,
      ng:`고르다가 인형 1 병을 쳤다. 병이 넘어진다. 남은 시럽이 쏟아진다.<br><br>시럽이 아니다. 검고 끈적하다. 솜 냄새가 난다. 쏟아진 자리에서 쉰 목소리가 난다. 콜록. 콜록.<br>뒷걸음질 쳤다. 기침 소리가 탕비실 문밖까지 따라 나왔다.`,
      win:{ exp:18, dream:2, item:'꿀 한 줌' }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 인형 1 병의 남은 방울 냄새를 맡는다.', k:'sense', dc:21,
      ok:`병 입구에 코를 댔다. 꿀, 생강. 그 밑에 진한 쓴맛. 아픈 걸 모르게 하는 약이다. 많이.<br><br>인형 1은 아팠다. 많이. 매일. 그래도 탈을 썼다. 아픈 걸 모르게 하고.<br>병을 제자리에 놓았다. 찬장 문 안쪽에 연필 자국이 있다. 세로 줄 몇십 개. 하루에 하나씩. 그어진 줄은 문 닫는 날에 끝났다.`,
      ng:`맡는데 병 안에서 숨이 나온다. 쉰 숨이다. 이쪽 얼굴에.<br><br>목이 따갑다. 소리가 안 나온다. 일행을 부르려는데 쉰 소리만 난다. 탈 안에서 내는 소리처럼.<br>저녁까지 목소리가 돌아오지 않았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'놀이 세트 — 허수아비 발치의 뿌리',
  x:`텃밭 동산 고랑에 약초가 섞여 자란다. 쑥, 질경이, 이름 모를 잎.<br><br>
    허수아비 발치에 굵은 뿌리가 흙 위로 드러나 있다. 약을 다루는 사람이 오래 찾던 뿌리다. 진하게 달이면 열을 꺾는다.<br>
    뿌리 둘레 흙이 사람 크기로 부풀어 있다.<br><br>
    고랑 팻말 하나가 뿌리 옆에 꽂혀 있다. 내가 심었어요.`,
  o:[
    { l:'① 흙을 헤쳐 굵은 뿌리를 통째로 캔다.', k:'break', dc:23,
      doom:{ title:'내가 심었어요', what:'뿌리를 쥔 채 흙 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`흙을 헤쳤다. 뿌리가 굵다. 두 손으로 쥐고 당겼다. 안 나온다. 더 세게 당겼다.<br><br>뿌리가 마주 당긴다. 흙 속에서 무언가 뿌리를 쥐고 있다. 손이다. 작은 손. 흙이 묻었다.<br>당기는 힘이 이쪽보다 세다. 팔이 흙에 묻힌다. 어깨, 얼굴. 흙이 따뜻하다. 잘 가꾼 흙이다.<br><br>위에서 허수아비 방글이가 팔을 벌린 채 내려다본다. 물을 준다. 천천히.`,
        dieText:`텃밭 동산 고랑에 팻말이 하나 늘었다.<br><br>내가 심었어요. 이름은 크레용 글씨다. 철자가 조금 어른 것이다.<br>그 고랑에 굵은 뿌리가 자란다. 약이 되는 뿌리다.` },
      ok:`흙을 헤치기 전에 뿌리 끝을 칼로 잘랐다. 드러난 데만. 땅속 쪽은 두었다.<br><br>잘린 자리에서 흙이 한 번 꿈틀한다. 그리고 가라앉는다. 땅속 것은 뿌리 끝을 놓았다.<br>한 뼘 반 토막이다. 달이면 몇 번은 쓴다. 팻말에 고맙다고 적어 두었다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' } },
    { l:'② 고랑 가장자리의 쑥과 질경이만 뜯는다.', k:'sense', dc:21,
      ok:`가장자리 고랑으로 갔다. 흙이 평평한 데다. 잎을 비벼 맡았다. 쑥은 쑥 냄새, 질경이는 풀 냄새. 섞인 냄새가 없다.<br><br>두 줌 뜯었다. 질경이는 상처에, 쑥은 연기에.<br>허수아비가 이쪽을 안 본다. 가장자리는 아무도 안 심은 데다.`,
      ng:`뜯는데 잎에서 쇠 냄새가 난다. 피 냄새다.<br><br>뿌리째 뽑혀 나온 질경이 뿌리에 머리카락이 감겼다. 가늘고 길다.<br>던졌다. 손바닥에 흙이 붙어 안 떨어진다. 그 흙이 따뜻하다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A1', t:'로비 — 손등의 도장',
  x:`일행 손등에 도장이 찍혀 있다. 웃는 해 모양. 재입장 도장이다.<br><br>
    언제 찍혔는지 아무도 모른다. 문지르면 진해진다. 씻으면 번진다. 번진 자리마다 작은 해가 하나씩 더 생긴다.<br>
    약을 다루는 사람은 잉크도 약처럼 본다. 무엇에 녹고 무엇에 엉기는지.<br><br>
    도장 찍힌 사람은 이 건물에 다시 온다고 한다.`,
  o:[
    { l:'① 쓴 즙과 소금과 재를 비율 맞춰 개어 지운다.', k:'heal', dc:22, wake:1,
      ok:`쓴 풀즙 둘, 소금 하나, 불에 탄 재 반. 손바닥에서 개었다. 잿빛 반죽이다.<br><br>도장 위에 바르고 기다렸다. 반죽이 잉크를 빨아들인다. 해 모양이 반죽 쪽으로 옮겨 간다. 반죽을 걷어 불에 던졌다. 치익. 작은 웃음소리가 났다.<br>손등이 맑다. 다섯 사람 손등을 다 그렇게 했다.<br><br>상처도 독도 아닌 것을 약으로 지웠다. 몸에 붙은 것을 떼는 약. 손이 처음 지어 본 약이다.`,
      ng:`개는데 비율이 틀렸다. 소금이 많다.<br><br>바르자 도장이 지워지는 게 아니라 손등 살갗이 일어난다. 해 모양으로. 쓰라리다.<br>도장은 그대로다. 그 위에 상처만 늘었다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 잉크 냄새를 맡아 무엇으로 만들었는지 본다.', k:'sense', dc:21,
      ok:`손등에 코를 댔다. 기름 냄새. 그리고 솜 냄새. 인형탈 안감 냄새다.<br><br>탈 안에서 배어 나온 것으로 찍었다. 탈을 쓴 것들과 같은 냄새를 묻힌 것이다. 찾아오기 쉽게.<br>장갑을 끼고 손등을 덮었다. 냄새가 덜 나면 덜 찾는다.`,
      ng:`맡는데 도장이 따뜻해진다. 숨 쉬는 쪽으로.<br><br>도장이 이쪽 코끝에 와 닿는다. 코끝에도 하나 찍혔다. 일행이 웃음을 참는다.<br>웃음을 참는 일행 손등의 도장들이 대신 웃는다. 박음질한 입처럼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A2', t:'양호실 — 약장의 위 칸과 아래 칸',
  x:`양호실 약장이 벽 위쪽에 있다. 위 칸은 물 밖, 아래 칸은 물속이다.<br><br>
    위 칸에 병이 줄지어 섰다. 이름표가 다 붙어 있다. 보건 선생님 글씨다. 반듯하다.<br>
    아래 칸 병들은 물속에서 둥둥 떠 있다. 병 하나가 이쪽 쪽으로 천천히 떠 온다. 이름표가 보인다. 해독.<br><br>
    셋째 침대 커튼 안에서 체온계 흔드는 소리. 탁, 탁.`,
  o:[
    { l:'① 위 칸 이름표를 다 읽고 쓸 것만 고른다.', k:'gaze', dc:22, wake:1,
      ok:`위 칸 이름표를 하나씩 읽었다. 소독, 해열, 지혈, 진통. 그리고 맨 끝에 손글씨로. 물 먹은 아이에게.<br><br>그 병에 든 것은 말린 약초다. 숨길을 여는 것과 몸을 데우는 것. 둘을 섞어 놓았다. 섞는 비율이 정확하다. 물 들어오던 날 지었다.<br>그 병을 챙겼다. 이름표 밑에 오늘 날짜와 이쪽 이름을 적었다. 가져간다고.<br><br>남이 남긴 처방을 읽어 손에 옮겼다. 처방 하나가 남의 손에서 이쪽 손으로 건너왔다. 손이 그만큼 넓어졌다.`,
      ng:`읽다가 이름표 글씨가 번진다. 물이 올라온다. 위 칸까지.<br><br>병들이 젖는다. 이름표가 다 지워졌다. 무엇이 무엇인지 모른다.<br>커튼 안 체온계 소리가 멈춘다. 손 하나가 커튼 틈으로 나와 이쪽 이마를 짚는다. 차다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 위 칸 구석의 꿀 단지만 챙긴다.', k:'luck', dc:21,
      ok:`꿀 단지가 구석에 있다. 뚜껑에 쪽지. 한 숟갈만. 욕심내면 혼나요.<br><br>한 숟갈씩만 떠서 일행 목에 넘겼다. 차가운 물을 먹은 목들이 풀린다. 나머지는 챙겼다.<br>커튼 안 체온계 소리가 잠깐 멈췄다 다시 난다. 괜찮다는 박자다.`,
      ng:`단지를 꺼내는데 뚜껑이 열려 있다. 꿀이 물을 먹어 묽다.<br><br>그래도 한 숟갈 떴다. 숟가락에 꿀이 아니라 물이 담긴다. 비린 물이다.<br>커튼 안에서 혼내는 소리가 난다. 욕심냈다고. 이쪽 이마가 오래 시렸다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 떠 오는 해독 병을 물속에서 건진다.', k:'heal', dc:23,
      doom:{ title:'아래 칸', what:'약병을 쥔 채 약장 아래 물속으로 끌려갑니다', dc:18, sec:50,
        text:`손을 물에 넣어 떠 오는 병을 쥐었다. 해독. 약을 다루는 사람에게 이보다 귀한 병은 없다.<br><br>병이 안 딸려 온다. 병 밑을 무엇이 쥐고 있다. 작은 손이다. 손 하나가 아니다. 아래 칸에서 손들이 병을 서로 쥐고 있다. 다 아팠던 손이다.<br>당긴다. 이쪽 팔이 아래 칸 안으로. 어깨가 물에 잠긴다. 약장 아래 칸은 깊다. 약장보다 깊다.<br><br>물속에서 누가 묻는다. 그 약, 저 주는 거예요?`,
        dieText:`양호실 약장 아래 칸에서 병들이 떠 있다.<br><br>해독 병이 이쪽으로 천천히 떠 온다. 이름표 글씨가 다르다. 반듯하지 않다. 약을 다루던 손 글씨다.<br>병 밑을 쥔 손이 하나 늘었다. 어른 손이다.` },
      ok:`손을 넣기 전에 위 칸 소독약을 물에 한 방울 떨어뜨렸다. 아래 물이 소독약 냄새를 싫어한다. 손들이 물러난다.<br><br>그 틈에 병만 집어 올렸다. 해독. 마개가 단단하다. 안에 가루가 말라 있다.<br>병을 꺼내자 아래 칸에서 손 하나가 물 위로 올라와 손바닥을 편다. 달라는 손이다. 꿀 사탕 하나를 쥐여 주었다. 손이 오므려 내려갔다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' } }
  ] },

{ at:'A2', t:'과학실 — 이름표가 녹은 약품장',
  x:`과학실 약품장이 물에 반쯤 잠겼다. 유리문이 금 갔다.<br><br>
    병들의 이름표가 다 녹았다. 종이가 물에 풀려 병 주위를 떠다닌다.<br>
    약을 다루는 사람은 이름표 없이도 안다. 색과 냄새와 무게로.<br><br>
    수조 쪽에서 물을 튀기는 소리가 난다. 실험용 수조가 아니다. 그보다 크다.`,
  o:[
    { l:'① 병마다 마개만 들어 냄새로 가린다.', k:'sense', dc:22,
      ok:`병을 하나씩 들어 마개 틈으로 맡았다. 식초. 알코올. 석회. 이건 쓴다. 이건 버린다.<br><br>알코올은 상처를 씻고 불을 붙인다. 석회는 물을 맑게 한다. 둘을 챙겼다. 나머지는 마개를 꼭 닫아 제자리에.<br>마지막 병은 아무 냄새가 없다. 그 병은 건드리지 않았다. 병 안이 조금 흔들렸다.`,
      ng:`맡다가 하나를 잘못 열었다. 코를 찌르는 김이 확 오른다.<br><br>눈물이 쏟아진다. 앞이 안 보인다. 수조 쪽 물 튀기는 소리가 가까워진다. 물 젓는 소리.<br>더듬어서 문을 찾았다. 눈은 저녁까지 따가웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 맨 위 칸의 하얀 결정 병을 꺼낸다.', k:'luck', dc:21,
      ok:`맨 위 칸 병은 물 밖이다. 하얀 결정이 가득하다. 혀끝에 대 보니 짜다. 소금이다. 실험용이라 깨끗하다.<br><br>소금은 약이고 음식이고 선이다. 병째 챙겼다.<br>꺼내고 보니 병 밑에 시험지가 깔려 있다. 이름과 점수. 빵점. 그 옆에 선생님 글씨. 다음엔 잘하자.`,
      ng:`꺼내는데 병이 미끄러진다. 물에 빠졌다. 결정이 물에 녹는다.<br><br>짠물이 퍼진다. 수조 쪽 소리가 멈춘다. 그리고 물속에서 무언가 이쪽으로 헤엄쳐 온다. 짠 냄새를 따라.<br>책상 위로 기어 올라가 지나가기를 기다렸다. 책상 다리를 무언가 한 바퀴 돌고 갔다.`,
      win:{ exp:16, dream:2, item:'소금 덩이' }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'세면장 — 약 맛이 나는 물',
  x:`세면장 수도꼭지에서 물이 졸졸 나온다. 학교가 다 잠겼는데.<br><br>
    일행이 손을 씻다가 한 모금 마셨다. 쓰다고 한다. 약 맛이다.<br>
    약을 다루는 사람이 받아 맡았다. 잠을 주는 풀 냄새. 아이들이 밤에 떠들지 말라고 물에 탄 것이다. 아주 옅게. 매일.<br><br>
    몇 해를 마셨다면 옅은 것도 짙어진다.`,
  o:[
    { l:'① 물을 오래 달여 약 기운을 날린다.', k:'heal', dc:22, wake:1,
      ok:`수통에 받은 물을 솥에 올려 오래 끓였다. 김이 오를 때 쓴 냄새가 같이 오른다. 날아간다.<br><br>반이 줄 때까지 끓였다. 맛을 봤다. 쓴맛이 없다. 맹물이다. 일행에게 마시게 했다. 마신 사람의 눈이 맑다.<br>먼저 마셨던 일행에게는 매운 뿌리를 씹게 했다. 오늘 밤만 버티면 된다.<br><br>독을 덜어 내는 것으로 물을 약으로 바꿨다. 넣는 것만 약이 아니다. 빼는 것도 약이다. 손이 그걸 알았다.`,
      ng:`끓이는데 김에서 냄새가 짙어진다. 날아가는 게 아니라 모인다.<br><br>세면장 안이 쓴 김으로 찬다. 다들 하품을 한다. 솥을 엎었다.<br>물은 버렸다. 하품은 그날 내내 멈추지 않았다.`,
      win:{ exp:22, dream:3, item:'맑은 물' }, lose:{ hp:-22, mind:-20 } },
    { l:'② 일행 모두에게 이 물을 마시지 말라 막는다.', k:'steady', dc:21,
      ok:`수도꼭지 앞을 막아섰다. 목말라도 이 물은 안 된다고 했다. 다들 불평한다.<br><br>먼저 마신 일행이 졸기 시작한다. 그걸 보고 다들 말이 없어졌다.<br>마른 수통을 흔들며 걸었다. 목이 탄다. 그래도 깨어 있다.`,
      ng:`막는데 일행 하나가 목이 너무 마르다며 마신다. 또 하나.<br><br>둘이 졸기 시작한다. 셋째도. 졸린 사람 셋을 끌고 걸었다.<br>세면장 거울 속에서 아이들이 수도꼭지 앞에 줄 서 있다. 차례로 마신다. 착하게.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-26 } }
  ] },

{ at:'A2', t:'보일러실 — 마르는 약초',
  x:`보일러실에 아직 불이 있다. 보일러 아궁이가 벌겋다. 물은 무릎 아래다.<br><br>
    보일러 위 배관에 약초 다발이 걸려 있다. 말리느라 걸어 둔 것이다. 보건 선생님 것인지 조리실 것인지.<br>
    다발 몇은 바짝 말랐고 몇은 아직 젖었다. 배관 밑 물에도 다발 하나가 떠 있다.<br><br>
    약을 다루는 사람에게 마른 약초는 금이다. 젖은 약초는 시간이다.`,
  o:[
    { l:'① 젖은 다발을 아궁이 열에 맞춰 마저 말린다.', k:'fix', dc:22,
      ok:`젖은 다발을 아궁이에서 한 뼘 반 거리에 걸었다. 너무 가까우면 약 기운이 날아가고 멀면 곰팡이가 슨다.<br><br>자리를 옮겨 가며 지켰다. 다발에서 김이 오르다 그친다. 바스락거린다. 말랐다.<br>세 다발을 챙겼다. 아궁이 불이 이쪽을 보는 것처럼 일렁였다. 오래 혼자 타던 불이다.`,
      ng:`말리는데 아궁이에서 불길이 확 내뻗는다. 다발에 붙었다.<br><br>약초가 탄다. 탄 약 냄새가 퍼진다. 쓴 연기가 눈을 찌른다.<br>불을 털다 손등이 데었다. 다 탔다.`,
      win:{ exp:18, dream:2, item:'약초 뭉치' }, lose:{ hp:-26, mind:-16 } },
    { l:'② 마른 다발로 보일러 불에 해열 약을 달인다.', k:'heal', dc:21,
      ok:`마른 다발 하나를 풀어 열을 꺾는 잎만 골랐다. 수통 물에 넣어 아궁이 앞에서 달였다.<br><br>물에 젖어 열이 오른 일행이 둘이다. 한 사발씩 먹였다. 땀이 난다. 열이 꺾인다.<br>남은 잎은 묶어 챙겼다. 아궁이 불이 조금 잦아들었다. 일을 하나 덜었다는 듯.`,
      ng:`달이는데 불이 너무 세다. 끓어 넘친다.<br><br>쓴 물이 아궁이에 쏟아진다. 치이익. 김이 보일러실을 채운다. 앞이 안 보인다.<br>김 속에서 누가 아궁이 문을 닫는 소리가 났다. 이쪽 일행은 아니다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 배관 밑 물에 뜬 다발을 손을 뻗어 건진다.', k:'luck', dc:23,
      doom:{ title:'배관 밑', what:'배관 틈 물살에 팔째 빨려 내려갑니다', dc:18, sec:45,
        text:`배관 밑으로 손을 뻗었다. 다발이 손끝에 닿는다. 쥐었다.<br><br>다발이 물살에 끌려간다. 배관 틈 쪽으로. 놓으면 되는데 손이 다발을 놓지 않는다. 약을 다루는 손이다.<br>틈의 물살이 손목을 감는다. 팔이 틈 안으로 빨려 들어간다. 어깨가 배관에 걸린다. 그 밑에서 당기는 힘이 계속된다. 물이 얼굴로 올라온다.<br><br>틈 안쪽에서 누가 다발을 받아 간다. 이쪽 손째로.`,
        dieText:`보일러실 배관에 약초 다발이 걸려 있다.<br><br>하나가 늘었다. 매듭이 다르다. 약을 오래 다룬 손의 매듭이다.<br>배관 밑 물에는 다발 하나가 떠 있다. 손을 뻗기 좋은 거리에.` },
      ok:`손 대신 부지깽이를 뻗었다. 끝으로 다발 끈을 걸어 당겼다.<br><br>다발이 끌려가려다 부지깽이에 걸려 딸려 온다. 배관 틈 물살이 부지깽이를 대신 빨아들였다. 놓았다. 부지깽이가 틈으로 사라졌다.<br>다발은 젖었지만 귀한 뿌리가 섞였다. 아궁이 앞에 걸어 말렸다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' } }
  ] },

{ at:'A2', t:'도서관 — 눌린 잎의 도감',
  x:`도서관 높은 서가 꼭대기는 물 밖이다. 거기 두꺼운 책이 하나 마른 채 꽂혀 있다.<br><br>
    약초 도감이다. 펼치면 잎이 눌려 붙어 있다. 아이들이 채집해 붙인 것이다. 잎마다 이름과 효능. 크레용 글씨.<br>
    몇 장은 효능이 틀렸다. 몇 장은 잎이 이 학교 화단에서만 나는 것이다.<br><br>
    마지막 장에 잎이 비었다. 이름만 적혀 있다. 숨 쉬는 풀.`,
  o:[
    { l:'① 눌린 잎과 적힌 효능을 맞춰 바로잡는다.', k:'gaze', dc:22, wake:1,
      ok:`한 장씩 넘기며 잎을 봤다. 맞는 것엔 둥글게, 틀린 것엔 고쳐 적었다. 독이 있는 것엔 해골을 그렸다. 약을 다루는 사람끼리 쓰는 표시다.<br><br>이 학교 화단 잎은 처음 본다. 잎맥이 물결 모양이다. 효능 칸에 적혀 있다. 물에 빠진 사람 숨이 돌아온다. 크레용이지만 정확한 관찰이다. 잎 하나를 떼어 챙겼다.<br><br>아이가 적은 효능을 이쪽 손이 받아 적었다. 모르던 풀 하나가 손 안에 들어왔다. 아는 약의 지도가 한 칸 넓어졌다.`,
      ng:`고쳐 적는데 크레용 글씨가 저절로 바뀐다. 이쪽이 고친 자리 옆에.<br><br>틀렸어요. 맞아요. 아이 글씨다. 고친 걸 다시 고친다.<br>도감을 덮었다. 덮은 책 안에서 크레용 긁는 소리가 한참 났다.`,
      win:{ exp:22, dream:3, item:'약초 뭉치' }, lose:{ mind:-18, spirit:-24 } },
    { l:'② 마지막 장의 대출 카드를 본다.', k:'bond', dc:21,
      ok:`뒤표지 안쪽에 대출 카드가 꽂혀 있다. 빌린 이름이 한 줄. 반납 칸이 비었다.<br><br>그 이름 옆에 작은 글씨. 숨 쉬는 풀 찾으러 감. 화단.<br>카드 반납 칸에 오늘 날짜를 적고 도감을 서가에 꽂았다. 대신 반납해 주었다. 서가 밑 물이 한 번 동그랗게 퍼졌다.`,
      ng:`카드를 꺼내는데 젖어 있다. 책은 말랐는데 카드만.<br><br>이름이 번져 이쪽 손가락에 묻는다. 지워지지 않는다. 대출 연체. 빨간 도장이 손가락에 찍혀 있다.<br>서가 밑에서 누가 반납하라고 속삭였다. 무엇을 반납하라는지 모르겠다.`,
      win:{ exp:16, dream:2, spirit:8 }, lose:{ hp:-22, spirit:-26 } }
  ] }

]);


// ------------------------------------------
// 의원 (physician) · 내공
// ------------------------------------------
kJob('physician', 'A', [

{ at:'A', t:'쉬는 자리 — 손목 하나에 맥 둘',
  x:`불 앞에 둘러앉자 손을 내밀었다. 손목을 달라는 뜻이다. 하루 끝에 맥을 짚는다.<br><br>
    넷은 지친 맥이다. 하나는 다르다. 한 손목에서 맥이 둘 뛴다.<br>
    하나는 그 사람 박자다. 하나는 반 박자 늦다. 늦은 쪽이 조금씩 앞으로 당겨 온다.<br><br>
    둘이 겹치는 날, 어느 쪽이 그 사람인지 아무도 모를 것이다.`,
  o:[
    { l:'① 손끝 셋을 따로 써서 두 박자를 가른다.', k:'sense', dc:22, wake:1,
      ok:`검지, 중지, 약지. 세 손가락을 손목에 얹고 하나씩 힘을 바꿨다. 가볍게 짚으면 겉 박자, 깊게 짚으면 속 박자.<br><br>늦은 박자는 겉에서만 뛴다. 살갗 바로 밑. 속까지 내려가지 못했다. 아직 들어오는 중이다.<br>겉 박자가 뛰는 혈을 엄지로 눌러 막았다. 늦은 박자가 갈 곳을 잃고 흩어진다. 맥이 하나가 됐다.<br><br>세 손가락이 각자 다른 깊이를 들었다. 맥 하나를 셋으로 나눠 듣는 손. 손끝이 한 겹 더 깊어졌다.`,
      ng:`가르려는데 두 박자가 손끝에서 섞인다. 어느 게 어느 건지 모르겠다.<br><br>그 사람이 손을 빼 간다. 왜 그렇게 오래 잡냐고 웃는다. 웃는 박자가 반 박자 늦다.<br>밤새 그 사람 쪽을 보지 않으려 애썼다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 내공을 흘려 넣어 낯선 박자를 밀어낸다.', k:'heal', dc:23, cost:{ qi:25 },
      ok:`손목 혈에 엄지를 대고 내공을 가늘게 흘려 넣었다. 기혈을 따라 한 바퀴.<br><br>낯선 박자가 내공에 밀린다. 팔꿈치, 어깨, 목덜미. 갈 데까지 밀려 정수리 혈에서 빠져나간다. 그 사람이 몸을 떤다. 한기가 머리 위로 빠졌다.<br>맥이 하나다. 그 사람 박자다.`,
      ng:`밀자 낯선 박자가 거꾸로 온다. 내공을 타고 이쪽 손목으로.<br><br>손을 떼기 전에 이쪽 맥이 한 번 반 박자 늦게 뛰었다. 들어왔다 나갔다.<br>내공은 다 쓰고 그 사람 맥은 여전히 둘이다.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 벽 속에서 뛰는 맥',
  x:`복도를 걷다 손이 벽에 닿았다. 멈췄다.<br><br>
    벽이 뛴다. 둥, 둥. 맥이다. 사람 것보다 느리고 깊다.<br>
    맥을 오래 짚어 온 손은 무엇이든 맥이 있으면 손이 먼저 그 박자를 센다. 세면 알게 된다.<br><br>
    복도 끝까지 벽이 뛴다. 걸음마다 맥이 조금씩 빨라진다. 이쪽 걸음에 맞춰.`,
  o:[
    { l:'① 벽에서 손을 떼고 한가운데로 걷는다.', k:'steady', dc:22,
      ok:`손을 떼고 복도 한가운데로 걸었다. 벽에 아무도 닿지 않게 일행을 붙들었다.<br><br>벽의 맥이 따라오지 못한다. 닿지 않은 것은 셀 수 없다. 저쪽도 이쪽을 못 센다.<br>복도 끝에서 돌아보니 벽 한 군데가 볼록하다. 맥이 거기 몰려 있다. 기다리는 모양이다.`,
      ng:`가운데로 걷는데 바닥도 뛴다. 둥, 둥. 발바닥으로 맥이 올라온다.<br><br>안 셀 수가 없다. 세지 않으려 해도 손끝이 셋다. 셋을 때마다 바닥 박자가 이쪽 박자에 붙는다.<br>복도를 다 빠져나오자 가슴이 두근거렸다. 바닥 박자로.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 벽의 맥이 몰리는 혈을 찾아 침을 놓는다.', k:'fix', dc:23, cost:{ qi:30 },
      ok:`손바닥을 벽에서 한 치 띄우고 따라갔다. 맥이 제일 센 데가 있다. 사람으로 치면 명치다.<br><br>가장 긴 침에 내공을 실어 벽 틈으로 찔렀다. 끝이 무엇에 닿는다. 물컹하다.<br>둥. 둥. 그리고 멈춘다. 복도 전체가 한숨을 쉰다. 벽이 잠들었다. 침은 뽑지 않고 두었다.`,
      ng:`침을 찔렀는데 빗나갔다. 벽이 움찔한다.<br><br>맥이 빨라진다. 화가 난 맥이다. 벽 표면이 출렁인다. 손바닥 자국들이 안쪽에서 떠올라 줄지어 이쪽으로 온다.<br>침을 버리고 뛰었다. 복도 끝 문을 닫자 문짝이 한참 두근거렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, mind:-18 } },
    { l:'③ 손바닥을 대고 끝까지 맥을 센다.', k:'sense', dc:23,
      doom:{ title:'벽의 맥', what:'맥에 맞춰진 손이 벽 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`두 손바닥을 벽에 댔다. 셌다. 열, 스물. 느리고 깊다.<br><br>세다 보니 이쪽 맥이 벽에 맞춰진다. 둥, 둥. 가슴이 벽 박자로 뛴다. 손바닥이 벽에 붙는다. 벽이 따뜻하다. 살 같다.<br>벽이 손바닥을 받아들인다. 손목, 팔꿈치. 맥이 하나가 된 것끼리는 떨어질 이유가 없다. 벽 안쪽에서 무엇이 당긴다.<br><br>짚는 쪽과 짚히는 쪽이 바뀌었다. 벽이 이쪽 맥을 센다.`,
        dieText:`복도 벽이 뛴다. 둥, 둥.<br><br>박자가 둘이다. 하나는 느리고 깊고, 하나는 사람 박자다. 겹쳐 뛴다.<br>다음에 지나간 사람이 벽에 손을 댔다. 맥 짚는 법을 모르는 사람인데도 박자가 들렸다.` },
      ok:`손바닥을 대기 직전에 손끝만 댔다. 하나만. 열까지만 세고 뗐다.<br><br>열 박자면 충분하다. 맥이 늘어지는 데가 복도 왼쪽, 빨라지는 데가 오른쪽이다. 빨라지는 쪽에 무엇이 깨어 있다.<br>일행을 왼쪽으로 붙여 걸었다. 오른쪽 벽이 한 번 크게 쿵 했다. 놓쳤다는 듯.`,
      win:{ exp:22, dream:3, mind:8 } }
  ] },

{ at:'A', t:'계단 — 멎었다 다시 뛰는 맥',
  x:`계단참에서 쉬는데 일행 하나가 갑자기 조용해진다.<br><br>
    손목을 잡았다. 맥이 없다. 하나, 둘, 셋. 일곱까지 세었을 때 다시 뛴다. 아무 일 없다는 듯.<br>
    그 사람은 모른다. 잠깐 졸았다고 한다.<br><br>
    다시 멎는다. 이번엔 아홉. 무엇이 그 사람 박자를 빌려 갔다가 돌려준다. 돌려줄 때마다 조금 늦게.`,
  o:[
    { l:'① 가슴 혈에 침을 놓아 박자를 붙들어 둔다.', k:'heal', dc:23, wake:1,
      ok:`옷을 헤치고 가슴 한가운데와 젖꼭지 사이 혈을 짚었다. 가는 침을 놓았다. 한 푼, 두 푼. 혈에 닿는 순간 그 사람이 크게 숨을 들이켠다.<br><br>침을 꽂아 두었다. 맥이 멎으려 할 때마다 침 끝이 떨린다. 떨림이 박자를 붙든다. 빌려 갈 박자가 침에 꽂혀 있다.<br>반나절 동안 한 번도 멎지 않았다.<br><br>침이 짚는 손가락을 대신해 붙들었다. 놓는 것이 아니라 박는 것. 손끝이 다른 쓰임을 배웠다.`,
      ng:`침을 놓는데 그 사람 맥이 그 순간 멎는다. 혈이 비었다.<br><br>빈 혈에 들어간 침은 아무것도 붙들지 못한다. 열하나를 세었을 때 다시 뛴다.<br>침을 뽑았다. 침 끝이 차다. 아주 차다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 내공을 실어 등 혈을 쳐 박자를 되찾게 한다.', k:'heal', dc:22, cost:{ qi:25 },
      ok:`맥이 멎는 순간 그 사람 등 뒤 날개뼈 사이 혈을 손바닥으로 쳤다. 내공을 실어서.<br><br>쿵. 그 사람 몸이 앞으로 꺾인다. 맥이 뛴다. 제 박자로. 늦지 않게.<br>빌려 가던 쪽이 손을 놓친 것이다. 계단 위 어둠에서 무언가 빈손을 쥐었다 펴는 소리가 났다.`,
      ng:`쳤는데 박자가 제 박자가 아니다. 친 이쪽 박자로 뛴다.<br><br>그 사람 맥이 이쪽 맥과 똑같다. 이쪽이 숨을 쉬면 그 사람도 쉰다. 떨어질 수가 없다.<br>반나절 동안 그 사람 곁에서 걸었다. 둘 다 숨이 찼다.`,
      win:{ exp:20, dream:2, hp:8 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'어둠 — 등으로 드는 한기',
  x:`어둠을 지나는데 일행이 하나씩 몸을 떤다. 춥다고 한다.<br><br>
    등을 만져 보니 날개뼈 사이가 얼음 같다. 다섯 다 같은 자리다.<br>
    맥을 짚는 사람은 혈이 문이라는 걸 안다. 열면 들어오고 닫으면 못 들어온다.<br><br>
    그 혈이 열려 있다. 무엇이 다섯 등에 손을 대고 지나간다.`,
  o:[
    { l:'① 다섯 등의 혈을 차례로 눌러 닫는다.', k:'heal', dc:22,
      ok:`한 사람씩 등을 돌려 세우고 날개뼈 사이 혈을 엄지로 눌렀다. 깊이, 오래. 문을 닫듯이.<br><br>누를 때마다 그 사람 숨이 길어진다. 한기가 갈 데를 잃는다. 다섯을 다 닫았다.<br>어둠 속에서 손바닥이 등 대신 허공을 쓰다듬는 소리가 났다. 문이 닫혀서 머뭇거린다.`,
      ng:`누르는데 혈이 안 닫힌다. 한기가 엄지를 밀어낸다.<br><br>엄지가 얼었다. 셋째 사람 등에서 손을 떼지 못했다. 그 사람 등과 이쪽 엄지가 같이 얼었다.<br>입김을 불어 겨우 뗐다. 엄지 끝이 하얗게 죽었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 내공을 크게 돌려 다섯의 몸을 한꺼번에 데운다.', k:'steady', dc:23, cost:{ qi:30 }, wake:1,
      ok:`다섯을 둥글게 앉히고 손을 잇게 했다. 내공을 한쪽 손으로 흘려 넣었다. 한 바퀴 돌아 반대 손으로 돌아온다.<br><br>돌 때마다 따뜻해진다. 등의 한기가 밀려난다. 다섯이 한 몸처럼 데워진다. 한 몸은 문이 하나다. 그 하나를 이쪽이 지킨다.<br><br>다섯의 기혈을 하나로 이어 한 사람처럼 지켰다. 한 몸을 보던 손이 여럿을 한 몸으로 보기 시작했다.`,
      ng:`돌리다가 한 사람에서 막힌다. 그 사람 등의 한기가 내공을 얼린다.<br><br>내공이 되돌아와 이쪽 가슴을 친다. 기침이 터진다. 손이 풀렸다. 다섯이 다시 따로따로 떤다.<br>내공은 비고 등은 여전히 차다.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A', t:'쉬는 자리 — 바뀌는 얼굴빛',
  x:`쉬는 자리에서 다섯의 얼굴을 봤다. 얼굴빛을 보면 속을 안다.<br><br>
    넷은 지친 빛이다. 하나는 빛이 바뀐다. 등잔불이 흔들릴 때마다. 누렇다가 하얗다가 푸르다.<br>
    사람 얼굴빛은 그렇게 빨리 안 바뀐다. 속이 바뀌는 게 아니라 속에 든 것이 바뀌는 것이다.<br><br>
    그 사람은 잠들었다. 숨이 고르다. 너무 고르다.`,
  o:[
    { l:'① 바뀌는 빛의 순서로 무엇이 드나드는지 읽는다.', k:'gaze', dc:22, wake:1,
      ok:`등잔을 고정하고 오래 봤다. 누런빛은 그 사람 것이다. 지친 간 빛이다. 하얀빛과 푸른빛은 들어온 것이다.<br><br>푸른빛이 오를 때 입술이 아주 조금 움직인다. 이름을 부른다. 다른 사람 이름이다. 하얀빛일 때는 손가락이 바닥을 긁는다.<br>둘 다 손끝에서 나간다. 열 손가락 끝을 침으로 땄다. 검은 피가 한 방울씩. 얼굴빛이 누런 데서 멈춘다.<br><br>얼굴빛 하나를 여러 겹으로 읽었다. 보는 눈이 얼굴 밑을 지나 속에 든 것까지 닿았다.`,
      ng:`보는데 빛이 이쪽 얼굴에도 옮겨 온다. 일행이 이쪽을 보며 놀란다. 얼굴이 푸르다고.<br><br>등잔을 껐다. 어둠 속에서 다섯이 숨죽였다. 잠든 그 사람만 고르게 숨을 쉰다.<br>아침에 얼굴빛은 돌아왔다. 둘 다. 손끝이 아직 시리다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 깨워서 혀를 내밀어 보라 한다.', k:'heal', dc:21,
      ok:`흔들어 깨웠다. 혀를 보자고 했다. 그 사람이 졸린 눈으로 내민다.<br><br>혀가 둘로 덮였다. 앞은 하얗고 뒤는 검다. 앞은 지친 것이고 뒤는 먹은 것이다. 이 안의 물을 먹었다.<br>쓴 차를 먹여 토하게 했다. 검은 것이 나온다. 얼굴빛이 하나로 고정된다. 지친 빛 하나로.`,
      ng:`깨우는데 안 깬다. 혀를 보려고 입을 벌렸다.<br><br>입안이 비었다. 혀가 목 안쪽으로 말려 있다. 숨은 고르다. 혀 없이도.<br>입을 닫고 등을 두드렸다. 한참 뒤 그 사람이 기침하며 깼다. 혀가 제자리에 있다. 아무것도 기억 못 한다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 잠든 그 사람 손목을 잡고 맥을 짚는다.', k:'sense', dc:23,
      doom:{ title:'잠든 손목', what:'잠든 것에게 손목을 잡혀 어둠 쪽으로 끌려갑니다', dc:18, sec:50,
        text:`잠든 손목을 들어 맥을 짚었다. 고르다. 너무 고르다. 사람 맥은 숨 따라 조금씩 흔들린다. 이건 안 흔들린다.<br><br>손목이 뒤집힌다. 그 손이 이쪽 손목을 짚는다. 맥 짚는 자리를. 정확하다. 손끝 셋을 따로 쓴다. 이쪽이 쓰는 법이다.<br>눈을 감은 채 그것이 일어선다. 이쪽 손목을 쥔 채 어둠 쪽으로 걷는다. 끌려간다. 손목을 짚힌 채로는 힘이 안 들어간다. 맥이 그것 박자로 뛴다.<br><br>일행이 깬다. 자고 있는 사람은 아직 그 자리에 누워 있다.`,
        dieText:`아침에 일행이 하나 모자랐다. 맥을 짚던 쪽이다.<br><br>잠들었던 사람은 멀쩡히 깼다. 얼굴빛이 좋다. 손목에 손가락 자국 셋이 남아 있다.<br>그 사람이 일행 맥을 짚어 주겠다고 했다. 손끝 셋을 따로 쓴다. 배운 적이 없는데.` },
      ok:`손목을 잡기 전에 손등 위로 손바닥을 한 치 띄워 기만 읽었다. 고르다. 사람 고름이 아니다.<br><br>손목은 잡지 않았다. 대신 그 사람 발목에 끈을 묶어 이쪽 발목에 이었다. 밤새 끈이 두 번 당겨졌다. 두 번 다 이쪽이 당겨 돌려놓았다.<br>아침에 그 사람 맥이 흔들린다. 사람답게.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A', t:'통로 — 침이 꽂힌 채 선 사람',
  x:`통로 벽에 사람이 기대 서 있다. 움직이지 않는다.<br><br>
    온몸에 침이 꽂혀 있다. 수십 대. 정수리, 목덜미, 손등, 발등.<br>
    맥을 짚어 온 사람은 침 자리를 보면 놓은 사람 생각을 안다. 이건 살리려고 놓은 침이 아니다. 붙들어 두려고 놓은 침이다.<br><br>
    그 사람 눈이 이쪽을 따라 움직인다. 눈만.`,
  o:[
    { l:'① 침 자리를 읽어 무엇을 붙들었는지 본다.', k:'gaze', dc:22,
      ok:`하나씩 따라 읽었다. 정수리는 정신, 목덜미는 숨, 손발은 걸음. 걸음을 막고 숨을 늦추고 정신을 붙들었다.<br><br>놓은 사람은 이 사람을 살리려고 한 게 아니다. 이 사람 안의 것을 못 나가게 한 것이다. 침이 뽑히면 안의 것이 나온다.<br>한 대도 건드리지 않았다. 그 사람 눈이 고맙다는 듯 한 번 감겼다 떠졌다.`,
      ng:`읽다가 눈이 마주쳤다. 그 사람 눈 속에 다른 눈이 있다. 그쪽이 이쪽을 본다.<br><br>침들이 아주 조금씩 빠져나온다. 안에서 밀려서. 정수리 침이 반 푼 올라왔다.<br>뒷걸음질 쳤다. 침이 다시 들어갔다. 이쪽이 멀어지자.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 쓸 만한 침 몇 대만 손발 끝에서 뽑아 챙긴다.', k:'fix', dc:21,
      ok:`붙드는 침은 정수리와 목덜미다. 손발 끝의 것은 거든 것뿐이다. 발등에서 둘, 손등에서 하나를 뽑았다.<br><br>좋은 침이다. 끝이 머리카락보다 가늘다. 오래 쓴 침이다. 놓은 사람은 솜씨가 좋았다.<br>그 사람 눈이 이쪽 손을 따라온다. 손가락 끝이 아주 조금 움직였다. 침 셋만큼.`,
      ng:`손등 침을 뽑는데 그 사람 손이 이쪽 손을 잡는다. 순식간에.<br><br>힘이 세다. 침 한 대가 빠지면 그만큼 풀린다. 손을 비틀어 빠져나오다 손목을 삐었다.<br>뽑은 침을 도로 꽂았다. 손이 다시 굳었다. 이쪽 손목은 저녁까지 부었다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A', t:'쉬는 자리 — 숨을 세는 소리',
  x:`밤에 깨어 있었다. 맥을 짚는 사람은 잠결에도 숨소리를 듣는다.<br><br>
    다섯의 숨 사이로 작은 소리가 난다. 세는 소리다. 하나, 둘. 이쪽 일행 숨을 하나씩 센다.<br>
    숫자가 줄어든다. 백, 아흔아홉. 숨 한 번에 하나씩.<br><br>
    영이 되면 무엇이 되는지는 모른다. 알고 싶지 않다.`,
  o:[
    { l:'① 내공으로 다섯의 숨을 길게 늘려 셈을 흐린다.', k:'hide', dc:23, cost:{ qi:25 },
      ok:`잠든 다섯 손목에 차례로 손을 얹고 내공을 가늘게 넣었다. 숨을 늘리는 혈에.<br><br>다섯의 숨이 길어진다. 들이쉬는 데 셋, 내쉬는 데 넷. 세는 쪽이 머뭇거린다. 한 번 쉬는 숨인지 두 번인지.<br>세는 소리가 틀린다. 아흔다섯, 아흔여섯. 거꾸로 간다. 새벽에 셈이 그쳤다. 처음부터 다시 세야 할 것이다.`,
      ng:`늘리는데 한 사람 숨이 너무 길어진다. 들이쉬고 내쉬지 않는다.<br><br>세는 소리가 그 사람 숨에서 멈춘다. 영. 급히 가슴을 눌렀다. 숨이 터져 나온다.<br>세는 소리가 다시 시작된다. 이번엔 그 사람만 센다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 다섯을 깨워 숨을 마구 섞어 쉬게 한다.', k:'bond', dc:22,
      ok:`하나씩 흔들어 깨웠다. 이유는 말하지 않았다. 아무렇게나 숨을 쉬라고만 했다. 짧게, 길게, 멈췄다가 몰아서.<br><br>다섯이 어리둥절하며 따른다. 숨이 제멋대로 엉킨다. 세는 소리가 버벅댄다. 하나, 하나, 넷.<br>새벽까지 그렇게 쉬었다. 다들 지쳤다. 그래도 셈은 끝나지 않았다. 끝나지 않은 셈은 영이 오지 않는다.`,
      ng:`깨우는데 하나가 안 깬다. 숨이 고르다. 세는 소리와 박자가 맞는다.<br><br>그 사람 숨만 하나씩 줄어든다. 넷이 그 사람을 흔들었다. 귀에 대고 소리쳤다. 새벽에야 깼다.<br>숨이 얕다. 남은 숫자가 몇인지는 이쪽만 들었다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'어둠 — 맥을 따라오는 것',
  x:`어둠 속에서 무언가가 따라온다. 소리는 없다.<br><br>
    다만 이쪽 맥이 빨라질 때마다 그것이 가까워진다. 맥이 느려지면 멈춘다.<br>
    맥을 짚는 사람이라 안다. 저것은 맥을 듣는다. 다섯 사람 심장 소리를 따라온다.<br><br>
    다들 무서워서 맥이 빨라진다. 그것이 빨리 온다.`,
  o:[
    { l:'① 다섯의 손목 혈을 눌러 맥을 늦춘다.', k:'heal', dc:22, wake:1,
      ok:`걸으면서 한 사람씩 손목 안쪽 혈을 눌렀다. 맥을 가라앉히는 혈이다. 무서운 마음까지는 못 누른다. 맥만 누른다.<br><br>다섯의 맥이 느려진다. 둥, 둥. 잠든 사람 박자로. 따라오던 것이 멈춘다. 고개를 갸웃하는 기척.<br>천천히 걸어서 빠져나왔다. 이쪽 맥은 이쪽이 직접 눌렀다. 제일 어려웠다.<br><br>여럿의 맥을 걸으면서 한꺼번에 다스렸다. 손이 고치는 자리에서 지키는 자리로 한 걸음 옮겼다.`,
      ng:`누르는데 누를 때마다 그 사람이 놀라 맥이 더 빨라진다.<br><br>그것이 다가온다. 바로 등 뒤까지. 차가운 것이 목덜미 혈을 짚는다. 이쪽이 짚는 자리를.<br>다들 뛰었다. 뛰는 맥을 따라 그것이 한참 따라왔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 내공을 끌어올려 제 맥을 크게 울려 미끼가 된다.', k:'steady', dc:23, cost:{ qi:30 },
      ok:`일행을 먼저 보냈다. 이쪽은 뒤에 서서 내공을 끌어올렸다. 맥이 크게 운다. 북처럼.<br><br>그것이 이쪽으로 온다. 다른 다섯 맥은 묻힌다. 일행이 멀어진다.<br>그것이 코앞에 왔을 때 내공을 한꺼번에 거뒀다. 맥이 뚝 가라앉는다. 그것이 허공을 짚는다. 그 틈에 걸어 나왔다.`,
      ng:`울리는데 너무 크게 울렸다. 내공이 가슴 안에서 터진다.<br><br>맥이 엉킨다. 크게 뛰다 멎다 뛴다. 그것이 반긴다. 목덜미에 찬 숨이 닿는다.<br>일행이 돌아와 끌고 갔다. 가슴이 사흘 동안 쑤셨다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'③ 그것의 맥을 거꾸로 짚어 자리를 찾아낸다.', k:'sense', dc:24,
      doom:{ title:'마주 짚은 맥', what:'제 맥이 그것의 박자에 맞춰 멎어 갑니다', dc:19, sec:45,
        text:`멈춰 서서 눈을 감았다. 저것이 맥을 듣는다면 저것에게도 맥이 있다. 짚으면 된다.<br><br>찾았다. 아주 느리다. 한 번 뛰고 한참 쉬고 한 번. 셌다. 셀수록 이쪽 맥이 그 박자에 맞춰진다. 한 번 뛰고 한참 쉬고.<br>쉬는 사이가 길어진다. 저쪽은 그렇게 산다. 이쪽은 그렇게 못 산다. 가슴이 조용해진다.<br><br>눈을 뜨니 그것이 바로 앞에 있다. 같은 박자로 뛰는 것끼리 마주 보고 있다.`,
        dieText:`어둠 속에서 무언가가 다음 일행을 따라간다.<br><br>맥이 빨라질 때마다 가까워진다. 둘이다. 하나는 느리고, 하나는 한때 사람 박자였다.<br>둘 다 맥을 듣는다. 하나는 맥 짚는 법을 안다.` },
      ok:`눈을 감고 찾았다. 아주 느린 맥. 다섯 박자만 세고 손을 털었다. 그 이상 세면 맞춰진다.<br><br>다섯 박자면 자리는 안다. 왼쪽 위다. 천장에 붙어 있다.<br>일행을 오른쪽 벽에 붙여 걸었다. 천장에서 무언가 방향을 놓쳐 허둥대는 기척이 났다.`,
      win:{ exp:22, dream:3, mind:8 } }
  ] },

{ at:'A', t:'계단 — 쥐가 난 다리',
  x:`계단을 오르다 일행 하나가 주저앉았다. 종아리에 쥐가 났다.<br><br>
    근육이 뭉쳐 돌처럼 단단하다. 그런데 뭉친 모양이 이상하다. 손가락 모양으로 오목하다. 무엇이 종아리를 쥐고 있는 것처럼.<br>
    맥을 짚는 사람은 근육 밑의 혈을 안다. 쥐는 혈이 막혀서 난다.<br><br>
    쥐가 허벅지로 올라간다. 손가락 자국째로.`,
  o:[
    { l:'① 무릎 뒤와 발목 혈을 짚어 쥔 것을 푼다.', k:'heal', dc:22, wake:1,
      ok:`무릎 뒤 오금 혈과 발목 안쪽 혈. 두 곳을 동시에 눌렀다. 위아래로 길을 열었다.<br><br>뭉친 근육이 풀린다. 손가락 모양의 오목함이 하나씩 펴진다. 마지막 하나가 펴질 때 종아리에서 찬 기운이 쑥 빠져나간다. 발바닥 쪽으로.<br>그 사람이 다리를 편다. 쥐가 풀렸다. 쥔 것도 풀었다.<br><br>근육 밑의 혈을 짚어 근육 밖의 것을 떼어 냈다. 혈이 몸 바깥과도 이어져 있다는 걸 손이 알았다.`,
      ng:`짚는데 손가락 모양이 이쪽 손을 피해 옮겨 간다. 혈이 열리기 전에.<br><br>허벅지까지 갔다. 그 사람이 비명을 지른다. 쥐가 허리로 오른다.<br>다 같이 다리를 붙잡고 주물렀다. 한참 뒤에 풀렸다. 허리에 손자국 다섯이 퍼렇게 남았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 쑥으로 종아리에 뜸을 떠 데운다.', k:'fix', dc:21,
      ok:`쑥을 비벼 작은 뭉치를 빚었다. 종아리 혈 셋에 얹고 불을 붙였다.<br><br>연기가 오른다. 뭉친 근육이 열에 풀린다. 손가락 모양이 뜨거워서 움찔한다. 놓는다.<br>그 사람이 일어섰다. 다리가 따뜻하다고 한다. 뜸 자국은 남았다. 손가락 자국은 안 남았다.`,
      ng:`뜸을 얹는데 연기가 이쪽으로만 기운다. 눈이 맵다.<br><br>불이 피부까지 탔다. 그 사람이 펄쩍 뛴다. 쥐는 그대로다. 뜸 자국만 늘었다.<br>그 사람을 업고 계단을 올랐다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-22 } }
  ] },

{ at:'A', t:'마지막 쉼 — 제 맥을 짚는다',
  x:`내려가기 전, 마지막 쉼이다. 다들 잠들었다.<br><br>
    남의 맥은 매일 짚는다. 제 맥은 잘 안 짚는다. 오늘은 짚었다.<br>
    빠르다. 고르지 않다. 두려움이 맥에 다 나와 있다.<br><br>
    두려운 맥으로는 남의 맥을 정확히 못 짚는다. 아래층은 더 나쁠 것이다.`,
  o:[
    { l:'① 제 손등 혈에 침을 놓아 박자를 세운다.', k:'heal', dc:22, wake:1,
      ok:`가는 침을 꺼내 제 손등 혈에 놓았다. 천천히. 한 푼, 두 푼. 혈에 닿는 순간 팔 전체가 찌릿하다.<br><br>맥이 한 번 크게 뛰고 가라앉는다. 고르게. 두려움은 그대로 있다. 다만 맥에서 빠졌다. 두려움은 머리에 두고 맥은 손에 둔다.<br><br>제 몸에 놓은 침으로 제 박자를 다스렸다. 남을 고치는 손이 먼저 저를 고쳤다. 손끝이 더 침착해졌다.`,
      ng:`놓다가 손이 떨렸다. 혈을 비켜 들어갔다.<br><br>피가 맺힌다. 맥이 더 빨라진다. 떨리는 손으로는 저를 못 고친다.<br>침을 뽑고 손을 무릎에 놓았다. 밤새 맥 소리가 귀에서 울렸다.`,
      win:{ exp:24, dream:3, mind:8 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 앉아서 내공을 크게 한 바퀴 돌린다.', k:'steady', dc:21, cost:{ qi:25 },
      ok:`등을 세우고 앉아 내공을 한 바퀴 크게 돌렸다. 단전에서 등줄기로, 정수리로, 앞으로 내려와 다시 단전으로.<br><br>돌 때마다 맥이 내공 박자에 실린다. 세 바퀴째에 맥이 고르다.<br>몸이 데워진다. 손끝도 데워진다. 데워진 손끝은 맥을 잘 듣는다.`,
      ng:`돌리는데 등줄기 어디선가 막힌다. 차가운 매듭이 있다. 오늘 짚은 것 중 무엇이 남았다.<br><br>내공이 매듭에 걸려 되돌아온다. 가슴이 철렁한다.<br>밤새 그 매듭을 더듬었다. 풀리지 않았다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'분장실 — 웃는 쪽으로 굳는 볼',
  x:`분장실 거울 앞에서 일행 하나가 볼을 감싼다.<br><br>
    얼굴 근육이 당긴다고 한다. 입꼬리 쪽으로. 거울 속 넷째 의자의 것이 분첩을 두드릴 때마다 한 번씩.<br>
    맥을 짚는 사람은 얼굴에도 혈이 있다는 걸 안다. 볼에, 입가에, 턱 밑에. 근육은 혈을 따라 움직인다.<br><br>
    입꼬리가 귀 쪽으로 올라간다. 웃는 얼굴이 아니다. 웃음으로 묶이는 얼굴이다.`,
  o:[
    { l:'① 입가와 턱 밑 혈에 침을 놓아 근육을 푼다.', k:'heal', dc:22, wake:1,
      ok:`가는 침 넷을 꺼냈다. 입꼬리 옆 둘, 턱 밑 둘. 얕게, 아주 얕게. 얼굴 혈은 깊이 놓지 않는다.<br><br>침이 들어가자 당기던 근육이 떤다. 거울 속 분첩 박자와 침 끝 떨림이 맞서다 침이 이긴다. 입꼬리가 내려온다. 한 푼씩.<br>침을 뽑자 그 사람이 얼굴을 찡그린다. 아프다고. 찡그릴 수 있는 얼굴로 돌아왔다.<br><br>남의 박자에 묶인 근육을 침으로 제 박자에 돌려놓았다. 침 끝이 근육의 결을 듣는다. 손이 그만큼 섬세해졌다.`,
      ng:`놓는데 근육이 침을 문다. 침이 안 빠진다.<br><br>거울 속 분첩 박자에 맞춰 침이 떤다. 침이 오히려 입꼬리를 끌어올린다.<br>억지로 뽑았다. 피가 맺힌다. 그 사람 입꼬리가 한쪽만 올라간 채 굳었다. 저녁에야 풀렸다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 귀 뒤 혈을 눌러 분첩 소리를 막는다.', k:'fix', dc:21,
      ok:`그 사람 귀 뒤 움푹한 혈을 양손 엄지로 눌렀다. 듣는 길을 닫는 혈이다.<br><br>그 사람이 고개를 갸웃한다. 분첩 소리가 안 들린다고. 소리를 못 들으니 박자를 못 탄다. 볼이 풀린다.<br>그 사람을 분장실 밖으로 데리고 나갈 때까지 엄지를 떼지 않았다. 엄지가 저렸다.`,
      ng:`누르는데 소리가 혈을 비켜 들어온다. 뼈를 타고.<br><br>그 사람이 이쪽 손을 뿌리친다. 시끄럽다고. 분첩 소리가 귀 안에서 울린다고.<br>억지로 끌고 나왔다. 그 사람 귀에서 한참 하얀 가루가 나왔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'의상실 — 탈 쓴 사람의 손목',
  x:`의상실 의자에 인형탈을 쓴 것이 앉아 있다. 삐뚤이 탈이다. 긴 파란 목이 꺾여 있다.<br><br>
    탈 소매 밖으로 손목이 나와 있다. 사람 손목이다. 맨살이다. 맥이 보인다. 아주 약하게 뛴다.<br>
    탈 안에 사람이 있다. 오래 있었다. 맥이 그렇게 말한다.<br><br>
    맥을 짚는 사람은 약한 맥을 보면 손이 먼저 간다.`,
  o:[
    { l:'① 손목을 잡고 맥을 제대로 짚는다.', k:'heal', dc:23,
      doom:{ title:'삐뚤이 탈', what:'짚은 손목에 잡혀 탈 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`손목을 잡았다. 따뜻하다. 맥이 뛴다. 손끝 셋으로 짚었다. 약하다. 그런데 손끝 밑에서 맥이 이쪽 손끝을 짚는다.<br><br>탈 소매 안에서 손이 하나 더 나온다. 이쪽 팔꿈치를 쥔다. 또 하나가 어깨를. 탈 안이 넓다. 사람 하나 들어갈 크기가 아니다.<br>파란 목이 숙여진다. 머리 구멍이 이쪽 얼굴 위로 온다. 안쪽이 따뜻하다. 숨 냄새가 난다. 여럿의 숨 냄새다.<br><br>끌려 들어간다. 소매 안으로. 맥이 짚히는 채로.`,
        dieText:`의상실 의자에 삐뚤이 탈이 앉아 있다.<br><br>소매 밖으로 손목이 나와 있다. 둘이다. 하나는 약하게 뛰고 하나는 아직 세게 뛴다.<br>센 쪽 손끝이 아주 조금 움직인다. 맥을 짚는 모양으로.` },
      ok:`잡기 전에 손목을 응시했다. 맥이 뛰는 자리가 손목 바깥쪽이다. 사람 맥은 안쪽에서 뛴다.<br><br>안쪽이 아니다. 뒤집힌 손목이다. 탈 안에서 거꾸로 내민 팔이다. 안에 있는 것이 사람인지, 사람 모양으로 사람 팔을 내민 것인지 모른다.<br>짚지 않았다. 손목 옆에 맑은 물 한 컵을 놓고 나왔다. 아픈 거라면 마실 것이다.`,
      win:{ exp:22, dream:3, mind:8 } },
    { l:'② 탈 머리 쪽 숨소리만 듣는다.', k:'sense', dc:22,
      ok:`탈 머리 가까이 귀를 댔다. 숨이 들린다. 하나가 아니다. 셋이다. 셋이 번갈아 쉰다.<br><br>탈 하나에 셋. 손목의 맥은 그중 하나의 것이다. 제일 약한 하나. 나머지 둘이 그 하나를 쥐고 있다.<br>할 수 있는 게 없다. 할 수 있는 게 없다는 걸 알고 물러섰다. 그것도 맥을 짚는 사람이 해야 하는 일이다.`,
      ng:`듣는데 숨소리가 이쪽 귀로 들어온다. 귓속에서 쉰다.<br><br>탈 안 숨과 이쪽 숨이 맞춰진다. 머리가 무겁다. 탈을 쓴 것처럼 덥다.<br>일행이 어깨를 흔들어 깨웠다. 귀가 한참 먹먹했다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-26 } },
    { l:'③ 내공을 손목 혈로 아주 가늘게 흘려 탈 안을 더듬는다.', k:'gaze', dc:23, cost:{ qi:30 },
      ok:`손목에 손을 대지 않고 한 치 위에서 내공을 실처럼 흘려 넣었다. 맥을 타고 안으로.<br><br>안이 그려진다. 팔은 사람 팔이다. 어깨에서 끊긴다. 어깨 뒤는 솜과 철사다. 팔만 사람이다. 맥은 그 팔이 혼자 뛰는 것이다.<br>내공을 거두었다. 손목이 아쉬운 듯 손가락을 오므린다. 짚어 줄 손을 기다렸다.`,
      ng:`흘린 내공이 손목에서 사라진다. 끝도 없이 들어간다.<br><br>탈이 고개를 든다. 꺾였던 파란 목이 펴진다. 내공을 먹고 펴졌다.<br>내공을 끊고 물러났다. 탈이 의자에서 일어서려다 다시 앉았다. 아직은.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A1', t:'방청석 — 박수에 맞춰 느려지는 심장',
  x:`방청석 스피커에서 박수가 일정하게 나온다. 짝, 짝, 짝.<br><br>
    점점 느려진다. 일행 하나가 가슴을 움켜쥔다. 심장이 박수를 따라간다고 한다.<br>
    손목을 잡았다. 맥이 박수와 똑같다. 박수가 느려지면 맥도 느려진다.<br><br>
    박수는 끝날 때 끝난다. 맥도 그럴 것이다.`,
  o:[
    { l:'① 가슴과 손목 혈을 엇박으로 눌러 제 박자를 찾게 한다.', k:'heal', dc:23, wake:1,
      ok:`박수 사이사이에 눌렀다. 짝, 하면 쉬고, 그 사이에 손목 혈. 다음 사이에 가슴 혈. 박수와 어긋나게.<br><br>맥이 흔들린다. 박수를 따라가다 이쪽 누름을 따라간다. 엇박이 박자를 부순다. 부서진 자리에 그 사람 박자가 다시 올라온다. 빠르다. 무서워서 빠르다. 그게 그 사람 박자다.<br>박수가 그쳤다. 그 사람 맥은 그치지 않았다.<br><br>남의 박자를 엇박으로 깨뜨렸다. 맥에 맞서는 법이 손끝에 생겼다. 맞추는 것만이 아니라 어긋내는 것.`,
      ng:`엇박으로 누르는데 이쪽 손도 박수를 탄다. 누르는 박자가 박수 박자다.<br><br>그 사람 맥이 더 느려진다. 이쪽 손이 박수를 거들었다. 손을 뗐다.<br>일행이 귀를 막아 주고 방청석에서 끌어냈다. 계단에서 맥이 돌아왔다. 아주 늦게.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 내공을 실어 일행 다섯의 맥을 이쪽 박자로 이끈다.', k:'bond', dc:22, cost:{ qi:30 },
      ok:`다섯 손을 잇게 하고 내공을 흘렸다. 이쪽 맥 박자로. 크게, 또렷하게.<br><br>다섯 맥이 내공을 따라 이쪽 박자로 모인다. 박수보다 가까운 박자다. 손에서 손으로 전해지니까.<br>박수가 느려져도 다섯 맥은 그대로다. 방청석을 다 빠져나갈 때까지 손을 놓지 않았다.`,
      ng:`이끄는데 이쪽 맥도 박수를 듣고 있다. 내공이 박수 박자로 흐른다.<br><br>다섯 맥이 같이 느려진다. 이쪽이 끌고 들어갔다. 손을 놓았다. 다들 숨을 몰아쉰다.<br>방청석이 녹음된 환호를 터뜨렸다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'부조정실 — 화면의 맥 파형',
  x:`부조정실 모니터 하나에 초록 선이 흐른다. 맥 파형이다. 위아래로 뛴다.<br><br>
    화면 밑에 글씨. 스튜디오. 이 건물의 맥이라는 듯.<br>
    맥을 짚는 사람은 파형도 맥으로 읽는다. 오르는 높이, 내리는 깊이, 사이의 길이.<br><br>
    파형 옆에 숫자가 있다. 다섯 시까지 남은 분이다. 숫자가 줄 때마다 파형이 빨라진다.`,
  o:[
    { l:'① 파형을 읽어 이 건물이 무엇을 기다리는지 본다.', k:'gaze', dc:22,
      ok:`의자에 앉아 오래 봤다. 높게 뛰고 길게 쉰다. 쉬는 사이에 작은 파형이 다섯 개 끼어든다. 일정하다.<br><br>다섯은 이쪽 일행 수다. 건물 맥 사이에 이쪽 맥이 섞여 있다. 건물이 이쪽을 품고 뛴다. 다섯 시가 되면 큰 박자 하나로 합칠 셈이다.<br>합쳐지기 전에 나가야 한다. 남은 분을 외웠다. 조정판 밑 구급함에서 붕대도 챙겼다.`,
      ng:`읽는데 작은 파형 다섯 중 하나가 크다. 이쪽 맥이다. 무서워서 크게 뛴다.<br><br>큰 파형에 화면이 맞춰 커진다. 이쪽 맥만 확대된다. 화면 밑 글씨가 바뀐다. 오늘의 친구.<br>화면을 등지고 나왔다. 가슴이 한참 화면 박자로 뛰었다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 화면에 손끝을 대고 파형을 맥처럼 짚는다.', k:'sense', dc:23,
      doom:{ title:'생방송 맥', what:'짚은 손끝부터 화면 속으로 빨려 들어갑니다', dc:18, sec:50,
        text:`화면에 손끝 셋을 댔다. 파형이 손끝 밑을 지나간다. 맥이다. 정말로 뛴다. 유리가 미지근하다.<br><br>손끝이 유리에 붙는다. 파형이 손끝을 타고 올라온다. 손목, 팔꿈치. 이쪽 맥이 초록 선이 된다.<br>유리가 물러진다. 손끝이 화면 안으로 들어간다. 안쪽은 조명 열기다. 스튜디오다. 팔이 빨려 든다. 화면 속에서 카메라가 이쪽을 돌아본다.<br><br>숫자가 줄어든다. 파형이 하나로 합쳐진다.`,
        dieText:`부조정실 모니터에 초록 선이 흐른다.<br><br>오르고 쉬고, 그 사이에 작은 파형이 넷. 하나가 줄었다. 줄어든 하나는 큰 박자 안에 들어갔다.<br>큰 박자가 조금 사람 박자를 닮았다.` },
      ok:`손끝을 대기 직전에 멈추고 손등을 유리 앞에 댔다. 손등은 맥을 짚지 않는다. 듣기만 한다.<br><br>유리 너머 열기가 손등에 닿는다. 화면 속이 진짜 스튜디오다. 이 화면은 창이다.<br>손을 거두고 화면 전원을 껐다. 창 하나를 닫았다. 다섯 시에 열릴 창이 하나 줄었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'인형극 무대 — 실에 매달린 팔',
  x:`인형극 무대 앞에서 일행 하나의 팔이 저절로 올라간다.<br><br>
    손을 흔든다. 인사하듯. 천장에서 보이지 않는 줄이 내려와 손목에 걸린 것처럼.<br>
    그 사람은 팔에 힘이 안 들어간다고 한다. 제 팔이 아니라고.<br><br>
    맥을 짚어 보니 팔의 맥이 끊겼다 이어졌다 한다. 줄이 당길 때마다.`,
  o:[
    { l:'① 어깨와 팔꿈치 혈에 침을 놓아 팔을 제 몸에 붙든다.', k:'heal', dc:22,
      ok:`어깨 앞 혈과 팔꿈치 안쪽 혈. 침을 깊게 놓았다. 팔을 몸통에 잇는 혈이다.<br><br>줄이 당긴다. 팔이 올라가려다 멈춘다. 침이 붙든다. 줄이 몇 번 더 당기다 느슨해진다. 손목에서 무언가 툭 끊어지는 느낌.<br>팔이 툭 떨어진다. 그 사람이 손가락을 꼼지락거린다. 제 팔이다.`,
      ng:`침을 놓는데 줄이 세게 당긴다. 팔이 홱 올라간다. 침이 휜다.<br><br>그 사람 어깨가 빠졌다. 줄이 계속 당긴다. 무대 막 뒤에서 손 인형들이 손을 흔든다. 같은 박자로.<br>어깨를 끼우는 데 셋이 매달렸다. 그 사람이 한참 울었다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 내공을 손날에 실어 손목 위 허공을 끊는다.', k:'break', dc:23, cost:{ qi:25 },
      ok:`팔이 올라가는 순간 손목 한 뼘 위 허공을 손날로 쳤다. 내공을 실어서.<br><br>무언가 끊어진다. 팽팽하던 것이 풀리는 소리. 위쪽 어둠에서 무엇이 휘청한다.<br>그 사람 팔이 내려온다. 손목에 가는 붉은 줄이 감겨 있던 자국이 남았다.`,
      ng:`쳤는데 손날이 허공만 가른다. 줄이 없다. 아니면 이쪽 손날보다 위에 있다.<br><br>그 사람 팔이 휘둘린다. 이쪽 얼굴을 친다. 입술이 터졌다.<br>막 뒤에서 웃음소리가 난다. 손가락 몇 개로 치는 박수.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A2', t:'양호실 — 커튼 너머의 맥',
  x:`양호실 셋째 침대에 커튼이 쳐져 있다. 안에서 체온계 흔드는 소리. 탁, 탁, 탁.<br><br>
    커튼 밑단이 물에 떠 있다. 그 아래로 손 하나가 늘어져 있다. 침대 밖으로. 맥 짚기 좋게.<br>
    다른 손이 커튼 틈으로 나와 체온계를 흔든다. 어른 손이다. 보건 선생님 손이다.<br><br>
    둘 다 맥이 있다. 맥을 짚는 사람 눈에는 보인다.`,
  o:[
    { l:'① 늘어진 아이 손목을 짚어 열을 가늠한다.', k:'heal', dc:22,
      ok:`늘어진 손목에 손끝 셋을 얹었다. 뜨겁다. 열이 높다. 몇 해째 같은 열이다.<br><br>열을 내리는 혈을 손목 안쪽에서 찾아 오래 눌렀다. 손목이 아주 조금 식는다. 체온계 소리가 잠깐 멈춘다.<br>커튼 안에서 보건 선생님 손이 일지를 넘기는 소리. 열 조금 내림. 그리고 다시 탁, 탁.`,
      ng:`짚는데 손목이 차다. 열이 아니라 물이다. 손가락 사이로 물이 흐른다.<br><br>체온계 소리가 멈춘다. 커튼 틈의 손이 이쪽 이마를 짚는다. 열을 재듯이. 오래.<br>그 손이 떠날 때까지 움직이지 못했다. 이마가 시리다. 머리가 깨질 것 같다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 커튼 너머 두 맥을 숨소리로 듣는다.', k:'sense', dc:21, wake:1,
      ok:`커튼에 귀를 가까이 대고 들었다. 두 맥. 아이 것은 빠르고 얕다. 어른 것은 느리고 깊다.<br><br>어른 맥이 아이 맥을 쫓아간다. 아이가 빨라지면 어른도 빨라진다. 지키는 맥이다. 몇 해째 곁에서 같이 앓는 맥.<br>커튼 밖에 서서 두 맥이 고를 때까지 기다렸다. 그리고 소리 없이 물러났다.<br><br>짚지 않고 들어서 둘 사이를 알았다. 맥과 맥 사이의 일까지 듣는 귀. 맥을 듣는 자리가 손끝에서 귀까지 넓어졌다.`,
      ng:`듣는데 맥이 셋이다. 셋째는 이쪽 것이다. 커튼 안에서 들린다.<br><br>이쪽 맥이 커튼 안에서 뛴다. 손목을 짚어 보니 비었다. 맥이 없다.<br>뒷걸음질 쳤다. 양호실 문밖에서야 손목에 맥이 돌아왔다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'③ 커튼 틈 보건 선생님 손목을 마주 짚는다.', k:'bond', dc:23,
      doom:{ title:'보건 선생님', what:'짚은 손에 침대로 눕혀져 물 밑으로 가라앉습니다', dc:18, sec:45,
        text:`커튼 틈의 손목을 짚었다. 같은 일을 하는 손끼리. 맥이 느리고 깊다. 지친 맥이다.<br><br>손이 이쪽 손목을 마주 짚는다. 익숙한 손길이다. 그 손이 말한다. 열이 있네요. 누워요.<br>커튼이 열린다. 어깨를 누르는 손. 부드럽다. 다리가 침대 모서리에 걸린다. 등이 시트에 닿는다. 시트가 물속에 있다. 체온계가 입에 물린다.<br><br>침대가 가라앉는다. 천천히. 손목을 짚힌 채로. 맥을 센다. 탁, 탁, 탁.`,
        dieText:`양호실 셋째 침대에 커튼이 쳐져 있다.<br><br>안에서 체온계 흔드는 소리. 그리고 맥을 세는 소리. 둘이 센다.<br>보건 일지 마지막 줄 처치 칸에 다른 글씨가 늘었다. 맥 정상. 누워 있을 것.` },
      ok:`짚기 전에 커튼 너머로 말을 걸었다. 같은 일을 하는 사람에게. 오늘은 제가 볼게요. 쉬세요.<br><br>체온계 흔드는 손이 멈춘다. 한참 있다가 손이 커튼 안으로 들어간다. 일지 넘기는 소리. 인계.<br>커튼 틈으로 꿀 단지 하나가 밀려 나왔다. 아이들 목에 한 숟갈씩 주던 것이다.`,
      win:{ exp:22, dream:3, item:'꿀 한 줌' } }
  ] },

{ at:'A2', t:'세면장 — 혈로 드는 물',
  x:`세면장 물이 무릎까지 찼다. 일행 하나가 다리가 무겁다고 한다.<br><br>
    종아리를 만져 보니 물렁하다. 살 속에 물이 찼다. 발목 혈 자리마다 작은 구멍이 열려 있다.<br>
    맥을 짚는 사람은 안다. 혈은 기가 드나드는 문이다. 지금은 물이 드나든다.<br><br>
    물이 무릎 혈까지 올라간다. 몸 안쪽으로.`,
  o:[
    { l:'① 혈마다 쑥뜸을 떠 물을 끓여 밀어낸다.', k:'heal', dc:22,
      ok:`쑥을 작게 빚어 발목 혈, 무릎 혈에 얹었다. 젖은 다리에 불을 붙이는 건 어렵다. 다리를 물 밖 세면대에 올려 놓고 붙였다.<br><br>뜸이 타며 혈이 데워진다. 데워진 혈에서 물이 김이 되어 빠져나간다. 쉬익. 종아리가 가벼워진다.<br>뜸 자국이 혈마다 남았다. 문을 데워 닫은 자국이다.`,
      ng:`뜸을 얹는데 혈의 물이 불을 끈다. 치익.<br><br>다시 붙여도 꺼진다. 물이 무릎을 넘었다. 그 사람 다리가 얼음처럼 차다.<br>업고 세면장을 나왔다. 다리가 이쪽 등을 적셨다. 오래.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-26, spirit:-22 } },
    { l:'② 내공을 혈로 밀어 넣어 물기를 아래로 쫓아낸다.', k:'steady', dc:23, cost:{ qi:30 },
      ok:`무릎 혈에 손바닥을 대고 내공을 밀었다. 위에서 아래로. 물을 쫓듯이.<br><br>살 속의 물이 발목 쪽으로 밀린다. 발목 혈 구멍으로 쏟아진다. 맑지 않다. 비린 물이다.<br>마지막 방울이 빠지자 혈이 닫힌다. 그 사람이 다리를 굽혀 본다. 가볍다고.`,
      ng:`밀자 물이 위로 달아난다. 허벅지로, 허리로.<br><br>그 사람이 숨이 차다고 한다. 물이 가슴 쪽으로 간다. 내공을 거꾸로 돌려 겨우 붙잡았다.<br>물은 허리에서 멈췄다. 그 사람은 그날 내내 허리를 굽히지 못했다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A2', t:'기숙사 — 점호 전의 맥',
  x:`밤 아홉 시가 가까워진다. 복도 끝에서 발소리가 다가온다. 점호다.<br><br>
    일행 맥을 짚었다. 다섯의 맥이 한 박자로 모인다. 서로 맞춰진다. 아무도 맞추려 하지 않았는데.<br>
    기숙사 벽 너머에서도 맥이 들린다. 수백. 같은 박자다.<br><br>
    이름이 불리면 그 박자로 대답하게 될 것이다.`,
  o:[
    { l:'① 다섯 손목 혈을 하나씩 튕겨 박자를 어긋나게 한다.', k:'fix', dc:22, wake:1,
      ok:`한 사람씩 손목을 잡고 혈을 손톱으로 튕겼다. 하나는 빠르게, 하나는 늦게. 다섯을 다 다르게.<br><br>모이던 맥이 흩어진다. 제각각 뛴다. 벽 너머 수백의 맥 속에 다섯이 섞이지 못한다.<br>점호 발소리가 문 앞에서 멈춘다. 이름을 부른다. 다섯 중 아무도 대답하지 않았다. 박자가 안 맞아서 입이 안 열린다.<br><br>맥 하나하나를 일부러 흩뜨려 사람을 지켰다. 고르게 하는 것만이 다스리는 게 아니다. 손이 흩는 법을 얻었다.`,
      ng:`튕기는데 이쪽 맥이 이미 수백 박자에 섞였다. 튕기는 손이 그 박자로 튕긴다.<br><br>다섯이 더 단단히 모인다. 발소리가 문 앞에서 멈춘다. 이름이 불린다. 일행 하나가 숨을 들이켠다. 대답하려는 숨이다.<br>그 사람 입을 손으로 막았다. 막은 손바닥이 그 사람 입김에 얼었다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 대답하려는 입마다 손바닥으로 막는다.', k:'bond', dc:21,
      ok:`점호가 시작되기 전에 일행을 바짝 모았다. 이름이 불리면 이쪽이 입을 막겠다고 했다.<br><br>이름이 불린다. 하나의 입술이 열린다. 막았다. 다음. 또 막았다. 손이 둘이라 모자란다. 일행끼리 서로 막게 했다.<br>점호가 지나갔다. 결석 다섯. 복도 끝에서 출석부에 무언가 적는 소리.`,
      ng:`막는데 한 사람 입이 손바닥 밑에서 움직인다. 소리 없이. 네.<br><br>소리가 안 났는데 복도의 발소리가 멈춘다. 들었다. 입 모양을.<br>그 사람 방 앞에서 한참 기다리다 갔다. 그 사람이 밤새 떨었다.`,
      win:{ exp:16, dream:2, spirit:8 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A2', t:'수영장 — 건져 낸 사람의 맥',
  x:`수영장 가장자리에 일행 하나를 건져 올렸다. 물에 빠졌었다.<br><br>
    숨을 안 쉰다. 손목을 잡았다. 맥이 아주 약하다. 그런데 손목 말고 다른 데서 맥이 뛴다.<br>
    물속에서다. 그 사람 발이 아직 물에 잠겨 있다. 발목에서 물속으로 맥이 이어진다. 누가 그 맥을 쥐고 있다.<br><br>
    레인 줄 부표가 이쪽을 향해 조금씩 밀려온다.`,
  o:[
    { l:'① 인중과 가슴 혈을 짚어 깨운다.', k:'heal', dc:22,
      ok:`코 밑 인중을 엄지로 세게 눌렀다. 그다음 가슴 한가운데. 다시 인중.<br><br>헉. 그 사람이 물을 토한다. 숨을 몰아쉰다. 발을 물 밖으로 끌어 올렸다. 발목 맥이 물속에서 끊긴다.<br>그 사람 눈이 이쪽을 알아본다. 이름을 불렀다. 대답했다. 이쪽 이름으로.`,
      ng:`눌렀는데 안 깬다. 맥이 손목에서 점점 사라진다. 발목 쪽으로 옮겨 간다.<br><br>그 사람 발을 끌어 올리려는데 무겁다. 물속에서 쥐고 있다. 셋이 매달렸다.<br>발이 빠져나왔다. 그 사람이 깨어난 건 한참 뒤다. 발목에 손자국이 고리처럼 남았다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 내공을 실어 가슴을 쳐 물을 밀어낸다.', k:'heal', dc:23, cost:{ qi:25 },
      ok:`그 사람 몸을 옆으로 눕히고 등 혈을 손바닥으로 쳤다. 내공을 실어서.<br><br>물이 한꺼번에 쏟아진다. 그 사람이 기침한다. 숨이 돌아온다. 맥이 손목으로 몰려온다. 발목 쪽 맥이 놓쳐 버린다.<br>물속에서 무언가 빈손을 쥐었다 편다. 물결이 하나 번졌다.`,
      ng:`쳤는데 물이 안 나온다. 물이 폐 안에서 버틴다.<br><br>다시 쳤다. 내공이 바닥난다. 세 번째에 물이 반쯤 나왔다. 숨이 얕다.<br>그 사람은 살았다. 쌕쌕거리며. 오래.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-18 } },
    { l:'③ 물속으로 이어진 맥을 따라 손을 넣어 짚는다.', k:'sense', dc:24,
      doom:{ title:'물속의 맥', what:'맥을 쥔 손에 잡혀 레인 바닥으로 끌려갑니다', dc:19, sec:45,
        text:`발목에서 물속으로 이어진 맥을 따라 손을 넣었다. 맥이 손끝을 끈다. 아래로, 아래로.<br><br>끝에 손이 있다. 작은 손. 맥을 쥐고 있다. 그 손이 이쪽 손을 쥔다. 손바닥끼리 맥이 맞닿는다. 이쪽 맥이 그 손 박자로 바뀐다.<br>당긴다. 어깨가 물에 잠긴다. 얼굴이. 물속은 조용하다. 맥 소리만 크게 들린다. 수십. 레인마다.<br><br>위에서 일행이 그 사람을 끌어낸다. 이쪽 발목은 아무도 안 잡았다.`,
        dieText:`수영장 레인 줄에 부표가 다 찼다.<br><br>물속에서 맥이 뛴다. 수십. 그중 하나는 맥 짚는 법을 안다.<br>다음에 빠진 사람 발목을 쥐는 손이 손끝 셋을 따로 쓴다.` },
      ok:`손을 넣기 전에 손목에 침을 놓았다. 맥을 잠그는 혈에. 이쪽 맥이 손끝까지 오지 않게.<br><br>물속에 손을 넣었다. 맥이 손끝에 닿는다. 작은 손이 쥐고 있다. 이쪽 손끝엔 맥이 없다. 쥘 것이 없다. 작은 손이 더듬다 놓는다.<br>그 사람 발목 맥이 풀려 올라온다. 끌어 올렸다. 숨이 돌아왔다.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A2', t:'강당 — 이백열두 자리의 맥',
  x:`강당 관람석이 물에 잠겼다. 의자 등받이만 물 위로 나와 있다. 줄지어.<br><br>
    등받이마다 맥이 뛴다. 손을 대지 않아도 보인다. 물이 등받이 둘레에서 아주 조금씩 떨린다. 이백열두 자리.<br>
    맥을 짚어 온 사람에게 이 강당은 커다란 손목 하나다.<br><br>
    맥이 안 뛰는 자리가 있다. 비어 있는 자리다.`,
  o:[
    { l:'① 강당 전체 맥을 짚어 빈자리가 몇인지 센다.', k:'sense', dc:23, wake:1,
      ok:`관람석 맨 뒤에 서서 눈을 감았다. 손을 펴고 물 위로 띄웠다. 떨림이 손바닥에 닿는다. 이백열두 개의 떨림.<br><br>셌다. 줄마다. 빈자리가 다섯. 줄 가운데 몰려 있다. 이쪽 일행 수다. 맞춰 비워 두었다.<br>다섯 자리를 피해 벽 쪽 통로로 걸었다. 빈자리 다섯이 끝까지 비어 있었다.<br><br>사람 하나의 맥을 짚던 손이 방 하나를 짚었다. 이백열둘을 하나처럼 듣는 손. 손바닥이 넓어졌다.`,
      ng:`세는데 셀 때마다 빈자리가 옮겨 간다. 이쪽 일행이 서 있는 쪽으로.<br><br>다섯 자리가 가까워진다. 등받이가 이쪽을 향해 돌아앉는다. 앉으라고.<br>뛰어서 통로를 지났다. 물이 뒤에서 의자 수만큼 출렁였다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 다른 맥은 듣지 않고 일행 다섯 맥만 짚으며 걷는다.', k:'steady', dc:22,
      ok:`다섯을 한 줄로 세우고 이쪽이 맨 뒤에 섰다. 앞사람 손목을 잡았다. 앞사람이 그 앞사람을. 맥이 사슬처럼 이어진다.<br><br>강당의 이백열두 맥은 듣지 않았다. 손 안의 다섯만 들었다. 다섯이 고르면 됐다.<br>통로 끝까지 다섯 맥이 끊기지 않았다. 강당이 섭섭하다는 듯 물을 한 번 출렁였다.`,
      ng:`잡고 걷는데 맨 앞사람 맥이 바뀐다. 강당 박자로.<br><br>사슬을 타고 바뀐 박자가 내려온다. 하나씩. 이쪽 손까지 오기 전에 손을 놓았다.<br>맨 앞사람을 뒤에서 끌어안고 통로를 빠져나왔다. 그 사람 맥이 돌아오는 데 오래 걸렸다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-22, spirit:-24 } }
  ] }

]);


// ------------------------------------------
// 수도사 (monk) · 무력
// ------------------------------------------
kJob('monk', 'A', [

{ at:'A', t:'쉬는 자리 — 같이 읽는 목소리',
  x:`다들 잠들자 일어나 앉았다. 두 손을 모았다. 하루 끝의 기도다.<br><br>
    다친 사람 이름을 하나씩 부른다. 첫 이름을 부르자 어둠 저편에서 누가 같이 부른다.<br>
    한 박자 늦게. 목소리가 이쪽 것과 똑같다.<br><br>
    둘째 이름에서는 반 박자 늦다. 셋째에서는 같이 부른다. 넷째는 저쪽이 먼저 부를 것이다.`,
  o:[
    { l:'① 박자를 바꿔 가며 끝까지 기도를 마친다.', k:'steady', dc:22, wake:1,
      ok:`넷째 이름을 부르기 전에 숨을 길게 쉬었다. 한 번, 두 번. 박자를 늦췄다.<br><br>저쪽이 먼저 부른다. 넷째 이름을. 틀렸다. 이쪽이 정한 이름이 아니다. 이쪽은 아직 안 불렀으니까. 저쪽은 들은 것만 따라 할 수 있다. 틀린 이름이 어둠 속에 혼자 남는다.<br>그다음은 저쪽이 따라오지 못했다. 끝까지 불렀다.<br><br>정해진 박자를 지키는 것만이 기도가 아니다. 박자를 쥐고 바꾸는 것. 닦던 마음이 한 겹 단단해졌다.`,
      ng:`박자를 늦추는데 저쪽도 늦춘다. 같이 숨을 쉰다.<br><br>넷째 이름을 부르려는데 입이 안 열린다. 저쪽이 부른다. 이쪽 일행 이름이다. 맞게.<br>그 사람이 잠결에 뒤척인다. 기도를 멈추고 그 사람 손을 잡았다. 날이 샐 때까지.`,
      win:{ exp:22, dream:3, hp:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 기도를 접고 손으로 셋의 상처를 씻긴다.', k:'heal', dc:21,
      ok:`기도를 접었다. 물을 데워 잠든 셋의 상처를 하나씩 씻겼다.<br><br>어둠 저편 목소리가 혼자 이름을 부른다. 받을 기도가 없다. 이쪽은 손으로 기도하는 중이니까.<br>목소리가 점점 작아진다. 따라 할 소리가 없으면 저쪽은 할 말이 없다.`,
      ng:`씻기는데 저쪽 목소리가 이번엔 씻는 소리를 따라 한다. 물 소리. 천 짜는 소리.<br><br>바로 등 뒤에서. 돌아보지 않았다. 손이 떨려 물그릇을 엎었다.<br>남은 물이 없다. 셋째 사람 상처는 못 씻었다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'복도 — 무거워지는 등',
  x:`다리를 다친 일행을 업었다. 끈으로 묶었다. 걷는다.<br><br>
    백 걸음쯤에서 등이 무겁다. 이백 걸음에서 더 무겁다. 업힌 사람은 그대로다. 등 위 무게만 는다.<br>
    물을 지고 산을 오르내려 본 몸은 무게를 정확히 안다. 지금 등에 둘이 있다.<br><br>
    업힌 사람이 귀에 대고 속삭인다. 왜 이렇게 숨이 차요. 둘째의 숨이다.`,
  o:[
    { l:'① 힘으로 끝까지 업고 걷는다. 내려놓지 않는다.', k:'steady', dc:23, cost:{ might:30 }, wake:1,
      ok:`허리를 세우고 무게를 땅으로 내렸다. 발바닥으로 업었다. 둘이면 둘을 업는다.<br><br>걸었다. 복도 끝까지. 등의 둘째 것이 점점 더 무거워진다. 그래도 걸었다. 무거워지는 것이 힘이 드는지 숨이 거칠어진다. 이쪽 숨이 아니다.<br>복도 끝에서 무게가 툭 떨어진다. 둘째가 먼저 지쳤다. 내려 업힌 사람은 하나다.<br><br>무게를 버티는 것이 무게를 이겼다. 업는 몸이 버티는 몸으로, 버티는 몸이 이기는 몸으로 한 걸음 갔다.`,
      ng:`반쯤 가서 무릎이 꺾였다. 둘이 같이 넘어졌다. 셋이다.<br><br>다친 다리가 바닥에 부딪친다. 그 사람이 비명을 지른다. 등 위 셋째 무게가 웃는다.<br>다른 일행이 그 사람을 받아 업었다. 이쪽 등이 한참 차가웠다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-28, mind:-18 } },
    { l:'② 내려놓고 업힌 사람 등 뒤를 본다.', k:'gaze', dc:22,
      ok:`벽에 기대 그 사람을 내려놓았다. 등잔을 들어 그 사람 등 뒤를 비췄다.<br><br>아무것도 없다. 대신 그 사람 그림자가 둘이다. 하나는 그 사람 것이고 하나는 그 사람 어깨에 턱을 괸 무엇이다.<br>등잔을 그림자 쪽으로 바짝 댔다. 그림자 하나가 빛에 밀려 벽 틈으로 빠진다. 다시 업으니 하나 무게다.`,
      ng:`내려놓는데 무게가 안 내려간다. 업힌 사람은 내려갔다. 등은 여전히 무겁다.<br><br>이쪽 등에 남았다. 돌아볼 수가 없다. 목덜미에 찬 턱이 닿아 있다.<br>복도 끝 빛 아래로 나와서야 무게가 사라졌다. 어깨에 손자국 열 개가 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-26 } },
    { l:'③ 무게가 기우는 쪽으로 몸을 숙여 따라 걷는다.', k:'bond', dc:23,
      doom:{ title:'둘째 무게', what:'업은 것에게 거꾸로 업혀 끌려갑니다', dc:18, sec:50,
        text:`무게가 기우는 쪽으로 몸을 숙였다. 그래야 덜 넘어진다. 복도 옆 어두운 통로 쪽이다.<br><br>숙일수록 무게가 앞으로 쏠린다. 등에서 어깨로, 어깨에서 머리로. 발이 땅에서 떨어진다. 업힌 것이 이쪽을 업는다. 거꾸로.<br>팔이 이쪽 다리를 감는다. 길다. 어두운 통로 쪽으로 걷는다. 이쪽 발은 허공이다. 업혀 간다.<br><br>원래 업혔던 일행이 바닥에 떨어진다. 부르는 소리가 멀다.`,
        dieText:`복도 옆 어두운 통로에서 발소리가 난다. 한 사람 발소리다.<br><br>무거운 것을 업은 걸음이다. 허리를 세우고 발바닥으로 업는 걸음.<br>다음에 업힌 사람이 지나갈 때 그 발소리가 따라붙었다. 도와주려는 것처럼.` },
      ok:`숙이려다 멈췄다. 무게가 기우는 쪽은 길이 아니다. 무게가 원하는 쪽이다.<br><br>반대로 몸을 틀었다. 무게가 버둥댄다. 이쪽 어깨를 할퀸다. 버텼다. 반대쪽으로 열 걸음.<br>무게가 놓았다. 등 뒤에서 어두운 통로로 무언가 기어 들어갔다. 업힌 사람은 잠들어 있었다.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A', t:'계단 — 미는 문',
  x:`계단 위 문을 닫았다. 저편에서 밀린다.<br><br>
    세게는 아니다. 꾸준히. 한 번씩. 문틈이 손가락 하나만큼 벌어졌다 닫힌다.<br>
    벌어질 때마다 차가운 바람과 손가락 끝이 보인다. 손가락이 많다.<br><br>
    일행은 아래로 내려가야 한다. 다 내려갈 때까지 누가 문을 받쳐야 한다.`,
  o:[
    { l:'① 등을 문에 대고 힘으로 받친다.', k:'steady', dc:23, cost:{ might:30 },
      ok:`문에 등을 대고 두 발을 버텼다. 무게를 땅에 박았다.<br><br>쿵. 밀린다. 버텼다. 쿵. 버텼다. 문틈이 더 벌어지지 않는다. 일행이 하나씩 계단 아래로 내려간다.<br>마지막 일행이 내려간 걸 보고 등을 뗐다. 문이 저절로 활짝 열린다. 아무도 없다. 미는 쪽은 이쪽이 떠나기를 기다렸다. 이쪽은 이미 계단 중간이다.`,
      ng:`버티는데 미는 손이 문틈으로 들어온다. 이쪽 허리를 짚는다. 차다.<br><br>힘이 빠진다. 문이 한 뼘 열린다. 손가락들이 이쪽 옷을 쥔다. 옷을 찢고 뛰었다.<br>계단 아래까지 손가락 자국이 등에 줄지어 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 일행을 먼저 보내고 문이 열리는 순간 비켜선다.', k:'evade', dc:22,
      ok:`문고리를 잡고 버티면서 일행을 먼저 보냈다. 마지막 하나가 내려간 순간 문고리를 놓고 옆으로 몸을 날렸다.<br><br>문이 쾅 열린다. 차가운 것이 쏟아져 들어와 이쪽이 서 있던 자리를 덮친다. 텅 빈 자리를. 손가락들이 바닥을 긁는다.<br>그 틈에 계단 난간을 타고 미끄러져 내려갔다.`,
      ng:`몸을 날렸는데 늦었다. 쏟아진 차가운 것이 발목을 덮친다.<br><br>발목이 얼어붙는다. 끌고 계단을 내려왔다. 발목 아래가 남의 것 같다.<br>다음 쉬는 자리까지 일행 어깨를 빌렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A', t:'어둠 — 기도를 청하는 목소리',
  x:`어둠 속에서 목소리가 부른다. 저기요, 손 모으시는 분.<br><br>
    부드러운 목소리다. 기도해 줄 수 있느냐고 묻는다. 자기는 여기서 죽었다고. 아무도 기도해 주지 않았다고.<br>
    기도하는 사람은 그 청을 쉽게 못 거절한다. 청하는 기도는 받아 주는 것이 도리다.<br><br>
    목소리가 덧붙인다. 이름은 묻지 마세요.`,
  o:[
    { l:'① 이름을 묻지 않고 짧게 기도만 해 준다.', k:'bond', dc:22, wake:1,
      ok:`그 자리에 서서 손을 모았다. 이름을 묻지 않았다. 이름 없이 기도했다. 여기서 죽은 이에게. 짧게.<br><br>목소리가 조용히 듣는다. 다 듣고 나서 한숨을 쉰다. 길고 편하게. 고맙다고 한다. 그리고 덧붙인다. 아래층 셋째 문은 열지 마세요.<br>어둠이 조금 옅어진다. 그 사람이 있던 자리만큼.<br><br>이름도 얼굴도 모르는 것을 위해 손을 모았다. 기도가 아는 사람을 넘어 닿았다. 마음이 그만큼 넓어졌다.`,
      ng:`기도하는데 목소리가 이름을 말한다. 묻지 않았는데.<br><br>이쪽 이름이다. 여기서 죽은 사람 이름이 이쪽 이름이다. 손이 굳는다. 기도가 끊긴다.<br>목소리가 웃는다. 끝까지 해 주셔야죠. 등을 돌려 걸었다. 그 이름이 등 뒤에서 오래 불렸다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 지금은 갈 길이 있다며 고개 숙여 지나간다.', k:'steady', dc:21,
      ok:`고개를 숙였다. 지금은 산 사람이 먼저라고 말했다. 나가서 꼭 해 주겠다고.<br><br>목소리가 한참 말이 없다. 그러다 약속이라고 한다.<br>지나갔다. 이 약속은 지켜야 할 것이다. 지키지 않으면 다음엔 저쪽이 찾아올 것이다.`,
      ng:`지나가려는데 목소리가 울기 시작한다. 크게.<br><br>울음이 어둠 전체에서 난다. 수십의 목소리로. 다 기도를 받지 못했다고.<br>귀를 막고 걸었다. 막은 손 사이로 울음이 비집고 들어왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 넷이 들어갈 방',
  x:`쉴 만한 방을 찾았다. 문이 잠긴다. 넷이 누울 만하다.<br><br>
    일행은 다섯이다.<br>
    문밖은 복도다. 복도 끝 어둠에서 무언가 기다린다. 소리 없이.<br><br>
    자리가 모자라면 누가 나가는지 묻지 않아도 안다. 그런 몸으로 오래 살았다.`,
  o:[
    { l:'① 자리를 내주고 문밖에 등을 대고 앉는다.', k:'steady', dc:22, wake:1,
      ok:`문밖에 앉았다. 등을 문에 대고. 다리를 꼬고, 손을 모았다.<br><br>복도 끝 어둠이 밤새 조금씩 다가왔다. 다가올 때마다 숨을 셌다. 숨은 셀 만하다. 어둠이 코앞에서 멈췄다. 앉은 사람이 깨어 있는 걸 보고.<br>새벽에 어둠이 물러갔다. 일어나니 다리가 가볍다.<br><br>문밖 한 자리가 문 안 네 자리를 지켰다. 버틴 몸이 아니라 닦인 몸이다. 앉음 하나가 벽이 됐다.`,
      ng:`밤 중간에 숨을 놓쳤다. 졸았다.<br><br>눈을 뜨니 어둠이 무릎 위에 있다. 차다. 소리를 질렀다. 일행이 문을 열고 끌어들였다.<br>방에 다섯이 끼어 앉았다. 아무도 못 잤다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 짐을 빼고 다섯이 붙어 앉게 자리를 고친다.', k:'heal', dc:21,
      ok:`짐을 다 빼서 문 앞에 쌓았다. 다섯을 바짝 붙여 앉혔다. 다친 사람은 가운데, 덜 다친 사람은 바깥.<br><br>이쪽은 제일 바깥이다. 어깨 반이 문에 붙는다. 다섯 체온이 모이니 방이 데워진다.<br>밤새 문을 두드리는 소리가 났다. 짐이 버텼다. 아무도 앓지 않았다.`,
      ng:`붙어 앉으니 다친 사람이 눌린다. 신음한다.<br><br>자리를 다시 바꾸는 사이 문이 덜컹인다. 짐더미가 무너진다.<br>밤새 이쪽이 등으로 문을 받쳤다. 아침에 허리를 펴지 못했다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-26, mind:-16 } },
    { l:'③ 문밖 어둠을 향해 앉아 눈을 감는다.', k:'gaze', dc:23,
      doom:{ title:'문밖 자리', what:'눈을 감은 채 어둠에 실려 갑니다', dc:18, sec:50,
        text:`문밖에 앉았다. 어둠을 마주 보고. 눈을 감았다. 두려운 것을 마주하고 눈을 감는 것도 닦는 일이다.<br><br>숨을 셌다. 백. 이백. 어둠이 다가오는 소리가 없다. 소리가 없으니 모른다.<br>무릎 밑이 들린다. 앉은 그대로. 바닥이 미끄러진다. 아니, 이쪽이 미끄러진다. 어둠이 앉은 사람을 앉은 채 들어 나른다. 조심스럽게. 기도를 깨우지 않으려는 것처럼.<br><br>눈을 뜨면 끝날 것 같다. 뜨지 않으면 끝까지 갈 것 같다.`,
        dieText:`아침에 일행이 문을 열었다. 문밖이 비었다.<br><br>복도 끝 어둠 속에 누가 앉아 있다. 다리를 꼬고, 손을 모았다. 등을 이쪽으로 돌렸다.<br>다음 밤부터 그 복도 끝 어둠은 다가오지 않았다. 앉은 것이 대신 지킨다. 어느 쪽을 지키는지는 모른다.` },
      ok:`눈을 감으려다 반만 감았다. 속눈썹 사이로 어둠을 봤다.<br><br>어둠이 다가온다. 소리 없이. 다가올 때마다 손바닥을 바닥에 내리쳤다. 쿵. 어둠이 멈춘다. 다시 다가온다. 쿵.<br>밤새 그랬다. 손바닥이 부었다. 어둠은 끝내 무릎에 닿지 못했다.`,
      win:{ exp:22, dream:3, mind:8 } }
  ] },

{ at:'A', t:'통로 — 흩어진 염주 알',
  x:`통로 바닥에 염주 알이 흩어져 있다. 끈이 끊겼다.<br><br>
    알이 닳았다. 오래 돌린 염주다. 주인은 없다.<br>
    염주를 돌려 본 손은 알을 그냥 두지 못한다. 하나라도 빠지면 염주가 아니다.<br><br>
    알들이 통로 안쪽으로 줄지어 굴러가 있다. 줍다 보면 안쪽으로 가게 된다.`,
  o:[
    { l:'① 손 닿는 데까지만 주워 남은 끈에 꿴다.', k:'fix', dc:22,
      ok:`손 닿는 데까지만 주웠다. 한 발도 안쪽으로 들이지 않았다. 마흔둘.<br><br>남은 끈에 꿰었다. 반도 안 된다. 반 염주도 돌릴 수 있다. 돌리며 주인을 위해 경을 읽었다.<br>안쪽에 남은 알들이 아주 조금씩 굴러 나온다. 경 소리 쪽으로. 하나, 둘. 다 꿰어지지는 않았다. 그래도 쉰을 넘겼다.`,
      ng:`줍다 보니 한 발이 안쪽에 들어가 있다. 언제 들어갔는지 모른다.<br><br>알이 발밑에서 굴러 더 안쪽으로 간다. 발이 따라간다. 일행이 허리를 잡아당겼다.<br>주운 알이 손바닥에서 차다. 하나는 알이 아니라 손가락 마디였다.`,
      win:{ exp:18, dream:2, spirit:8 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 알 하나를 굴려 어디로 가는지 본다.', k:'gaze', dc:21,
      ok:`알 하나를 집어 바닥에 굴렸다. 똑바로 굴러간다. 그러다 휜다. 통로 왼쪽 벽 아래로. 거기서 멈춘다.<br><br>벽 아래 틈이 있다. 알이 다 그쪽으로 가 있었다. 틈 안에서 바람이 들어온다. 당기는 바람이다.<br>알을 따라가면 안 된다. 알이 가는 쪽을 피해서 오른쪽 길로 갔다.`,
      ng:`굴린 알이 되돌아온다. 이쪽 발끝까지. 거기서 멈춘다.<br><br>다른 알들도 하나씩 돌아온다. 이쪽 발 주위에 둥글게 모인다. 염주가 된다. 이쪽 발목을 꿰는 염주.<br>발을 빼서 뛰었다. 등 뒤에서 알들이 짤그락 따라 굴렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 씻기지 않는 손',
  x:`쉬는 자리에서 제 손을 봤다. 피가 말라붙었다. 오늘 업고 끌고 묶은 사람들 것이다.<br><br>
    물 한 줌으로 씻는다. 늘 그렇게 해 왔다.<br>
    오늘은 안 지워진다. 문지를수록 손금마다 붉다. 손금이 원래보다 많다.<br><br>
    새로 생긴 손금이 다른 사람 손금이다.`,
  o:[
    { l:'① 이름을 하나씩 부르며 물 한 줌으로 오래 씻는다.', k:'heal', dc:22,
      ok:`손바닥에 물을 한 줌만 붓고 천천히 비볐다. 오늘 만진 사람 이름을 하나씩 불렀다. 일행 넷. 그리고 길에서 만난 것들. 이름 모르는 것은 생김새로.<br><br>부를 때마다 손금 하나가 지워진다. 남의 손금이 제 주인에게 돌아간다. 마지막에 제 손금만 남았다.<br>물 한 줌이면 된다. 오래 비비면.`,
      ng:`부르는데 이름이 모자란다. 손금은 아직 많다. 모르는 사람 것이다.<br><br>문지를수록 손이 남의 손 같다. 쥐는 버릇이 바뀐다. 주먹을 쥐면 엄지가 안으로 들어간다. 이쪽은 원래 밖으로 쥔다.<br>밤새 손을 펴고 잤다. 아침에도 그대로다.`,
      win:{ exp:18, dream:2, mind:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 손을 흙에 묻었다가 털어 낸다.', k:'steady', dc:21,
      ok:`바닥 흙을 파고 두 손을 묻었다. 흙은 무엇이든 받는다. 손을 묻고 앉아 숨을 셌다.<br><br>흙이 손금을 빨아들인다. 차갑다가 미지근해진다. 남의 것이 흙으로 간다.<br>털어 냈다. 손이 깨끗하다. 묻었던 자리 흙이 손 모양으로 오목하다. 그 위에 돌을 하나 얹어 두었다.`,
      ng:`묻었는데 흙 속에서 손을 잡는다. 여럿이.<br><br>빼냈다. 손에 흙이 아니라 피가 더 묻었다. 흙 밑에 먼저 묻힌 손들이 있었다.<br>그 자리를 떠났다. 손을 계속 바지에 문질렀다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'어둠 — 손을 드는 낯선 사람',
  x:`통로 벽에 낯선 사람이 기대 있다. 다른 일행이었던 사람이다. 혼자 남았다.<br><br>
    숨이 얕다. 많이 안 남았다. 그 사람이 손을 든다. 잡아 달라는 것 같다.<br>
    마지막 숨을 지켜 주는 것은 기도하는 사람의 일이다.<br><br>
    그 사람 그림자가 벽에 비친다. 손을 든 그림자다. 그런데 그림자는 손을 둘 들었다.`,
  o:[
    { l:'① 한 손만 잡고 끝까지 곁에 있는다.', k:'bond', dc:22,
      ok:`든 손 하나를 잡았다. 그림자의 다른 손은 보지 않았다.<br><br>그 사람이 무언가 말한다. 이름 같다. 들은 대로 따라 불러 주었다. 숨이 길어졌다가 멎었다. 눈을 감겼다.<br>벽의 그림자가 손 하나를 내린다. 다른 손은 그대로 들고 있다. 잡아 줄 사람을 기다린다. 그 손은 사람 손이 아니다. 일어나 걸었다.`,
      ng:`잡는데 그 사람이 꽉 쥔다. 안 놓는다. 숨이 멎은 뒤에도.<br><br>벽 그림자의 다른 손이 이쪽 그림자 어깨를 짚는다. 차다. 진짜 어깨가.<br>손가락을 하나씩 펴는 데 오래 걸렸다. 어깨는 저녁까지 시렸다.`,
      win:{ exp:18, dream:3, spirit:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 아직 살릴 수 있는지 숨을 살핀다.', k:'heal', dc:21,
      ok:`가슴에 귀를 댔다. 물이 찬 소리다. 몸을 옆으로 눕히고 등을 두드렸다. 물이 쏟아진다.<br><br>숨이 조금 깊어진다. 살렸다고는 못 한다. 시간을 조금 벌었다.<br>그 사람 품에 꿀 한 줌이 있다. 제게 쓸 겨를이 없던 것이다. 입술에 조금 발라 주고 나머지는 챙겼다.`,
      ng:`귀를 댔는데 소리가 없다. 이미 늦었다. 손을 든 건 숨이 아니었다.<br><br>그림자의 두 손이 다 이쪽을 향한다. 뒷걸음질 쳤다. 그림자가 벽을 타고 한참 따라왔다.<br>벽이 끝나는 데서 놓쳤다.`,
      win:{ exp:16, dream:2, item:'꿀 한 줌' }, lose:{ hp:-22, spirit:-26 } },
    { l:'③ 마지막 기도를 소리 내어 해 준다.', k:'steady', dc:23,
      doom:{ title:'마지막 기도', what:'기도 소리째 벽 그림자 속으로 빨려 들어갑니다', dc:18, sec:50,
        text:`곁에 앉아 소리 내어 기도했다. 마지막 기도다. 가는 길이 편하라고.<br><br>그 사람 숨이 멎는다. 기도는 계속된다. 벽의 그림자가 기도 소리를 들이마신다. 소리가 그림자 입으로 빨려 간다. 소리를 따라 숨이, 숨을 따라 몸이.<br>그림자가 두 손으로 이쪽 그림자를 안는다. 진짜 몸이 벽 쪽으로 기운다. 벽이 차다. 물 같다. 들어간다.<br><br>기도가 끝나지 않는다. 끝낼 입이 이미 벽 안에 있다.`,
        dieText:`통로 벽에 그림자가 둘 비친다. 기대 앉은 사람 그림자. 그 곁에 손을 모은 그림자.<br><br>다음 사람이 지나갈 때 벽에서 기도 소리가 났다. 작게, 끊이지 않게.<br>가는 길이 편하라고. 누구의 길인지는 말하지 않는다.` },
      ok:`기도를 소리 내지 않았다. 입술만 움직였다. 소리는 그 사람 귀에만 닿게, 귀에 바짝 대고.<br><br>그 사람 숨이 멎는다. 벽 그림자가 고개를 숙인다. 들이마실 소리가 없다.<br>그림자가 두 손을 내린다. 그 사람 그림자와 겹쳐 하나가 된다. 같이 간 것이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'계단 — 내려앉는 천장',
  x:`계단참 천장에서 가루가 떨어진다. 금이 번진다.<br><br>
    다들 위를 본다. 다친 일행 하나가 계단에 누워 있다. 일어날 수 없다.<br>
    도망치는 법보다 덮는 법을 먼저 배운 몸이다. 다친 사람 위에 엎드리는 법.<br><br>
    금 사이로 천장 안쪽이 보인다. 안쪽에 무언가 웅크리고 있다. 천장을 무겁게 하는 것이.`,
  o:[
    { l:'① 다친 이 위에 엎드려 힘으로 등을 굳힌다.', k:'steady', dc:23, cost:{ might:30 }, wake:1,
      ok:`다친 사람 위에 엎드렸다. 팔꿈치와 무릎으로 땅을 짚고 등을 굳혔다. 무게를 땅으로.<br><br>천장이 내려앉는다. 등에 떨어진다. 돌이 아니다. 무겁고 물렁하다. 웅크렸던 것이다. 이쪽 등을 딛고 선다. 버텼다. 그것이 등 위에서 한참 머문다. 아래를 들여다보려고.<br>못 들여다본다. 등이 덮고 있으니까. 그것이 지쳐 떠난다.<br><br>등 하나가 지붕이 됐다. 다친 사람을 덮는 몸이 무엇이 와도 열리지 않는 몸으로 굳어 간다.`,
      ng:`엎드렸는데 그것의 무게가 생각보다 크다. 등이 꺼진다.<br><br>팔꿈치가 미끄러진다. 아래 사람이 눌려 신음한다. 그것이 틈으로 손을 넣는다.<br>일행이 막대로 그것을 쳐서 떼어 냈다. 등이 퍼렇게 멍들었다. 아래 사람은 갈비가 금 갔다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 다친 이를 끌어당겨 계단 아래로 굴러 피한다.', k:'evade', dc:22,
      ok:`누운 사람 어깨를 잡고 확 당겼다. 둘이 같이 계단을 굴렀다.<br><br>방금 누웠던 자리에 천장이 쏟아진다. 돌과 함께 무언가 떨어진다. 바닥에서 몸을 펴고 일어선다. 아무도 없는 자리를 내려다본다.<br>그사이 계단 아래 모퉁이를 돌았다. 다친 사람 이마가 깨졌다. 그래도 거기 깔리는 것보다 낫다.`,
      ng:`당기는데 무겁다. 반만 끌었다.<br><br>다친 사람 다리에 돌이 떨어진다. 그리고 떨어진 것이 그 다리를 쥔다.<br>셋이 매달려 겨우 빼냈다. 다리에 손가락 자국이 다섯 줄로 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-22 } }
  ] },

{ at:'A', t:'마지막 쉼 — 졸지 않는다',
  x:`내려가기 전, 마지막 쉼이다. 다들 쓰러지듯 잠들었다.<br><br>
    누군가 지켜야 한다. 밤을 새우는 법은 안다. 앉아서, 등을 세우고, 숨을 센다.<br>
    오늘은 많이 업고 많이 막았다. 눈꺼풀이 무겁다.<br><br>
    어둠이 문틈에서 숨을 고른다. 앉은 사람이 졸기를 기다린다.`,
  o:[
    { l:'① 등을 세우고 숨을 세며 밤새 지킨다.', k:'steady', dc:22, wake:1,
      ok:`등을 세우고 앉았다. 숨을 셌다. 천까지 세고 다시 하나부터.<br><br>어둠이 몇 번 문틈을 넘어왔다. 앉은 사람이 깨어 있는 걸 보고 물러났다. 넘어올 때마다 조금 덜 넘어왔다.<br>새벽이 왔다. 일어나니 몸이 가볍다.<br><br>지친 몸으로 밤 하나를 지켰다. 어디서든 앉으면 그 자리가 닦는 자리가 된다. 몸이 그걸 알았다.`,
      ng:`세다가 숫자를 놓쳤다. 졸았다.<br><br>눈을 뜨니 어둠이 바로 앞이다. 손을 뻗으면 닿을 거리. 일행 하나의 발목을 쥐고 있다.<br>소리를 지르자 물러났다. 그 사람 발목에 검은 자국이 남았다.`,
      win:{ exp:24, dream:3, mind:8 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 잠든 동료들의 상처를 다시 본다.', k:'heal', dc:21,
      ok:`등잔을 낮추고 하나씩 상처를 봤다. 풀린 붕대를 다시 감고 덧난 데를 씻었다. 아무도 안 깼다.<br><br>상처를 보는 동안은 졸리지 않는다. 손이 움직이니까. 다섯째를 마치니 새벽이다.<br>아침에 다들 상처가 덜 아프다고 한다. 왜인지는 아무도 모른다.`,
      ng:`보는데 등잔이 꺼졌다.<br><br>어둠 속에서 붕대를 감다 엉뚱한 데를 감았다. 손목이 하나 더 있었다. 차가운 손목.<br>아침에 다들 이상하게 감긴 붕대를 풀었다. 붕대 하나가 비어 있었다.`,
      win:{ exp:16, dream:2, hp:8 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'로비 — 팔 벌린 뭉치',
  x:`로비 한가운데 뭉치가 서 있다. 갈색 털이 천장까지 닿을 듯하다. 단추 눈 두 개.<br><br>
    두 팔을 벌리고 있다. 천천히. 반갑다는 몸짓이다. 좀약 냄새가 확 끼친다.<br>
    안아 달라는 것에게 등을 돌리는 건 기도하는 사람에게 어려운 일이다.<br><br>
    뭉치 발치에 신발이 몇 켤레 놓여 있다. 끈이 가지런히 묶였다.`,
  o:[
    { l:'① 안기지 않고 털 난 손만 두 손으로 맞잡는다.', k:'bond', dc:22,
      ok:`다가가 벌린 팔 안으로 들어가지 않았다. 뻗은 손 하나만 두 손으로 맞잡았다. 인사하듯 고개를 숙였다.<br><br>뭉치가 멈춘다. 안으려던 팔이 공중에서 머뭇거린다. 손을 잡혀 본 적은 없는 모양이다.<br>한참 맞잡고 있다가 놓았다. 뭉치가 팔을 내린다. 길을 비킨다. 털 속에서 작은 소리가 났다. 고마워, 친구.`,
      ng:`맞잡는데 뭉치 손이 이쪽 손을 털 속으로 끌어들인다. 팔꿈치까지.<br><br>털 안이 따뜻하다. 안쪽에서 다른 손들이 이쪽 손을 잡는다. 작은 손들. 여럿이.<br>빼냈다. 소매가 털에 엉켜 찢어졌다. 팔에 좀약 냄새가 배어 빠지지 않는다.`,
      win:{ exp:18, dream:2, spirit:8 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 힘을 실어 벌린 팔을 밀쳐 길을 낸다.', k:'break', dc:23, cost:{ might:25 },
      ok:`어깨를 낮추고 힘을 모아 뭉치 옆구리를 밀쳤다. 무겁다. 솜이 아니다. 솜 속에 무게가 있다.<br><br>뭉치가 한 걸음 비틀거린다. 벌린 팔이 허공을 안는다. 그 틈에 일행이 옆으로 빠졌다.<br>뭉치가 다시 팔을 벌리고 섰다. 빈 팔이다. 단추 눈이 이쪽을 따라온다. 서운한 눈이다.`,
      ng:`밀쳤는데 솜이 받아 낸다. 힘이 다 먹힌다.<br><br>뭉치가 팔을 오므린다. 이쪽이 그 안에 있다. 털이 얼굴을 덮는다. 숨이 털 사이로만 난다.<br>일행이 다리를 잡아당겨 겨우 빠져나왔다. 숨이 한참 차올랐다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A1', t:'방청석 — 손에서 손으로',
  x:`방청석 위로 일행 하나가 떠간다. 누운 채로. 의자 사이에서 손들이 올라와 받쳐 든다.<br><br>
    손에서 손으로 넘긴다. 무대 쪽으로. 스피커에서 함성이 터진다. 오늘의 친구!<br>
    일행이 버둥댄다. 손들이 부드럽게 붙든다. 놓치지 않게.<br><br>
    빈 의자마다 손이 올라와 있다. 다음 사람을 기다리는 손도 있다.`,
  o:[
    { l:'① 힘으로 손들을 헤치고 일행을 끌어내린다.', k:'break', dc:23, cost:{ might:30 },
      ok:`의자 등받이를 밟고 올라서 일행 발목을 잡았다. 힘을 모아 끌어내렸다. 손들이 놓지 않는다. 한 손씩 떼어 냈다.<br><br>손들이 차다. 작고 많다. 떼어 낸 손은 의자 밑으로 들어간다. 다른 손이 올라온다. 쉬지 않고 떼었다.<br>일행이 떨어진다. 이쪽 품으로. 무대 앞까지 세 줄 남았었다.`,
      ng:`끌어내리는데 손들이 이쪽 발목도 잡는다. 이쪽도 들린다.<br><br>둘이 같이 떠간다. 손에서 손으로. 이쪽 팔이 일행 팔을 붙들었다. 놓지 않았다.<br>무대 직전에서 다른 일행이 의자를 넘어뜨렸다. 손들이 흩어졌다. 둘이 떨어졌다. 무릎이 깨졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-22 } },
    { l:'② 의자 사이에 서서 손들을 향해 경을 읽는다.', k:'steady', dc:22, wake:1,
      ok:`의자 사이 통로에 서서 손을 모았다. 경을 읽었다. 함성보다 낮게, 함성보다 오래.<br><br>손들이 멈춘다. 하나씩. 경 소리를 듣는다. 들어 올린 일행을 내려놓는 손이 있다. 또 하나. 손들이 의자 밑으로 들어간다. 박수를 칠 손을 모은다. 이쪽처럼.<br>일행이 의자 위에 내려졌다. 함성이 그쳤다.<br><br>힘으로 떼지 않고 소리로 내려놓게 했다. 기도가 손이 하는 일을 대신했다. 그 기도가 몸에 깊이 들었다.`,
      ng:`읽는데 함성이 더 커진다. 경 소리를 덮는다.<br><br>손들이 이쪽 쪽으로도 올라온다. 경 읽는 입을 막으려고. 작은 손바닥이 입술에 닿는다.<br>경을 그쳤다. 일행은 다른 일행이 의자를 밟고 끌어냈다. 입술에 손자국이 차갑게 남았다.`,
      win:{ exp:22, dream:3, mind:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'③ 일행 대신 손들 위에 눕는다.', k:'bond', dc:23,
      doom:{ title:'오늘의 친구', what:'손에서 손으로 실려 무대 위로 갑니다', dc:18, sec:50,
        text:`일행 옆으로 올라가 손들 위에 누웠다. 대신 데려가라고. 일행을 밀어 의자 쪽으로 떨어뜨렸다.<br><br>손들이 이쪽을 받는다. 부드럽게. 넘긴다. 앞으로. 천장 조명이 지나간다. 하나, 둘.<br>무대가 가까워진다. 무대 위에 방글이가 팔을 벌리고 서 있다. 웃는 입이 얼굴보다 길다. 손들이 이쪽을 방글이 품에 넘긴다.<br><br>스피커에서 박수가 쏟아진다. 오늘의 친구! 이쪽 이름을 부른다.`,
        dieText:`다음 날 다섯 시, 방송이 나갔다.<br><br>오늘의 친구 코너. 무대 위 아이가 두 손을 모으고 서 있다. 키가 조금 크다.<br>아이가 무엇을 읊는다. 소리가 녹음에 묻혀 안 들린다. 입 모양만 보인다. 기도하는 입이다.` },
      ok:`누우려다 손들 사이로 의자 다리 하나를 걸어 넘어뜨렸다. 쿵. 의자가 넘어지며 손들이 흩어진다.<br><br>일행이 떨어진다. 받아 냈다. 이쪽은 눕지 않았다. 대신 넘어진 의자를 다시 세워 주었다. 손들이 그 의자 밑으로 들어간다. 조용히.<br>대신 가는 것만이 지키는 것은 아니다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'분장실 — 거울 속 넷째 의자',
  x:`분장실 거울에는 의자가 넷 비친다. 진짜 의자는 셋이다.<br><br>
    거울 속 넷째 의자에 누가 앉아 있다. 하얀 분을 두드린다. 탁, 탁.<br>
    얼굴이 아직 덜 됐다. 눈 있을 자리가 비었다. 분 두드리는 손이 이쪽 일행을 하나씩 돌아본다. 눈 대신 쓸 얼굴을 고르는 것처럼.<br><br>
    거울 앞에 앉으면 고름을 받는다. 앉지 않아도 비치면 고름을 받는다.`,
  o:[
    { l:'① 거울 앞에 등을 대고 서서 경을 읽는다.', k:'steady', dc:22, wake:1,
      ok:`일행을 거울 밖으로 내보내고 거울 앞에 섰다. 거울을 등지고. 손을 모았다. 경을 읽었다.<br><br>등 뒤 거울에 이쪽 등만 비친다. 넷째 의자의 것이 이쪽 뒤통수를 본다. 얼굴이 안 보인다. 고를 수가 없다.<br>분 두드리는 소리가 느려진다. 경 소리에 맞춰. 그리고 멈춘다. 일행이 다 빠져나갈 때까지 읽었다.<br><br>등 하나로 거울을 막았다. 얼굴을 내주지 않는 것도 기도다. 마음이 등만큼 넓어졌다.`,
      ng:`읽는데 거울 속에서 손이 나와 이쪽 어깨를 짚는다. 돌아보라고. 부드럽게.<br><br>목이 돌아간다. 저절로. 반쯤 돌았을 때 일행이 뒤에서 머리를 감싸 쥐었다.<br>끌려 나왔다. 목이 한참 뻐근했다. 어깨에 분가루가 손 모양으로 남았다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 의상실 천으로 거울을 덮는다.', k:'fix', dc:21,
      ok:`옆방 의상실에서 큰 천을 끌어 왔다. 거울 위쪽 전구에 걸쳐 덮었다.<br><br>천 너머에서 분 두드리는 소리가 멈춘다. 그리고 천을 안쪽에서 더듬는 소리. 얼굴을 찾는다. 천에 얼굴 모양이 볼록하게 솟았다 꺼진다.<br>그사이 다 빠져나왔다.`,
      ng:`덮는데 천이 거울에 빨려 들어간다. 반쯤.<br><br>거울 속으로 들어간 천을 넷째 의자의 것이 받는다. 얼굴에 쓴다. 천 얼굴이다. 이쪽 얼굴 크기에 맞춰 접는다.<br>뛰어나왔다. 등 뒤에서 분 두드리는 소리가 다시 시작됐다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'놀이 세트 — 공 바다',
  x:`놀이 세트에 공 바다가 있다. 알록달록한 공이 허리까지 찼다.<br><br>
    일행 하나가 건너다 멈췄다. 가라앉는다고 한다. 공이 다리를 잡아당긴다고.<br>
    벌써 가슴까지다. 공은 물이 아니라서 헤엄칠 수가 없다.<br><br>
    공 사이로 작은 손이 보였다 사라진다. 여럿.`,
  o:[
    { l:'① 가장자리에 발을 박고 힘으로 팔을 뻗어 끌어낸다.', k:'break', dc:23, cost:{ might:30 },
      ok:`공 바다 가장자리 틀에 발을 박았다. 팔을 뻗어 일행 겨드랑이를 잡았다. 힘을 모아 단숨에 당겼다.<br><br>공들이 와르르 쏟아지며 일행이 빠져나온다. 다리에 작은 손 몇 개가 매달려 나왔다가 떨어진다. 공 사이로 돌아간다.<br>일행 신발 한 짝은 공 바다가 가져갔다. 그건 줬다.`,
      ng:`당기는데 공 밑에서 더 세게 당긴다. 팔이 빠질 것 같다.<br><br>반쯤 끌어내고 놓쳤다. 일행이 다시 가슴까지 잠긴다. 다른 일행이 같이 붙어 겨우 뺐다.<br>일행 다리에 작은 손자국이 수십 개 찍혀 있다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 공 위에 엎드려 무게를 나눠 다가간다.', k:'steady', dc:23,
      doom:{ title:'공 바다', what:'공 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`공 위에 엎드렸다. 무게를 넓게 나누면 안 가라앉는다. 눈밭에서 배운 법이다.<br><br>일행 쪽으로 기어갔다. 손이 닿았다. 일행을 끌어 올렸다. 일행이 이쪽 등을 밟고 가장자리로 넘어간다.<br>그만큼 이쪽이 가라앉는다. 공 사이로 작은 손들이 이쪽 팔다리를 쥔다. 놀자고. 당긴다. 공이 얼굴을 덮는다. 알록달록한 어둠이다.<br><br>공 밑은 깊다. 공 바다보다 깊다. 아래에서 웃음소리가 올라온다.`,
        dieText:`공 바다가 조용하다. 허리까지 찼다.<br><br>공 사이로 손이 보였다 사라진다. 그중 하나가 크다. 어른 손이다. 다른 손들을 하나씩 잡아 준다. 놀다 다치지 않게.<br>다음 사람이 건널 때 그 손이 다리를 붙들었다. 아주 조심스럽게.` },
      ok:`엎드리기 전에 허리에 끈을 매어 가장자리 틀에 묶었다. 그리고 공 위에 엎드려 기어갔다.<br><br>일행을 잡아 끌어 올렸다. 이쪽이 가라앉는다. 끈이 팽팽해진다. 틀이 버틴다. 일행이 끈을 타고 넘어가 이쪽을 당긴다.<br>공들이 아쉽게 와르르 흩어졌다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'송출 부스 앞 — 소금 선 위에 앉는다',
  x:`송출 부스 문 앞에 소금으로 선이 그어져 있다. 하얗고 굵다. 누가 오래전에 그었다.<br><br>
    선 너머에 부스가 있다. 선 이쪽에 인형탈들이 줄지어 서 있다. 선을 못 넘는다.<br>
    선이 군데군데 끊겼다. 끊긴 데로 인형탈 발끝이 들어온다.<br><br>
    일행이 스위치를 내릴 때까지 누가 선을 지켜야 한다.`,
  o:[
    { l:'① 끊긴 자리에 앉아 몸으로 선을 잇고 경을 읽는다.', k:'steady', dc:23, wake:1,
      ok:`끊긴 자리에 다리를 꼬고 앉았다. 소금이 무릎 밑에서 바스락거린다. 손을 모았다. 경을 읽었다.<br><br>인형탈 발끝이 이쪽 무릎 앞에서 멈춘다. 몸이 선이 됐다. 인형탈들이 앉은 사람 앞에 줄지어 선다. 웃는 얼굴로 내려다본다. 기다린다.<br>등 뒤에서 스위치가 내려가는 소리. 방송 중 등이 꺼진다. 인형탈들이 손을 흔들던 자세 그대로 멈췄다.<br><br>앉은 몸이 끊긴 선을 이었다. 몸으로 경계를 긋는 법. 앉음이 그만큼 무거워졌다.`,
      ng:`앉았는데 인형탈 하나가 무릎을 꿇는다. 이쪽 앞에. 마주 앉는다.<br><br>웃는 얼굴이 이쪽 얼굴 앞에 있다. 숨 냄새가 솜 냄새다. 경 소리가 떨린다. 떨리는 경은 선이 아니다.<br>인형탈 손이 이쪽 무릎 밑 소금을 쓸어 낸다. 일행이 스위치를 내렸을 때 무릎 밑은 비어 있었다.`,
      win:{ exp:24, dream:3, mind:8 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 선을 넘으려는 일행을 붙들어 안쪽에 세운다.', k:'bond', dc:22,
      ok:`스위치로 가는 일행 하나가 발을 헛디뎌 선 쪽으로 기운다. 어깨를 붙잡아 안쪽으로 돌려세웠다.<br><br>인형탈 손이 방금 그 사람 어깨가 있던 자리를 쥐었다 편다.<br>일행 하나하나 어깨를 짚어 부스 쪽으로 밀어 주었다. 다 들어갔다. 마지막으로 이쪽이 들어가며 소금 한 줌을 끊긴 자리에 뿌렸다.`,
      ng:`붙드는데 이쪽 발이 선을 밟는다. 소금이 흩어진다.<br><br>인형탈들이 한꺼번에 한 걸음 들어온다. 발끝이 이쪽 발등을 밟는다. 무겁다.<br>발을 빼냈다. 발등이 퍼렇게 부었다. 끊긴 자리가 하나 더 늘었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A2', t:'종탑 — 당기는 종줄',
  x:`종탑 종줄이 바닥 구멍을 지나 물속으로 내려간다. 젖었다.<br><br>
    일행 하나가 줄을 만졌다가 손목이 감겼다. 줄이 당긴다. 물 쪽으로. 한 번, 그리고 길게.<br>
    머리 위에서 종이 한 번 운다. 댕.<br><br>
    물을 지고 산을 오르내린 몸은 당기는 힘을 안다. 이건 한 사람 힘이 아니다.`,
  o:[
    { l:'① 줄을 잡고 힘으로 버텨 당김을 멈춘다.', k:'steady', dc:23, cost:{ might:30 },
      ok:`일행 손목 위쪽 줄을 두 손으로 감아쥐었다. 발을 바닥에 박고 허리를 낮췄다. 무게를 땅에 내렸다.<br><br>줄이 당긴다. 버텼다. 또 당긴다. 버텼다. 머리 위 종이 울리다 만다. 댕, 하다 멎는다.<br>당김이 느슨해진 틈에 일행이 손목을 뺐다. 줄을 놓자 물 밑으로 쑥 끌려 내려간다. 다시 팽팽해진다. 다음 손을 기다린다.`,
      ng:`버티는데 줄이 이쪽 손목도 감는다. 둘이 같이 끌려간다.<br><br>발이 구멍 가장자리에 걸린다. 머리 위에서 종이 길게 운다. 다른 일행이 칼로 줄을 끊었다.<br>끊긴 줄이 물속으로 사라진다. 손목에 줄 자국이 피멍으로 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 감긴 일행 손목의 줄을 매듭 반대로 푼다.', k:'heal', dc:22,
      ok:`당기는 힘은 버티지 않았다. 줄이 감긴 방향을 봤다. 세 바퀴, 오른쪽으로. 매듭 반대로 풀었다. 당김에 맞춰서.<br><br>당길 때 한 바퀴, 쉴 때 한 바퀴. 세 바퀴째에 손목이 빠진다. 손목이 퍼렇다. 맥은 뛴다.<br>문지르고 묶어 주었다. 줄은 혼자 물속으로 내려갔다.`,
      ng:`푸는데 줄이 바퀴를 늘린다. 풀린 만큼 다시 감는다.<br><br>손목이 퍼렇게 질린다. 일행이 비명을 지른다. 결국 칼로 끊었다. 줄과 같이 살갗이 조금 쓸렸다.<br>끊긴 줄 끝이 물속에서 한참 손목을 찾았다.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-26, spirit:-22 } },
    { l:'③ 줄을 타고 구멍 아래로 내려가 당기는 것을 본다.', k:'gaze', dc:24,
      doom:{ title:'종줄 아래', what:'종줄에 감겨 물 밑으로 끌려갑니다', dc:19, sec:45,
        text:`일행 손목을 풀어 주고 이쪽이 줄을 잡았다. 줄을 타고 구멍 아래로 내려갔다. 당기는 것이 무엇인지 보려고.<br><br>물이 차다. 아래로 갈수록 줄이 굵어진다. 줄이 아니다. 머리카락을 꼬아 만든 줄이다. 끝에 손들이 매달려 있다. 다 당기고 있다. 종을 치려고.<br>손들이 이쪽을 본다. 손이 하나 더 왔다고 반긴다. 이쪽 손을 줄에 감아 준다. 같이 당기자고. 위에서 종이 운다. 댕.<br><br>숨이 다한다. 손이 줄에서 안 떨어진다.`,
        dieText:`아침 일곱 시가 되자 종이 울렸다. 일곱 번.<br><br>줄은 물 밑에서 당겨졌다. 당기는 손이 하나 늘었다. 무거운 것을 오래 당겨 본 손이다.<br>그 손이 당길 때 종소리가 조금 더 깊다.` },
      ok:`줄을 타고 몇 발만 내려갔다. 머리는 물 밖에 두고 줄을 내려다봤다.<br><br>줄이 아래로 갈수록 굵어진다. 머리카락을 꼬았다. 더 내려가지 않았다. 볼 만큼 봤다.<br>올라와 일행 손목을 풀고, 줄에 매듭을 지어 창틀 고리에 걸었다. 당길 때마다 고리가 버틴다. 종이 울리지 않았다.`,
      win:{ exp:22, dream:3, spirit:8 } }
  ] },

{ at:'A2', t:'기숙사 — 열두 침대의 잠자리 기도',
  x:`기숙사 방에 침대가 열둘이다. 밤 아홉 시 점호가 끝난 뒤다.<br><br>
    빈 침대마다 작은 목소리가 기도한다. 소곤소곤. 엄마 아빠 건강하게 해 주세요. 내일은 집에 가게 해 주세요.<br>
    몇 해째 같은 기도다. 아무도 들어 주지 않은 기도.<br><br>
    기도하는 사람은 남의 기도를 그냥 지나치지 못한다.`,
  o:[
    { l:'① 침대 하나하나 곁에 서서 끝까지 들어 준다.', k:'bond', dc:22, wake:1,
      ok:`첫 침대 곁에 섰다. 기도가 끝날 때까지 들었다. 끝에 한마디 보탰다. 들었어요.<br><br>목소리가 멈춘다. 그리고 다시, 처음으로 다른 말을 한다. 고맙습니다. 다음 침대. 또 다음.<br>열두째 침대에서 기도가 끝나자 방이 조용하다. 열두 침대의 이불이 저마다 조금씩 반듯해진다. 잠든 모양으로.<br><br>남의 기도를 들어 주는 것으로 기도를 마쳤다. 하는 기도에서 듣는 기도로. 손 모은 마음이 한 칸 넓어졌다.`,
      ng:`듣는데 목소리 하나가 기도를 바꾼다. 아저씨도 여기 있게 해 주세요.<br><br>다른 침대들도 따라 한다. 열두 목소리가 이쪽을 위해 기도한다. 같이 있게 해 주세요.<br>방을 나왔다. 문을 닫는데 기도 소리가 문틈으로 따라 나왔다. 오래.`,
      win:{ exp:22, dream:3, mind:8 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 이름은 부르지 않고 방 가운데서 짧게 손만 모은다.', k:'steady', dc:21,
      ok:`방 가운데 서서 손을 모았다. 누구 이름도 부르지 않았다. 이름을 부르면 대답이 온다. 이 학교에서 대답은 위험하다.<br><br>짧게 모았다가 풀었다. 기도 소리들이 잠깐 멎었다가 이어진다. 조금 작게. 조금 편하게.<br>문을 닫고 나왔다. 아무도 따라오지 않았다.`,
      ng:`손을 모으는데 기도 소리가 멈춘다. 열둘 다.<br><br>침대 위 이불들이 일제히 이쪽으로 돌아눕는다. 누구세요. 점호 끝났는데.<br>대답하지 않고 나왔다. 복도에서 사감 발소리가 이쪽으로 빨라졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-26 } }
  ] },

{ at:'A2', t:'체육관 — 조회 줄의 끝',
  x:`물 밑 체육관에 줄이 서 있다. 보이지 않는 줄이다. 물이 줄 모양으로 조금씩 떨린다.<br><br>
    반별로, 번호순으로. 조회 줄이다. 맨 끝마다 빈자리가 하나씩 있다.<br>
    일행이 지나가려면 줄 끝을 지나야 한다. 빈자리 옆을.<br><br>
    빈자리 앞 물이 이쪽 일행 쪽으로 기운다. 서라고.`,
  o:[
    { l:'① 줄 끝에 서서 일행이 지나갈 동안 자리를 막는다.', k:'steady', dc:22,
      ok:`줄 끝 빈자리 바로 옆에 섰다. 자리에 서지는 않고 그 앞을 몸으로 막았다. 일행이 등 뒤로 지나간다.<br><br>빈자리 앞 물이 이쪽을 민다. 서라고. 버텼다. 무게를 바닥에 내렸다. 물속이라 몸이 뜬다. 발가락으로 바닥을 쥐었다.<br>일행이 다 지났다. 물러서자 빈자리 물이 아쉽게 출렁였다.`,
      ng:`막는데 물이 이쪽 발을 빈자리 쪽으로 민다. 한 걸음 들어갔다.<br><br>줄이 일제히 차렷한다. 물이 굳는다. 이쪽 발이 바닥에 붙는다. 번호를 부르는 소리가 물속에서 난다.<br>일행이 어깨를 잡고 빼냈다. 발목에 줄 선 자국이 남았다. 발끝을 모은 모양으로.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 빈자리마다 무엇이 비었는지 들여다본다.', k:'gaze', dc:21,
      ok:`줄 끝 빈자리마다 물 바닥을 봤다. 실내화가 한 켤레씩 놓여 있다. 가지런히.<br><br>실내화 뒤축에 이름이 있다. 다 다르다. 결석한 아이들이다. 끝까지 오지 않은 아이들. 물이 들어오던 날 다른 데 있었던 아이들.<br>빈자리는 그 아이들 자리다. 이쪽 자리가 아니다. 그걸 알고 지나가니 물이 기울지 않았다.`,
      ng:`들여다보는데 실내화 하나가 이쪽 발 크기다. 뒤축에 이름이 비었다.<br><br>쓰라고 둔 자리다. 물이 이쪽 발을 실내화 쪽으로 기울인다.<br>뒷걸음질 쳤다. 실내화가 물속에서 한 걸음 따라왔다.`,
      win:{ exp:16, dream:2, spirit:8 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A2', t:'수영장 — 다이빙대 아래',
  x:`수영장 다이빙대 아래 물에 일행 하나가 빠졌다. 허우적거린다.<br><br>
    물 밑에서 손들이 그 사람 다리를 당긴다. 그 사람이 손을 뻗는다. 위로.<br>
    다이빙대는 높다. 물가는 멀다.<br><br>
    물을 지고 산을 오른 몸은 무거운 것을 끌어 올리는 법을 안다. 우물에서 물동이를 올리듯.`,
  o:[
    { l:'① 다이빙대 끝에 엎드려 힘으로 팔을 뻗어 건진다.', k:'break', dc:23, cost:{ might:25 },
      ok:`다이빙대 끝에 엎드려 발을 난간에 걸었다. 팔을 아래로 뻗었다. 일행 손목을 잡았다. 힘을 모아 단숨에 끌어 올렸다.<br><br>물에서 그 사람이 빠져나온다. 다리에 매달렸던 손들이 하나씩 떨어진다. 물 위로 손가락 끝들이 아쉽게 솟았다 가라앉는다.<br>다이빙대 위에서 둘이 같이 숨을 몰아쉬었다.`,
      ng:`끌어 올리는데 아래에서 더 세게 당긴다. 이쪽 몸이 다이빙대 끝으로 미끄러진다.<br><br>발이 난간에서 빠질 뻔했다. 일행 손목을 놓치지 않았다. 다른 일행이 이쪽 발목을 붙들었다.<br>셋이 줄줄이 매달려 겨우 끌어 올렸다. 어깨가 빠졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 물가 끝에서 장대를 내밀고 기다린다.', k:'steady', dc:22,
      ok:`물가 끝으로 달려가 구조 장대를 내렸다. 그 사람 쪽으로 내밀었다. 닿을 때까지 기다렸다.<br><br>그 사람이 허우적대다 장대 끝을 잡는다. 당겼다. 물 밑 손들이 장대도 당긴다. 버텼다.<br>그 사람이 물가에 닿았다. 장대는 물이 가져갔다. 그건 줬다.`,
      ng:`장대를 내미는데 그 사람이 반대로 허우적댄다. 물이 그 사람을 밀어낸다.<br><br>장대 끝이 닿지 않는다. 한참 기다렸다. 그 사람이 가라앉았다 떠오른다. 세 번째에 장대를 잡았다.<br>건져 올렸을 때 그 사람 입술이 파랬다. 숨은 돌아왔다. 늦게.`,
      win:{ exp:18, dream:2, hp:8 }, lose:{ hp:-24, spirit:-24 } },
    { l:'③ 다이빙대에서 뛰어들어 아래에서 받쳐 올린다.', k:'bond', dc:24,
      doom:{ title:'다이빙대', what:'받쳐 올린 만큼 물 밑으로 가라앉습니다', dc:19, sec:45,
        text:`뛰어들었다. 물이 차다. 그 사람 아래로 들어가 어깨로 받쳤다. 그 사람이 이쪽 어깨를 밟고 올라간다. 물 밖으로.<br><br>그만큼 이쪽이 내려간다. 물 밑 손들이 이쪽 다리를 받는다. 하나 놓으면 하나를 잡는다. 공평하다.<br>숨이 짧다. 위를 보니 수면이 멀다. 빛이 흔들린다. 손들이 이쪽을 바닥으로 데려간다. 레인 줄 아래로.<br><br>남을 밟고 올라가게 하는 몸은 잡을 손이 없다.`,
        dieText:`건져진 사람이 물가에서 돌아봤다. 수면이 평평했다.<br><br>레인 줄에 부표가 하나 늘었다. 다른 것보다 낮게 떠 있다. 무거운 것을 받치는 모양으로.<br>그 뒤로 이 수영장에 빠진 사람은 이상하게 발밑이 단단했다고 한다. 누가 아래에서 받친 것처럼.` },
      ok:`뛰어들기 전에 다이빙대 난간에 끈을 매고 허리에 감았다. 그리고 뛰었다.<br><br>그 사람 아래로 들어가 받쳤다. 그 사람이 밟고 올라간다. 이쪽이 내려간다. 손들이 다리를 잡는다. 끈이 팽팽해진다. 위에서 일행이 당긴다.<br>손들이 놓쳤다. 끈을 타고 올라왔다. 다리에 손자국이 가득하다. 그래도 둘 다 물 밖이다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'무대 뒤 — 결석생 명단',
  x:`강당 무대 뒤에 명단이 붙어 있다. 결석생 명단. 이름이 몇 줄이다.<br><br>
    물이 들어오던 날 학교에 없었던 아이들이다. 출석부에 그 아이들 칸만 비어 있다. 몇 해째.<br>
    무대 뒤 바닥에 명찰들이 가지런히 놓였다. 결석생 명찰이다. 주인 없이.<br><br>
    다른 명찰들은 다 가슴에 달려 있을 것이다. 물 밑에서.`,
  o:[
    { l:'① 결석생 이름마다 손을 모아 기도한다.', k:'steady', dc:22, wake:1,
      ok:`명단 앞에 앉았다. 이름을 하나씩 읽고 손을 모았다. 살아서 결석한 아이들에게. 지금은 어른이 되었을 아이들에게.<br><br>다 읽고 나니 무대 뒤가 조용하다. 명찰들이 물에 젖지 않은 채 바닥에 놓여 있다. 젖지 않은 것은 이 학교에서 처음이다. 아무도 데려가지 못한 이름들이다.<br>명찰 하나를 집어 명단 옆에 꽂았다. 결석, 이라고 덧붙여 적었다.<br><br>여기 없는 사람을 위해 손을 모았다. 기도가 닿는 자리가 눈앞을 넘어갔다. 그 자리가 멀어질수록 앉음이 단단해진다.`,
      ng:`읽는데 명단 이름이 하나씩 젖는다. 읽을 때마다.<br><br>젖은 이름이 번진다. 무대 바닥 명찰도 젖는다. 물 밑에서 출석 부르는 소리가 올라온다. 그 이름들을.<br>읽기를 멈췄다. 젖은 이름 셋이 다시 마르지 않았다.`,
      win:{ exp:24, dream:3, spirit:8 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 명찰들을 반별로 정리해 명단 아래에 단다.', k:'fix', dc:21,
      ok:`명찰을 주워 반별로, 번호순으로 정리했다. 명단 아래 게시판 핀에 하나씩 꽂았다.<br><br>다 꽂고 나니 명단이 완성된다. 이름 옆에 명찰. 결석생이 결석생 자리에 있다.<br>무대 커튼 너머에서 누가 그걸 보고 한숨을 쉰다. 출석부를 덮는 소리가 났다.`,
      ng:`꽂다가 하나를 잘못 꽂았다. 다른 반이다.<br><br>명찰이 핀에서 빠져 떨어진다. 바닥 물 위에 뜬다. 물이 명찰을 끌고 무대 밑으로 간다.<br>쫓아가다 무대 밑 틈에 손이 끼었다. 손등이 찢어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] }

]);
